// ─── Email typo detection ───────────────────────────────────────────────
// Catches common TLD + provider-name typos before we burn a Supabase OTP
// send on a dead address. Returns either null (looks fine) or a corrected
// suggestion string. Conservative on purpose — only suggests when we're
// very confident, so we don't second-guess legitimate domains.
var EMAIL_TLD_TYPOS = {
  'con': 'com', 'cmo': 'com', 'comm': 'com', 'cim': 'com', 'cm': 'com',
  'ner': 'net', 'nett': 'net',
  'orgg': 'org', 'ogr': 'org',
  'edi': 'edu', 'eud': 'edu',
  'goc': 'gov',
  'cok': 'co'
};
var EMAIL_PROVIDER_TYPOS = {
  'gmial.com': 'gmail.com', 'gmai.com': 'gmail.com', 'gmail.co': 'gmail.com',
  'gmaill.com': 'gmail.com', 'gnail.com': 'gmail.com', 'gmil.com': 'gmail.com',
  'hotmial.com': 'hotmail.com', 'hotmai.com': 'hotmail.com',
  'hotmal.com': 'hotmail.com', 'hotmali.com': 'hotmail.com',
  'yhaoo.com': 'yahoo.com', 'yaho.com': 'yahoo.com', 'yahooo.com': 'yahoo.com',
  'yahoo.co': 'yahoo.com',
  'outlok.com': 'outlook.com', 'outloook.com': 'outlook.com',
  'icoud.com': 'icloud.com', 'iclud.com': 'icloud.com', 'icloud.co': 'icloud.com'
};
function suggestEmailTypo(email) {
  if (!email || email.indexOf('@') < 0) return null;
  var parts = email.toLowerCase().split('@');
  if (parts.length !== 2 || !parts[1]) return null;
  var local = parts[0];
  var domain = parts[1];
  // Whole-domain provider match wins first.
  if (EMAIL_PROVIDER_TYPOS[domain]) {
    return local + '@' + EMAIL_PROVIDER_TYPOS[domain];
  }
  // Otherwise look at just the TLD (after last dot).
  var lastDot = domain.lastIndexOf('.');
  if (lastDot < 0) return null;
  var tld = domain.slice(lastDot + 1);
  if (EMAIL_TLD_TYPOS[tld]) {
    return local + '@' + domain.slice(0, lastDot + 1) + EMAIL_TLD_TYPOS[tld];
  }
  return null;
}
function showEmailSuggestion(suggestion) {
  var box = document.getElementById('auth-email-suggestion');
  var btn = document.getElementById('auth-email-suggestion-btn');
  if (!box || !btn) return;
  btn.textContent = suggestion;
  box.style.display = 'block';
}
function clearEmailSuggestion() {
  var box = document.getElementById('auth-email-suggestion');
  if (box) box.style.display = 'none';
}
function acceptEmailSuggestion() {
  var btn = document.getElementById('auth-email-suggestion-btn');
  var input = document.getElementById('auth-email');
  if (!btn || !input) return;
  input.value = btn.textContent;
  clearEmailSuggestion();
  input.focus();
}

// Translate a Supabase auth error into a short, kind, action-able toast.
// Inputs we've seen in the wild on signup / OTP verify:
//   - over_email_send_rate_limit / email_send_rate_limit_exceeded (HTTP 429)
//   - email_address_invalid / signup_disabled (HTTP 403)
//   - otp_expired / token_expired / expired_token
//   - invalid_otp / token_not_found / invalid_grant
function _translateAuthError(err) {
  if (!err) return 'Something went wrong \u2014 please try again.';
  var code = String(err.code || err.error || err.name || '').toLowerCase();
  var msg  = String(err.message || '').toLowerCase();
  var status = err.status || 0;
  var hay = code + ' ' + msg;
  if (hay.indexOf('rate_limit') !== -1 || hay.indexOf('rate limit') !== -1 || status === 429) {
    return 'Too many tries \u2014 please wait 60 seconds and try again.';
  }
  if (hay.indexOf('otp_expired') !== -1 || hay.indexOf('expired') !== -1) {
    return 'That code expired \u2014 tap Resend code to get a fresh one.';
  }
  if (hay.indexOf('invalid_otp') !== -1 || hay.indexOf('token_not_found') !== -1 || hay.indexOf('invalid_grant') !== -1 || hay.indexOf('invalid token') !== -1) {
    return 'That code doesn\u2019t match \u2014 try again or request a new one.';
  }
  if (hay.indexOf('email_address_invalid') !== -1 || hay.indexOf('invalid email') !== -1) {
    return 'That email doesn\u2019t look right \u2014 please check the spelling.';
  }
  if (status === 403 || hay.indexOf('signup_disabled') !== -1 || hay.indexOf('not allowed') !== -1) {
    return 'We can\u2019t send to that address right now \u2014 try a different email or contact betsy@getwellet.com.';
  }
  // Fall back to Supabase’s own message if it's user-friendly enough.
  return err.message ? ('Couldn\u2019t sign you in: ' + err.message) : 'Couldn\u2019t sign you in \u2014 please try again.';
}

// Build the attribution payload we attach to signInWithOtp.options.data.
// Lands on auth.users.user_metadata so the rest of the app (and analytics) can
// see where a signup came from — specifically used by the /me bypass below.
function _buildSignupAttribution() {
  var params = {};
  try {
    var search = new URLSearchParams(window.location.search || '');
    search.forEach(function(v, k) { params[k] = v; });
  } catch (e) {}
  var landing = '/';
  try { landing = window.location.pathname || '/'; } catch (e) {}
  // signup_location: explicit ?signup_location=... wins, then landing-path heuristic.
  var sig = params.signup_location || '';
  if (!sig) {
    if (landing === '/me' || landing === '/me/' || landing.indexOf('/me') === 0) sig = 'me_landing';
    else if (landing === '/' || landing === '/index.html') sig = 'caregiver_landing';
    else sig = 'unknown';
  }
  return {
    signup_location: sig,
    landing_page: landing,
    entry_path: landing + (window.location.search || ''),
    referrer: (document.referrer || '').slice(0, 500),
    utm_source: params.utm_source || null,
    utm_medium: params.utm_medium || null,
    utm_campaign: params.utm_campaign || null,
    utm_content: params.utm_content || null,
    utm_term: params.utm_term || null
  };
}

async function sendMagicLink() {
  var email = document.getElementById('auth-email').value.trim();
  if (!email) { showToast('Please enter your email'); return; }

  // Catch the .con / gmial.com class of typos before we send.
  var suggestion = suggestEmailTypo(email);
  if (suggestion && suggestion !== email.toLowerCase()) {
    showEmailSuggestion(suggestion);
    return;
  }
  clearEmailSuggestion();

  var btn = document.getElementById('auth-send-btn');
  btn.disabled = true;
  btn.textContent = 'Sending…';

  var sentEmail = document.getElementById('auth-sent-email');
  if (sentEmail) sentEmail.textContent = email;
  // Remember the email for the OTP verify step and the expired-session banner.
  try { localStorage.setItem('wellet_last_signin_email', email); } catch (e) {}
  // Attribution: capture URL params + landing page so signups know where they came from.
  // Persisted to auth.users.user_metadata via options.data — used by /me bypass and analytics.
  var _attribution = _buildSignupAttribution();
  try { localStorage.setItem('wellet_signup_attribution', JSON.stringify(_attribution)); } catch (e) {}
  var { error } = await db.auth.signInWithOtp({
    email: email,
    options: { emailRedirectTo: 'https://mywellet.com', shouldCreateUser: true, data: _attribution }
  });
  if (error) {
    showToast(_translateAuthError(error));
    btn.disabled = false;
    btn.innerHTML = 'Send 6-digit code <i data-lucide="arrow-right" style="width:16px;height:16px;"></i>';
    initIcons();
  } else {
    document.getElementById('auth-form-state').style.display = 'none';
    document.getElementById('auth-sent-state').style.display = 'block';
    // Reset the send button label for next time and focus the code input.
    btn.disabled = false;
    btn.innerHTML = 'Send 6-digit code <i data-lucide="arrow-right" style="width:16px;height:16px;"></i>';
    var codeInput = document.getElementById('auth-code');
    if (codeInput) { codeInput.value = ''; setTimeout(function(){ codeInput.focus(); }, 50); }
    var verifyBtn = document.getElementById('auth-verify-btn');
    if (verifyBtn) verifyBtn.disabled = true;
    initIcons();
  }
}

// ── OTP code entry (web) ────────────────────────────────────────────────
function handleOtpCodeInput(e) {
  var input = e && e.target ? e.target : document.getElementById('auth-code');
  if (!input) return;
  // Strip non-digits, cap at 6.
  var cleaned = (input.value || '').replace(/[^0-9]/g, '').slice(0, 6);
  if (cleaned !== input.value) input.value = cleaned;
  var verifyBtn = document.getElementById('auth-verify-btn');
  if (verifyBtn) verifyBtn.disabled = cleaned.length !== 6;
  // Auto-submit when 6 digits entered.
  if (cleaned.length === 6) {
    verifyAuthCode();
  }
}

async function verifyAuthCode() {
  var input = document.getElementById('auth-code');
  var code = input ? (input.value || '').trim() : '';
  if (code.length !== 6) { showToast('Enter all 6 digits'); return; }
  var email = '';
  try { email = localStorage.getItem('wellet_last_signin_email') || ''; } catch (e) {}
  if (!email) {
    showToast('Session expired — please enter your email again');
    showAuthFormState();
    return;
  }
  var btn = document.getElementById('auth-verify-btn');
  if (btn) { btn.disabled = true; btn.textContent = 'Verifying…'; }
  var { data, error } = await db.auth.verifyOtp({
    email: email,
    token: code,
    type: 'email'
  });
  if (error) {
    showToast(_translateAuthError(error));
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = 'Verify code <i data-lucide="arrow-right" style="width:16px;height:16px;"></i>';
      initIcons();
    }
    if (input) { input.value = ''; input.focus(); }
    return;
  }
  // Success — Supabase has set the session. Hard-reload so the app picks it up cleanly.
  // window.location.href = 'https://mywellet.com' was a soft-nav on Chrome iOS that
  // skipped re-running initApp(), stranding the user on the login screen even though
  // the session was written to localStorage. window.location.reload() forces a fresh
  // document load that re-runs Supabase's session bootstrap.
  if (btn) btn.textContent = 'Signed in';
  setTimeout(function(){ window.location.reload(); }, 200);
}

async function resendAuthCode() {
  var email = '';
  try { email = localStorage.getItem('wellet_last_signin_email') || ''; } catch (e) {}
  if (!email) {
    showToast('Please enter your email again');
    showAuthFormState();
    return;
  }
  var resend = document.getElementById('auth-resend-btn');
  if (resend) { resend.disabled = true; resend.textContent = 'Sending…'; }
  // Reuse attribution from the original send so resends don't blow it away.
  var _attribution = {};
  try { _attribution = JSON.parse(localStorage.getItem('wellet_signup_attribution') || '{}'); } catch (e) {}
  if (!_attribution || !_attribution.signup_location) { _attribution = _buildSignupAttribution(); }
  var { error } = await db.auth.signInWithOtp({
    email: email,
    options: { emailRedirectTo: 'https://mywellet.com', shouldCreateUser: true, data: _attribution }
  });
  if (error) {
    showToast(_translateAuthError(error));
  } else {
    showToast('New code sent');
  }
  if (resend) {
    // 30s cooldown so the user can’t spam Supabase.
    var seconds = 30;
    resend.textContent = 'Resend in ' + seconds + 's';
    var t = setInterval(function(){
      seconds -= 1;
      if (seconds <= 0) {
        clearInterval(t);
        resend.disabled = false;
        resend.textContent = 'Resend code';
      } else {
        resend.textContent = 'Resend in ' + seconds + 's';
      }
    }, 1000);
  }
}

function showAuthFormState() {
  document.getElementById('auth-form-state').style.display = 'block';
  document.getElementById('auth-sent-state').style.display = 'none';
  var reveal = document.getElementById('auth-signin-reveal');
  var toggle = document.getElementById('auth-signin-toggle');
  if (reveal) reveal.style.display = 'none';
  if (toggle) toggle.style.display = '';
  initIcons();
}

