// ── CARESIGNALS HELPERS ──────────────────────────────────────────────────────
function buildSparkline(values, width, height, color) {
  var max = Math.max.apply(null, values);
  var min = Math.min.apply(null, values);
  var range = max - min || 1;
  var step = width / (values.length - 1);
  var points = values.map(function(v, i) {
    return (i * step) + ',' + (height - ((v - min) / range) * height);
  }).join(' ');
  return '<svg width="' + width + '" height="' + height + '" viewBox="0 0 ' + width + ' ' + height + '">'
    + '<polyline fill="none" stroke="' + color + '" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" points="' + points + '"/>'
    + '</svg>';
}

// Richer 7-day chart for the rhythm cards: area fill + value labels on max
// day, dots on each non-zero day, and day-of-week ticks underneath. `values`
// is the 7-day trend (oldest -> newest). `color` is the stroke color; we
// derive a soft fill from it.
function buildRhythmChart(values, width, height, color, unitSuffix) {
  var W = width;
  var H = height;
  var padL = 6, padR = 6, padT = 16, padB = 18;
  var chartW = W - padL - padR;
  var chartH = H - padT - padB;
  var nonZero = (values || []).filter(function(v){ return v > 0; });
  if (nonZero.length === 0) {
    return '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" aria-hidden="true"></svg>';
  }
  var max = Math.max.apply(null, values);
  var min = Math.min.apply(null, nonZero);
  // Pad the visual range so the line never hugs the top/bottom.
  var rangeRaw = max - min;
  var pad = rangeRaw > 0 ? rangeRaw * 0.15 : Math.max(1, max * 0.1);
  var lo = Math.max(0, min - pad);
  var hi = max + pad;
  var range = hi - lo || 1;
  var n = values.length;
  var stepX = n > 1 ? chartW / (n - 1) : 0;
  function px(i){ return padL + i * stepX; }
  function py(v){ return padT + chartH - ((v - lo) / range) * chartH; }
  // Line points and area points.
  var linePts = [];
  var areaPts = [];
  for (var i = 0; i < n; i++) {
    var v = values[i];
    if (v > 0) {
      linePts.push(px(i) + ',' + py(v));
      areaPts.push(px(i) + ',' + py(v));
    }
  }
  if (linePts.length === 0) {
    return '<svg width="' + W + '" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" aria-hidden="true"></svg>';
  }
  // Close the area path along the bottom.
  var firstX = parseFloat(linePts[0].split(',')[0]);
  var lastX = parseFloat(linePts[linePts.length-1].split(',')[0]);
  var baseY = padT + chartH;
  var areaPath = 'M' + firstX + ',' + baseY + ' L' + areaPts.join(' L') + ' L' + lastX + ',' + baseY + ' Z';
  // Day labels: oldest = 6 days ago, newest = today.
  var dayNames = ['S','M','T','W','T','F','S'];
  var today = new Date();
  var labels = [];
  for (var d = n - 1; d >= 0; d--) {
    var dt = new Date(today.getFullYear(), today.getMonth(), today.getDate() - d);
    labels.push(dayNames[dt.getDay()]);
  }
  // Find max-value index for the headline label.
  var maxIdx = 0;
  for (var mi = 0; mi < n; mi++) { if (values[mi] >= values[maxIdx]) maxIdx = mi; }
  // Build SVG.
  var svg = '<svg width="100%" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none" aria-hidden="true" style="display:block;">';
  // Soft grid baseline.
  svg += '<line x1="' + padL + '" y1="' + (padT + chartH) + '" x2="' + (W - padR) + '" y2="' + (padT + chartH) + '" stroke="#E5DFD2" stroke-width="1"/>';
  // Area fill.
  svg += '<path d="' + areaPath + '" fill="' + color + '" fill-opacity="0.12"/>';
  // Line.
  svg += '<polyline fill="none" stroke="' + color + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="' + linePts.join(' ') + '"/>';
  // Dots on each non-zero day.
  for (var di = 0; di < n; di++) {
    if (values[di] > 0) {
      svg += '<circle cx="' + px(di) + '" cy="' + py(values[di]) + '" r="' + (di === maxIdx ? 3 : 2) + '" fill="' + color + '"/>';
    }
  }
  // Max-value label.
  var maxLabel = (values[maxIdx] >= 1000) ? Math.round(values[maxIdx]/1000*10)/10 + 'k' : Math.round(values[maxIdx]);
  if (unitSuffix) maxLabel += unitSuffix;
  var labelX = Math.max(padL + 14, Math.min(W - padR - 14, px(maxIdx)));
  svg += '<text x="' + labelX + '" y="' + (py(values[maxIdx]) - 6) + '" text-anchor="middle" font-family="DM Sans, system-ui, sans-serif" font-size="10" font-weight="600" fill="#3D3530">' + maxLabel + '</text>';
  // Day-of-week ticks.
  for (var li = 0; li < n; li++) {
    var isToday = (li === n - 1);
    svg += '<text x="' + px(li) + '" y="' + (H - 4) + '" text-anchor="middle" font-family="DM Sans, system-ui, sans-serif" font-size="9" fill="' + (isToday ? '#3D3530' : '#9B8F7E') + '" font-weight="' + (isToday ? '600' : '400') + '">' + labels[li] + '</text>';
  }
  svg += '</svg>';
  return svg;
}

function buildProgressRing(percent, size, color) {
  var r = (size - 6) / 2;
  var circ = 2 * Math.PI * r;
  var offset = circ - (percent / 100) * circ;
  return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 ' + size + ' ' + size + '">'
    + '<circle cx="' + size/2 + '" cy="' + size/2 + '" r="' + r + '" fill="none" stroke="#eee" stroke-width="4"/>'
    + '<circle cx="' + size/2 + '" cy="' + size/2 + '" r="' + r + '" fill="none" stroke="' + color + '" stroke-width="4" '
    + 'stroke-dasharray="' + circ + '" stroke-dashoffset="' + offset + '" stroke-linecap="round" '
    + 'transform="rotate(-90 ' + size/2 + ' ' + size/2 + ')"/>'
    + '</svg>';
}

function fmtMin(m) {
  if (m < 60) return m + 'm';
  var h = Math.floor(m / 60);
  var r = m % 60;
  return r ? h + 'h ' + r + 'm' : h + 'h';
}

function buildSleepBar(sleep) {
  var total = sleep.deep + sleep.core + sleep.rem + sleep.awake;
  if (!total) return '';
  var pctDeep = (sleep.deep / total * 100).toFixed(1);
  var pctCore = (sleep.core / total * 100).toFixed(1);
  var pctRem = (sleep.rem / total * 100).toFixed(1);
  var pctAwake = (sleep.awake / total * 100).toFixed(1);
  var html = '<div class="sleep-bar">'
    + '<div class="sleep-bar-seg sleep-bar-seg--deep" style="width:' + pctDeep + '%"></div>'
    + '<div class="sleep-bar-seg sleep-bar-seg--core" style="width:' + pctCore + '%"></div>'
    + '<div class="sleep-bar-seg sleep-bar-seg--rem" style="width:' + pctRem + '%"></div>'
    + '<div class="sleep-bar-seg sleep-bar-seg--awake" style="width:' + pctAwake + '%"></div>'
    + '</div>';
  html += '<div class="sleep-legend">'
    + '<span class="sleep-legend-item"><span class="sleep-legend-dot" style="background:#4338CA"></span>' + fmtMin(sleep.deep) + ' deep</span>'
    + '<span class="sleep-legend-item"><span class="sleep-legend-dot" style="background:#3B6EA5"></span>' + fmtMin(sleep.core) + ' core</span>'
    + '<span class="sleep-legend-item"><span class="sleep-legend-dot" style="background:#0D9488"></span>' + fmtMin(sleep.rem) + ' REM</span>'
    + '<span class="sleep-legend-item"><span class="sleep-legend-dot" style="background:#D1D5DB"></span>' + fmtMin(sleep.awake) + ' awake</span>'
    + '</div>';
  return html;
}

function getMedStatus(timeStr, now, cabinetHour) {
  var parts = timeStr.split(':');
  var schedH = parseInt(parts[0], 10);
  var schedM = parseInt(parts[1], 10);
  var schedMin = schedH * 60 + schedM;
  var nowMin = now.getHours() * 60 + now.getMinutes();
  var diff = schedMin - nowMin;
  if (diff <= 0 && diff > -30) return 'due';
  if (diff > 0 && diff <= 30) return 'due';
  if (schedMin < nowMin) {
    if (cabinetHour >= 0 && Math.abs(schedH - cabinetHour) <= 1) return 'taken';
    return 'missed';
  }
  return 'upcoming';
}

function formatTime12(timeStr) {
  var parts = timeStr.split(':');
  var h = parseInt(parts[0], 10);
  var m = parts[1];
  var ampm = h >= 12 ? 'PM' : 'AM';
  var h12 = h % 12 || 12;
  return h12 + ':' + m + ' ' + ampm;
}

// ── RENDER SIGNALS VIEW ──────────────────────────────────────────────────────
// Client-side cache for Signals data, keyed by personId. TTL 60s.
var _signalsCache = {};
var _SIGNALS_CACHE_TTL_MS = 60 * 1000;

function _buildDeviceCardsHtml(activeConns) {
  var html = '<div class="terra-devices-section">';
  html += '<div class="terra-devices-title">Connected Devices</div>';
  for (var ci = 0; ci < activeConns.length; ci++) {
    var conn = activeConns[ci];
    var providerName = conn.provider ? conn.provider.charAt(0).toUpperCase() + conn.provider.slice(1).toLowerCase() : 'Unknown';
    var statusDotClass = conn.status === 'active' ? 'terra-status-dot--active' : 'terra-status-dot--inactive';
    var connDate = conn.connected_at ? new Date(conn.connected_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '';
    var lastData = conn.last_data_at ? 'Last data: ' + new Date(conn.last_data_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) + ' at ' + new Date(conn.last_data_at).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) : 'No data yet';
    html += '<div class="terra-device-card">';
    html += '<div class="terra-device-icon"><i data-lucide="watch"></i></div>';
    html += '<div class="terra-device-info">';
    html += '<div class="terra-device-name"><span class="terra-status-dot ' + statusDotClass + '"></span> ' + escHtml(providerName) + '</div>';
    html += '<div class="terra-device-meta">' + escHtml(lastData);
    if (connDate) html += ' \u00b7 Connected ' + escHtml(connDate);
    html += '</div></div>';
    html += '<button class="terra-disconnect-btn" onclick="disconnectTerra(\'' + conn.id + '\')">Disconnect</button>';
    html += '</div>';
  }
  html += '<button class="terra-add-btn" onclick="openTerraConnect()"><i data-lucide="plus" style="width:14px;height:14px;"></i> Connect another device</button>';
  html += '<div class="terra-poweredby">Wearables powered by <a href="https://tryterra.co" target="_blank" rel="noopener noreferrer">Terra</a></div>';
  html += '</div>';
  return html;
}

async function renderSignalsView() {
  var el = document.getElementById('view-signals');
  if (!el) return;
  console.log('[Signals] renderSignalsView called, isDemoMode:', isDemoMode, 'currentPersonId:', currentPersonId);

  var data = isDemoMode ? DEMO_CARESIGNALS : null;

  if (!data) {
    var sigFirstName = getPersonFirstName();
    // Capture the personId at render-start so an in-flight async load can
    // detect if the user has since switched people. Without this guard, a
    // slow loadTerraConnections from a prior person could complete after a
    // switch and (a) paint stale data, (b) write into the new person's
    // cache slot — the bug that forced a hard refresh after switching.
    var startPersonId = currentPersonId;
    var cacheKey = startPersonId || '_nopid';
    var cached = _signalsCache[cacheKey];
    var cacheFresh = cached && (Date.now() - cached.ts) < _SIGNALS_CACHE_TTL_MS;

    // 1) Paint from cache instantly if we have it, then refresh in background.
    if (cacheFresh) {
      console.log('[Signals] paint from cache');
      _paintSignals(el, sigFirstName, cached.activeConns, cached.terraData);
    } else {
      // Show lightweight shell so the header appears immediately instead of a blank screen.
      el.innerHTML = '<div class="signals-view">'
        + '<header class="view-header">'
        + '<p class="view-header__eyebrow">Loading\u2026</p>'
        + '<h1 class="view-header__title">CareSignals</h1>'
        + '<p class="view-header__lede">Daily rhythms from ' + escHtml(sigFirstName) + '\u2019s wearables, sensors, and medications \u2014 patterns you might miss.</p>'
        + '</header>'
        + '<div class="terra-loading"><i data-lucide="loader" style="width:20px;height:20px;animation:spin 1s linear infinite;"></i>'
        + '<div style="margin-top:8px;">Loading devices\u2026</div></div></div>';
      initIcons();
    }

    // 2) Fetch connections + data in parallel with a shorter 4s timeout.
    var conns = [];
    var terraData = null;
    if (currentPersonId) {
      try {
        var connsTimeout = new Promise(function(resolve) { setTimeout(function() { resolve([]); }, 4000); });
        var dataTimeout = new Promise(function(resolve) { setTimeout(function() { resolve(null); }, 4000); });
        var results = await Promise.all([
          Promise.race([loadTerraConnections(currentPersonId), connsTimeout]),
          Promise.race([loadTerraData(currentPersonId).catch(function(e){ console.error('[Signals] loadTerraData error:', e); return null; }), dataTimeout])
        ]);
        conns = results[0] || [];
        terraData = results[1] || null;
      } catch(e) {
        console.error('Signals load error:', e);
      }
    }
    console.log('[Signals] connections loaded:', conns.length, 'data:', terraData ? 'yes' : 'no');
    var activeConns = conns.filter(function(c){ return c.status === 'active'; });

    // If the user switched people while we were loading, drop this result
    // entirely — don't paint stale data and don't poison the cache.
    if (currentPersonId !== startPersonId) {
      console.log('[Signals] person switched during load, discarding result for', startPersonId);
      return;
    }

    // Update cache (keyed on the person we actually loaded for)
    _signalsCache[cacheKey] = { ts: Date.now(), activeConns: activeConns, terraData: terraData };

    // 3) Repaint with fresh data (unless the view has since navigated away).
    if (document.getElementById('view-signals') !== el) return;
    _paintSignals(el, sigFirstName, activeConns, terraData);
    return;
  }

  // Demo-mode path falls through to original renderer below.
  return _renderSignalsDemo(el, data, getPersonFirstName());
}

// Invalidate the cache whenever a connection changes (add/disconnect) so the
// next render reflects reality.
function invalidateSignalsCache(personId) {
  if (personId) { delete _signalsCache[personId]; }
  else { _signalsCache = {}; }
}

// ── CareSignals v2 helpers ──────────────────────────────────────────────────
// Pull the user's most-chartable EHR signals (BP, weight, common labs, active
// meds) so CareSignals has something to surface even when no Apple Watch /
// wearable is connected. This is what answers "why would I add a device?" —
// once you see your own BP trending over years, the value of adding daily
// readings via a wearable becomes obvious.
//
// Returns:
//   {
//     bp:    { systolic: [...], diastolic: [...], dates: [...], latest, summary }
//     weight:{ values: [...], dates: [...], latest, unit, summary }
//     labs:  [{ name, code, values:[], dates:[], unit, range, latest, latestStatus }, ...]
//     meds:  [{ name, dose, startDate }, ...]
//   }
// All keys optional — caller renders only what's populated.
async function _loadEhrTrends(personId) {
  if (!personId || !db) return null;
  var out = { bp: null, weight: null, labs: [], meds: [] };
  try {
    var loads = await Promise.all([
      // Vitals — last 60 months so BP/weight trends have shape even for
      // loved ones with sparser chronic-monitoring schedules.
      db.from('vitals')
        .select('vital_type, value, unit, effective_date')
        .eq('person_id', personId)
        .gte('effective_date', new Date(Date.now() - 60 * 30 * 24 * 60 * 60 * 1000).toISOString())
        .order('effective_date', { ascending: true })
        .limit(500)
        .then(function(r){ return (r && r.data) || []; })
        .catch(function(e){ console.warn('[EHR trends] vitals error', e); return []; }),
      // Labs — last 60 months, numeric only. The wider window lets liver
      // panels (ALT/AST/Alk Phos) and CBC trends on long-running chronic
      // meds surface even when there's no recent Western metabolic panel.
      db.from('lab_results')
        .select('test_name, loinc_code, value, unit, reference_range, status, effective_date')
        .eq('person_id', personId)
        .gte('effective_date', new Date(Date.now() - 60 * 30 * 24 * 60 * 60 * 1000).toISOString())
        .order('effective_date', { ascending: true })
        .limit(500)
        .then(function(r){ return (r && r.data) || []; })
        .catch(function(e){ console.warn('[EHR trends] labs error', e); return []; }),
      // Active meds.
      db.from('medications')
        .select('name, dose, frequency, active, start_date')
        .eq('person_id', personId)
        .eq('active', true)
        .order('start_date', { ascending: false, nullsFirst: false })
        .limit(20)
        .then(function(r){ return (r && r.data) || []; })
        .catch(function(e){ console.warn('[EHR trends] meds error', e); return []; })
    ]);
    var vitals = loads[0], labs = loads[1], meds = loads[2];
    // ── Vitals: pair systolic/diastolic by date; keep last 12 readings.
    var sys = vitals.filter(function(v){ return v.vital_type === 'Systolic blood pressure'; });
    var dia = vitals.filter(function(v){ return v.vital_type === 'Diastolic blood pressure'; });
    if (sys.length >= 2 && dia.length >= 2) {
      // Group by date (YYYY-MM-DD) so we pair each visit's S/D.
      var bpMap = {};
      sys.forEach(function(v){ var d = String(v.effective_date).slice(0,10); var num = parseFloat(v.value); if (!isNaN(num)) bpMap[d] = bpMap[d] || {date:d}; if (!isNaN(num)) bpMap[d].sys = num; });
      dia.forEach(function(v){ var d = String(v.effective_date).slice(0,10); var num = parseFloat(v.value); if (!isNaN(num)) bpMap[d] = bpMap[d] || {date:d}; if (!isNaN(num)) bpMap[d].dia = num; });
      var paired = Object.keys(bpMap).map(function(k){ return bpMap[k]; })
        .filter(function(r){ return r.sys && r.dia; })
        .sort(function(a,b){ return a.date < b.date ? -1 : 1; });
      if (paired.length >= 2) {
        var last = paired.slice(-12);
        var latest = last[last.length - 1];
        var prior = last.length > 1 ? last[last.length - 2] : null;
        var summary;
        if (latest.sys >= 140 || latest.dia >= 90) summary = 'Latest reading elevated';
        else if (latest.sys >= 130 || latest.dia >= 80) summary = 'Latest reading borderline';
        else summary = 'Latest reading in range';
        if (prior) {
          var delta = latest.sys - prior.sys;
          if (Math.abs(delta) >= 5) summary += ' \u00b7 ' + (delta > 0 ? '\u2191' : '\u2193') + ' ' + Math.abs(delta) + ' from prior visit';
        }
        out.bp = {
          systolic: last.map(function(r){ return r.sys; }),
          diastolic: last.map(function(r){ return r.dia; }),
          dates: last.map(function(r){ return r.date; }),
          latest: latest.sys + '/' + latest.dia,
          latestDate: latest.date,
          summary: summary
        };
      }
    }
    // Weight
    var wRows = vitals.filter(function(v){ return v.vital_type === 'Weight'; })
      .map(function(v){ return { v: parseFloat(v.value), d: String(v.effective_date).slice(0,10), unit: v.unit || 'kg' }; })
      .filter(function(r){ return !isNaN(r.v); })
      .sort(function(a,b){ return a.d < b.d ? -1 : 1; });
    if (wRows.length >= 2) {
      var lastW = wRows.slice(-12);
      var latestW = lastW[lastW.length - 1];
      var earliestW = lastW[0];
      var dW = latestW.v - earliestW.v;
      var unit = latestW.unit || 'kg';
      // Convert kg → lbs for display if the EHR gave us kg (Duke does kg).
      var displayUnit = unit;
      var conv = 1;
      if (/^kg/i.test(unit)) { displayUnit = 'lb'; conv = 2.20462; }
      var summaryW = 'Latest ' + Math.round(latestW.v * conv) + ' ' + displayUnit;
      if (Math.abs(dW) >= 1) summaryW += ' \u00b7 ' + (dW > 0 ? '\u2191' : '\u2193') + ' ' + Math.abs(Math.round(dW * conv)) + ' ' + displayUnit + ' over ' + lastW.length + ' visits';
      out.weight = {
        values: lastW.map(function(r){ return Math.round(r.v * conv * 10) / 10; }),
        dates: lastW.map(function(r){ return r.d; }),
        latest: Math.round(latestW.v * conv) + ' ' + displayUnit,
        latestDate: latestW.d,
        unit: displayUnit,
        summary: summaryW
      };
    }
    // ── Labs: pick the top "chartable" tests — numeric value, ≥3 readings, and a
    // curated allowlist that's clinically meaningful to surface.
    var labWhitelist = {
      // Western metabolic / cardiac panel
      'Hemoglobin A1C':       { display:'Hemoglobin A1C', priority: 1 },
      'Glucose':              { display:'Glucose',        priority: 2 },
      'Cholesterol, Total':   { display:'Total Cholesterol', priority: 3 },
      'HDL':                  { display:'HDL',            priority: 4 },
      'LDL':                  { display:'LDL',            priority: 4 },
      'Triglyceride':         { display:'Triglycerides',  priority: 5 },
      // Kidney
      'Creatinine':           { display:'Creatinine',     priority: 6 },
      'Glomerular Filtration Rate (eGFR)': { display:'eGFR (kidney function)', priority: 6 },
      'BUN':                  { display:'BUN (kidney)',   priority: 7 },
      'Blood Urea Nitrogen':  { display:'BUN (kidney)',   priority: 7 },
      // CBC — important for chronic meds like imatinib
      'Hemoglobin':           { display:'Hemoglobin',     priority: 8 },
      'Hematocrit':           { display:'Hematocrit',     priority: 8 },
      'Platelet Count':       { display:'Platelets',      priority: 8 },
      'White Blood Cell Count': { display:'WBC',          priority: 8 },
      'WBC':                  { display:'WBC',            priority: 8 },
      // Thyroid / vitamins
      'TSH':                  { display:'TSH (thyroid)',  priority: 9 },
      'Vitamin D':            { display:'Vitamin D',      priority: 10 },
      'Ferritin':             { display:'Ferritin',       priority: 10 },
      // Liver panel — chronic-monitoring labs that often dominate when
      // there's no recent metabolic panel (e.g. CML patients on imatinib).
      'ALT':                  { display:'ALT (liver)',    priority: 11 },
      'Alanine Aminotransferase': { display:'ALT (liver)', priority: 11 },
      'AST':                  { display:'AST (liver)',    priority: 11 },
      'Aspartate Aminotransferase': { display:'AST (liver)', priority: 11 },
      'Alk Phos':             { display:'Alk Phos (liver)', priority: 12 },
      'Alkaline Phosphatase': { display:'Alk Phos (liver)', priority: 12 },
      'Albumin':              { display:'Albumin',        priority: 12 },
      'Bilirubin':            { display:'Bilirubin',      priority: 12 },
      'Bilirubin, Total':     { display:'Bilirubin',      priority: 12 },
      // Basic metabolic — electrolytes / calcium
      'Sodium':               { display:'Sodium',         priority: 13 },
      'Potassium':            { display:'Potassium',      priority: 13 },
      'Chloride':             { display:'Chloride',       priority: 13 },
      'Calcium':              { display:'Calcium',        priority: 13 }
    };
    var byTest = {};
    labs.forEach(function(l) {
      if (!l.test_name || !labWhitelist[l.test_name]) return;
      var n = parseFloat(l.value);
      if (isNaN(n)) return;
      var k = l.test_name;
      byTest[k] = byTest[k] || { name: labWhitelist[k].display, code: l.loinc_code, unit: l.unit, range: l.reference_range, status: l.status, priority: labWhitelist[k].priority, rows: [] };
      byTest[k].rows.push({ v:n, d: String(l.effective_date).slice(0,10), status: l.status });
    });
    Object.keys(byTest).forEach(function(k) {
      var t = byTest[k];
      if (t.rows.length < 3) return; // need a real trend
      t.rows.sort(function(a,b){ return a.d < b.d ? -1 : 1; });
      var last = t.rows.slice(-10);
      var latest = last[last.length - 1];
      out.labs.push({
        name: t.name,
        code: t.code,
        values: last.map(function(r){ return r.v; }),
        dates: last.map(function(r){ return r.d; }),
        unit: t.unit || '',
        range: t.range || '',
        latest: latest.v,
        latestDate: latest.d,
        latestStatus: (latest.status || '').toLowerCase(),
        priority: t.priority
      });
    });
    out.labs.sort(function(a,b){ return a.priority - b.priority; });
    out.labs = out.labs.slice(0, 4); // show top 4 max so the section stays scannable
    // Active meds: trim Epic's verbose dose strings for chip display.
    out.meds = (meds || []).slice(0, 6).map(function(m) {
      // Pull just the drug name + strength (e.g. "lisinopril 20 MG tablet")
      // and drop Epic's "Take 1 tablet by mouth\u2026, Starting \u2026, Electronic" trailer.
      var name = String(m.name || '').replace(/\s+tablet$/i, '').trim();
      var shortDose = '';
      if (m.dose) {
        var dose = String(m.dose);
        // Capture "Take N tablet(s) (X mg total)" or "Inject X mLs (Y mg total)" prefix.
        var match = dose.match(/^(Take[^,]+|Inject[^,]+)/i);
        shortDose = match ? match[1].trim() : (dose.split(',')[0] || '').trim();
        if (shortDose.length > 56) shortDose = shortDose.slice(0, 54) + '\u2026';
      }
      return {
        name: name,
        dose: shortDose,
        frequency: m.frequency || '',
        startDate: m.start_date || null
      };
    });
    return out;
  } catch (e) {
    console.warn('[EHR trends] load failed', e);
    return null;
  }
}

// Render the "From your chart" section: BP card, weight card, lab mini-charts,
// active meds list. Returns '' when the user truly has no EHR data.
function _buildEhrTrendsHtml(ehrTrends, sigFirstName) {
  if (!ehrTrends) return '';
  var hasAny = !!(ehrTrends.bp || ehrTrends.weight || (ehrTrends.labs || []).length || (ehrTrends.meds || []).length);
  if (!hasAny) return '';
  var html = '';
  // ── BP + Weight: side-by-side big-number cards with a 12-visit trend.
  if (ehrTrends.bp || ehrTrends.weight) {
    html += '<div class="cs-ehr-vitals-grid">';
    if (ehrTrends.bp) {
      var bp = ehrTrends.bp;
      html += '<div class="cs-ehr-card">';
      html += '<div class="cs-ehr-card-label">Blood pressure</div>';
      html += '<div class="cs-ehr-card-metric">' + escHtml(bp.latest) + ' <span class="cs-ehr-card-unit">mmHg</span></div>';
      html += '<div class="cs-ehr-card-spark">' + buildDualLineChart(bp.systolic, bp.diastolic, 280, 86, '#B85450', '#3B6EA5') + '</div>';
      html += '<div class="cs-ehr-card-legend">';
      html += '<span class="cs-ehr-legend-dot" style="background:#B85450;"></span><span>Systolic</span>';
      html += '<span class="cs-ehr-legend-dot" style="background:#3B6EA5;margin-left:10px;"></span><span>Diastolic</span>';
      html += '</div>';
      html += '<div class="cs-ehr-card-sub">' + escHtml(bp.summary) + ' \u00b7 last visit ' + escHtml(_humanDate(bp.latestDate)) + '</div>';
      html += '</div>';
    }
    if (ehrTrends.weight) {
      var w = ehrTrends.weight;
      html += '<div class="cs-ehr-card">';
      html += '<div class="cs-ehr-card-label">Weight</div>';
      html += '<div class="cs-ehr-card-metric">' + escHtml(w.latest) + '</div>';
      html += '<div class="cs-ehr-card-spark">' + buildRhythmChart(w.values, 280, 86, '#5A6F50', '') + '</div>';
      html += '<div class="cs-ehr-card-sub">' + escHtml(w.summary) + ' \u00b7 last visit ' + escHtml(_humanDate(w.latestDate)) + '</div>';
      html += '</div>';
    }
    html += '</div>';
  }
  // ── Labs: 2-column mini-card grid.
  if ((ehrTrends.labs || []).length > 0) {
    html += '<div class="cs-ehr-section-sub">From recent labs</div>';
    html += '<div class="cs-ehr-labs-grid">';
    ehrTrends.labs.forEach(function(l) {
      var statusClass = '';
      if (l.latestStatus === 'abnormal' || l.latestStatus === 'high' || l.latestStatus === 'low' || l.latestStatus === 'h' || l.latestStatus === 'l') statusClass = ' cs-ehr-lab-card--alert';
      html += '<div class="cs-ehr-lab-card' + statusClass + '">';
      html += '<div class="cs-ehr-lab-name">' + escHtml(l.name) + '</div>';
      html += '<div class="cs-ehr-lab-value">' + escHtml(String(l.latest)) + (l.unit ? ' <span class="cs-ehr-lab-unit">' + escHtml(l.unit) + '</span>' : '') + '</div>';
      try { html += '<div class="cs-ehr-lab-spark">' + buildRhythmChart(l.values, 200, 56, '#5A6F50', '') + '</div>'; } catch(_e){}
      var when = _humanDate(l.latestDate);
      var rangeBit = l.range ? ' \u00b7 ref ' + escHtml(l.range) : '';
      html += '<div class="cs-ehr-lab-sub">' + escHtml(when) + rangeBit + '</div>';
      html += '</div>';
    });
    html += '</div>';
  }
  // ── Active meds: compact list.
  if ((ehrTrends.meds || []).length > 0) {
    html += '<div class="cs-ehr-section-sub">Active medications</div>';
    html += '<div class="cs-ehr-meds-list">';
    ehrTrends.meds.forEach(function(m) {
      html += '<div class="cs-ehr-med-row">';
      html += '<div class="cs-ehr-med-icon"><i data-lucide="pill" style="width:14px;height:14px;"></i></div>';
      html += '<div class="cs-ehr-med-body">';
      html += '<div class="cs-ehr-med-name">' + escHtml(m.name) + '</div>';
      var subBits = [];
      if (m.dose) subBits.push(m.dose);
      if (m.frequency) subBits.push(m.frequency);
      if (m.startDate) subBits.push('Since ' + _humanDate(m.startDate));
      if (subBits.length) html += '<div class="cs-ehr-med-sub">' + escHtml(subBits.join(' \u00b7 ')) + '</div>';
      html += '</div>';
      html += '</div>';
    });
    html += '</div>';
  }
  return html;
}

// Human date helper used by the EHR trends section. Falls back gracefully if
// the input is malformed.
function _humanDate(d) {
  if (!d) return '';
  try {
    var dt = new Date(d);
    if (isNaN(dt.getTime())) return String(d);
    return dt.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  } catch (_e) {
    return String(d);
  }
}

// Dual-line chart for paired metrics (systolic/diastolic). Reuses the same
// padding & day-tick conventions as buildRhythmChart but draws two lines.
function buildDualLineChart(seriesA, seriesB, width, height, colorA, colorB) {
  if (!seriesA || !seriesB || seriesA.length === 0) return '';
  var W = width, H = height;
  var padL = 6, padR = 6, padT = 14, padB = 18;
  var chartW = W - padL - padR;
  var chartH = H - padT - padB;
  var combined = seriesA.concat(seriesB).filter(function(v){ return v > 0; });
  if (combined.length === 0) return '';
  var max = Math.max.apply(null, combined);
  var min = Math.min.apply(null, combined);
  var pad = (max - min) > 0 ? (max - min) * 0.15 : Math.max(2, max * 0.05);
  var lo = Math.max(0, min - pad);
  var hi = max + pad;
  var range = hi - lo || 1;
  var n = seriesA.length;
  var stepX = n > 1 ? chartW / (n - 1) : 0;
  function px(i){ return padL + i * stepX; }
  function py(v){ return padT + chartH - ((v - lo) / range) * chartH; }
  function makeLine(series, color) {
    var pts = [];
    for (var i = 0; i < series.length; i++) {
      if (series[i] > 0) pts.push(px(i) + ',' + py(series[i]));
    }
    if (pts.length === 0) return '';
    var out = '<polyline fill="none" stroke="' + color + '" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" points="' + pts.join(' ') + '"/>';
    for (var j = 0; j < series.length; j++) {
      if (series[j] > 0) out += '<circle cx="' + px(j) + '" cy="' + py(series[j]) + '" r="2" fill="' + color + '"/>';
    }
    return out;
  }
  var svg = '<svg width="100%" height="' + H + '" viewBox="0 0 ' + W + ' ' + H + '" preserveAspectRatio="none" aria-hidden="true" style="display:block;">';
  svg += '<line x1="' + padL + '" y1="' + (padT + chartH) + '" x2="' + (W - padR) + '" y2="' + (padT + chartH) + '" stroke="#E5DFD2" stroke-width="1"/>';
  svg += makeLine(seriesA, colorA);
  svg += makeLine(seriesB, colorB);
  // Latest-value labels
  var latestA = seriesA[seriesA.length - 1];
  var latestB = seriesB[seriesB.length - 1];
  if (latestA > 0) svg += '<text x="' + (W - padR) + '" y="' + (py(latestA) - 4) + '" text-anchor="end" font-family="DM Sans, system-ui, sans-serif" font-size="10" font-weight="600" fill="' + colorA + '">' + Math.round(latestA) + '</text>';
  if (latestB > 0) svg += '<text x="' + (W - padR) + '" y="' + (py(latestB) + 11) + '" text-anchor="end" font-family="DM Sans, system-ui, sans-serif" font-size="10" font-weight="600" fill="' + colorB + '">' + Math.round(latestB) + '</text>';
  // X-tick: "oldest \u2192 latest" hint instead of day-of-week (irregular visit spacing).
  svg += '<text x="' + padL + '" y="' + (H - 4) + '" text-anchor="start" font-family="DM Sans, system-ui, sans-serif" font-size="9" fill="#9B8F7E">oldest</text>';
  svg += '<text x="' + (W - padR) + '" y="' + (H - 4) + '" text-anchor="end" font-family="DM Sans, system-ui, sans-serif" font-size="9" fill="#3D3530" font-weight="600">latest</text>';
  svg += '</svg>';
  return svg;
}

// Pull the last 7 days of Apple Health from wearable_observations and roll it
// up into a compact rhythm summary. Returns null on any failure or no data so
// callers can render an empty state cleanly.
//
// Available hk_types confirmed in the DB (2026-05-12):
//   HKQuantityTypeIdentifierHeartRate, StepCount, RestingHeartRate,
//   HeartRateVariabilitySDNN, ActiveEnergyBurned
// (Sleep not flowing yet — quantity types only.)
async function _loadAppleHealthRhythm(personId) {
  if (!personId || !db) return null;
  var sinceIso = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
  try {
    var res = await db.from('wearable_observations')
      .select('hk_type, start_at, value, unit, device_source')
      .eq('person_id', personId)
      .eq('source', 'apple-health')
      .gte('start_at', sinceIso)
      .order('start_at', { ascending: false })
      .limit(2000);
    if (!res || res.error || !Array.isArray(res.data) || res.data.length === 0) {
      if (res && res.error) console.warn('[Signals] AH rhythm query error', res.error);
      return null;
    }
    var rows = res.data;
    var byType = { hr: [], rhr: [], steps: [], hrv: [], active: [] };
    var lastSyncAt = null;
    for (var i = 0; i < rows.length; i++) {
      var r = rows[i];
      if (!r || !r.hk_type) continue;
      if (!lastSyncAt || r.start_at > lastSyncAt) lastSyncAt = r.start_at;
      if (r.hk_type === 'HKQuantityTypeIdentifierHeartRate') byType.hr.push(r);
      else if (r.hk_type === 'HKQuantityTypeIdentifierRestingHeartRate') byType.rhr.push(r);
      else if (r.hk_type === 'HKQuantityTypeIdentifierStepCount') byType.steps.push(r);
      else if (r.hk_type === 'HKQuantityTypeIdentifierHeartRateVariabilitySDNN') byType.hrv.push(r);
      else if (r.hk_type === 'HKQuantityTypeIdentifierActiveEnergyBurned') byType.active.push(r);
    }
    // Day-bucket helper (YYYY-MM-DD local)
    function dayKey(iso) {
      try {
        var d = new Date(iso);
        return d.getFullYear() + '-' + (d.getMonth()+1) + '-' + d.getDate();
      } catch (_e) { return ''; }
    }
    function bucketSum(arr) {
      var by = {};
      for (var j = 0; j < arr.length; j++) {
        var k = dayKey(arr[j].start_at);
        if (!k) continue;
        by[k] = (by[k] || 0) + (Number(arr[j].value) || 0);
      }
      // Return last 7 days in chronological order (oldest → newest)
      var out = [];
      for (var d2 = 6; d2 >= 0; d2--) {
        var dt = new Date(Date.now() - d2 * 24 * 60 * 60 * 1000);
        var key = dt.getFullYear() + '-' + (dt.getMonth()+1) + '-' + dt.getDate();
        out.push(by[key] || 0);
      }
      return out;
    }
    function bucketAvg(arr) {
      var by = {};
      for (var j = 0; j < arr.length; j++) {
        var k = dayKey(arr[j].start_at);
        if (!k) continue;
        if (!by[k]) by[k] = { sum: 0, n: 0 };
        by[k].sum += (Number(arr[j].value) || 0);
        by[k].n  += 1;
      }
      var out = [];
      for (var d2 = 6; d2 >= 0; d2--) {
        var dt = new Date(Date.now() - d2 * 24 * 60 * 60 * 1000);
        var key = dt.getFullYear() + '-' + (dt.getMonth()+1) + '-' + dt.getDate();
        var b = by[key];
        out.push(b && b.n > 0 ? Math.round(b.sum / b.n) : 0);
      }
      return out;
    }
    var stepsByDay = bucketSum(byType.steps);
    var hrByDay    = bucketAvg(byType.hr);
    var rhrByDay   = bucketAvg(byType.rhr);
    var hrvByDay   = bucketAvg(byType.hrv);
    function latestNonZero(arr) {
      for (var k = arr.length - 1; k >= 0; k--) if (arr[k] > 0) return arr[k];
      return 0;
    }
    var hr  = byType.hr.length    ? { latest: Math.round(Number(byType.hr[0].value) || 0),  trend: hrByDay,  unit: 'bpm' }  : null;
    var rhr = byType.rhr.length   ? { latest: Math.round(Number(byType.rhr[0].value) || 0), trend: rhrByDay, unit: 'bpm' }  : null;
    var steps = byType.steps.length ? { today: stepsByDay[stepsByDay.length-1], trend: stepsByDay, unit: 'steps' } : null;
    var hrv = byType.hrv.length   ? { latest: Math.round(Number(byType.hrv[0].value) || 0), trend: hrvByDay, unit: 'ms' }   : null;
    // If RHR is missing but HR is present, use latest non-zero HR average as a soft fallback.
    if (!rhr && hr) rhr = { latest: latestNonZero(hrByDay) || hr.latest, trend: hrByDay, unit: 'bpm', soft: true };
    return {
      heartRate: hr,
      restingHr: rhr,
      steps:     steps,
      hrv:       hrv,
      lastSyncAt: lastSyncAt
    };
  } catch (e) {
    console.error('[Signals] _loadAppleHealthRhythm exception', e);
    return null;
  }
}

// Editorial one-liner for the "Right Now" section. Returns '' to suppress.
function _buildRightNowLine(name, checkIns, conns, terraData, rhythmAH) {
  var who = escHtml(name || 'your loved one');
  // 1) Fresh family check-in beats everything
  var latestCi = (checkIns && checkIns.length) ? checkIns[0] : null;
  if (latestCi) {
    var when = '';
    try { when = formatTimeAgo(latestCi.checked_in_at || latestCi.created_at); } catch(_e){}
    var bits = [];
    if (latestCi.mood)         bits.push('mood ' + String(latestCi.mood).toLowerCase());
    if (latestCi.energy_level) bits.push('energy ' + String(latestCi.energy_level).toLowerCase());
    if (latestCi.sleep_quality)bits.push('sleep ' + String(latestCi.sleep_quality).toLowerCase());
    var snippet = bits.slice(0,2).join(', ');
    if (snippet) {
      return who + ' \u2014 ' + escHtml(snippet) + (when ? ' \u00b7 ' + escHtml(when) : '') + '.';
    }
    if (latestCi.notes) {
      var note = String(latestCi.notes).slice(0, 140);
      return who + ' \u2014 \u201c' + escHtml(note) + '\u201d' + (when ? ' \u00b7 ' + escHtml(when) : '') + '.';
    }
  }
  // 2) Apple Health snapshot — only when the underlying data is FRESH.
  // If Wellet Connect hasn't pushed any HealthKit rows in 12+ hours, the
  // "resting heart rate 67 bpm" line is days-old and misleading, so we
  // suppress it and fall through to a softer 'following rhythms' line.
  if (rhythmAH) {
    var freshMs = 12 * 60 * 60 * 1000;
    var isFresh = false;
    if (rhythmAH.lastSyncAt) {
      try { isFresh = (Date.now() - new Date(rhythmAH.lastSyncAt).getTime()) < freshMs; } catch(_e) {}
    }
    if (isFresh) {
      var phrases = [];
      if (rhythmAH.steps && rhythmAH.steps.today > 0) {
        phrases.push((rhythmAH.steps.today).toLocaleString() + ' steps today');
      }
      if (rhythmAH.restingHr && rhythmAH.restingHr.latest > 0) {
        phrases.push('resting heart rate ' + rhythmAH.restingHr.latest + ' bpm');
      } else if (rhythmAH.heartRate && rhythmAH.heartRate.latest > 0) {
        phrases.push('heart rate ' + rhythmAH.heartRate.latest + ' bpm');
      }
      if (phrases.length) {
        return who + ' \u2014 ' + escHtml(phrases.slice(0,2).join(', ')) + '.';
      }
    }
  }
  // 3) Terra device data
  if (terraData && terraData.vitals && terraData.vitals.length) {
    return 'Wellet is following ' + who + '\u2019s wearable rhythms.';
  }
  return '';
}

// Render the active-watches list inline in the CareSignals view. Mirrors the
// shape of renderWatchesList() but returns HTML so the parent section can wrap
// it. Empty state nudges toward the "Tell Wellet" CTA in the section head.
function _renderWatchesSectionHtml(watches, name) {
  if (!watches || watches.length === 0) {
    return ''
      + '<div class="cs-watches-empty">'
      +   'Nothing to notice yet. Tap '
      +   '<em>Tell Wellet what to notice</em> '
      +   'to add the first one \u2014 like \u201cnotice if ' + escHtml(name) + ' takes fewer than 1,000 steps for three days.\u201d'
      + '</div>';
  }
  // Sort: active first, then by created_at desc (already)
  var sorted = watches.slice().sort(function(a, b) {
    var aa = (a.active === false) ? 1 : 0;
    var bb = (b.active === false) ? 1 : 0;
    return aa - bb;
  });
  var out = '<div class="cs-watches-list">';
  for (var i = 0; i < sorted.length; i++) {
    var w = sorted[i];
    var friendly = _watchTypeFriendly(w.watch_type, w.parameters);
    var paused = (w.active === false);
    var statusChip = paused
      ? '<span class="watch-row-status watch-row-status-paused">Paused</span>'
      : '<span class="watch-row-status watch-row-status-active">Active</span>';
    var pauseLabel = paused ? 'Resume' : 'Pause';
    var pauseIcon  = paused ? 'play' : 'pause';
    out += ''
      + '<div class="watch-row" data-id="' + escHtml(w.id) + '">'
      +   '<div class="watch-row-head">'
      +     '<i data-lucide="bell" class="watch-row-icon"></i>'
      +     '<div class="watch-row-meta">'
      +       '<div class="watch-row-title">' + escHtml(friendly) + '</div>'
      +       '<div class="watch-row-sub">For ' + escHtml(name) + '</div>'
      +     '</div>'
      +     statusChip
      +   '</div>'
      +   '<div class="watch-row-actions">'
      +     '<button type="button" class="watch-row-btn" onclick="toggleWatchPaused(\'' + w.id + '\', ' + (paused ? 'false' : 'true') + '); setTimeout(renderSignalsView, 250);">'
      +       '<i data-lucide="' + pauseIcon + '" style="width:13px;height:13px;"></i><span>' + pauseLabel + '</span>'
      +     '</button>'
      +     '<button type="button" class="watch-row-btn watch-row-btn-danger" onclick="deleteWatch(\'' + w.id + '\'); setTimeout(renderSignalsView, 250);">'
      +       '<i data-lucide="trash-2" style="width:13px;height:13px;"></i><span>Stop</span>'
      +     '</button>'
      +   '</div>'
      + '</div>';
  }
  out += '</div>';
  return out;
}

// This Week's Rhythm — sparkline trio. Returns '' if no data of any kind so
// the parent section can skip itself.
function _buildRhythmHtml(terraData, rhythmAH, checkIns) {
  var ah = rhythmAH || {};
  var hasHr    = !!(ah.heartRate && (ah.heartRate.trend || []).some(function(v){ return v > 0; }));
  var hasSteps = !!(ah.steps && (ah.steps.trend || []).some(function(v){ return v > 0; }));
  var hasHrv   = !!(ah.hrv && (ah.hrv.trend || []).some(function(v){ return v > 0; }));
  var sleepFromCi = (checkIns || [])
    .filter(function(c){ return !!c.sleep_quality; })
    .slice(0, 5)
    .map(function(c){ return String(c.sleep_quality); });
  var hasSleep = sleepFromCi.length > 0;
  if (!hasHr && !hasSteps && !hasHrv && !hasSleep) return '';
  // Format the freshness of the underlying Apple Health rows so testers can
  // see WHY a metric looks weird (e.g. "Steps 0" because background sync
  // hasn't flushed today's writes from Wellet Connect yet).
  var freshLabel = '';
  var isStale = false; // > 24h old → tiles show "no fresh data" not "0"
  if (ah.lastSyncAt) {
    try {
      var ageMs = Date.now() - new Date(ah.lastSyncAt).getTime();
      isStale = ageMs > 24 * 60 * 60 * 1000;
      freshLabel = 'Apple Health \u00b7 last synced ' + formatTimeAgo(ah.lastSyncAt);
    } catch(_e) {}
  }
  var html = '';
  if (isStale) {
    // Stale banner: tells the user the displayed numbers are old and lets them
    // tap to bounce into Wellet Connect (which resumes HealthKit background
    // delivery). On iPhone the wellet:// universal link opens the app; on
    // desktop/Android the click is a no-op visual.
    var refreshHref = 'javascript:refreshAppleHealthFromBanner();';
    html += '<a href="' + refreshHref + '" class="cs-rhythm-stale cs-rhythm-stale--tappable" role="button">';
    html += '<div class="cs-rhythm-stale-icon"><i data-lucide="refresh-cw" style="width:14px;height:14px;"></i></div>';
    html += '<div class="cs-rhythm-stale-body">';
    html += '<div class="cs-rhythm-stale-title">' + escHtml(freshLabel || 'Apple Health is quiet') + '</div>';
    html += '<div class="cs-rhythm-stale-sub">Tap to open Wellet Connect on your iPhone and refresh today\u2019s heart rate and steps.</div>';
    html += '</div>';
    html += '<div class="cs-rhythm-stale-chevron"><i data-lucide="chevron-right" style="width:16px;height:16px;"></i></div>';
    html += '</a>';
  } else if (freshLabel) {
    html += '<div class="cs-rhythm-freshness">' + escHtml(freshLabel) + '</div>';
  }
  html += '<div class="cs-rhythm-grid">';
  // Resting heart rate — prefer RHR rows; fall back to soft mean of HR.
  // Skip if we truly have no signal of either kind.
  var rhrTile = ah.restingHr;
  var hrFallback = !rhrTile && hasHr ? ah.heartRate : null;
  if (rhrTile || hrFallback) {
    var src = rhrTile || hrFallback;
    // Compute the 7-day mean of the non-zero days so the headline number
    // matches the sparkline instead of just echoing the latest sample.
    var nonZero = (src.trend || []).filter(function(v){ return v > 0; });
    var mean = nonZero.length
      ? Math.round(nonZero.reduce(function(a,b){return a+b;}, 0) / nonZero.length)
      : (src.latest || 0);
    html += '<div class="cs-rhythm-card">';
    html += '<div class="cs-rhythm-label">Resting heart rate</div>';
    html += '<div class="cs-rhythm-metric">' + mean + ' <span class="cs-rhythm-unit">bpm</span></div>';
    try { html += '<div class="cs-rhythm-spark">' + buildRhythmChart(src.trend, 280, 72, '#B85450', '') + '</div>'; } catch (_e) {}
    html += '<div class="cs-rhythm-sub">' + (isStale ? 'Last 7 days · numbers may be stale' : '7-day average') + '</div>';
    html += '</div>';
  }
  // Steps sparkline — if stale AND today=0, show last non-zero day instead of
  // a misleading "0 today" headline.
  if (hasSteps) {
    var todaySteps = ah.steps.today || 0;
    var stepsLabel = 'Today \u00b7 7-day trend';
    var stepsHeadline = todaySteps.toLocaleString();
    if (isStale && todaySteps === 0) {
      var trendArr = ah.steps.trend || [];
      var lastNonZero = 0;
      var daysBack = 0;
      for (var si = trendArr.length - 1; si >= 0; si--) {
        if (trendArr[si] > 0) { lastNonZero = trendArr[si]; daysBack = trendArr.length - 1 - si; break; }
      }
      if (lastNonZero > 0) {
        stepsHeadline = lastNonZero.toLocaleString();
        stepsLabel = daysBack === 1 ? 'Yesterday\u2019s steps · awaiting fresh sync'
                    : daysBack <= 6 ? daysBack + ' days ago · awaiting fresh sync'
                    : 'Recent steps · awaiting fresh sync';
      } else {
        stepsLabel = 'Awaiting fresh sync';
      }
    }
    html += '<div class="cs-rhythm-card">';
    html += '<div class="cs-rhythm-label">Steps</div>';
    html += '<div class="cs-rhythm-metric">' + stepsHeadline + '</div>';
    try { html += '<div class="cs-rhythm-spark">' + buildRhythmChart(ah.steps.trend, 280, 72, '#5A6F50', '') + '</div>'; } catch (_e) {}
    html += '<div class="cs-rhythm-sub">' + escHtml(stepsLabel) + '</div>';
    html += '</div>';
  }
  // Sleep — prefer family check-in sleep_quality; otherwise show a calm
  // placeholder so testers know Apple Health sleep is on the roadmap
  // rather than silently missing. HRV is intentionally NOT shown in v1.
  if (hasSleep) {
    html += '<div class="cs-rhythm-card">';
    html += '<div class="cs-rhythm-label">Sleep</div>';
    html += '<div class="cs-rhythm-metric cs-rhythm-metric--soft">' + escHtml(sleepFromCi[0]) + '</div>';
    html += '<div class="cs-rhythm-sub">From recent check-ins</div>';
    html += '</div>';
  } else {
    html += '<div class="cs-rhythm-card cs-rhythm-card--placeholder">';
    html += '<div class="cs-rhythm-label">Sleep</div>';
    html += '<div class="cs-rhythm-metric cs-rhythm-metric--soft">\u2014</div>';
    html += '<div class="cs-rhythm-sub">Coming next from Apple Health</div>';
    html += '</div>';
  }
  html += '</div>';
  return html;
}

// Care Circle check-in feed (last 5). Empty state encourages the first one.
function _renderCircleSectionHtml(checkIns, name) {
  if (!checkIns || checkIns.length === 0) {
    return ''
      + '<div class="cs-circle-empty">'
      +   'No check-ins from ' + escHtml(name) + '\u2019s circle yet. When family or friends log how they\u2019re feeling, it shows up here.'
      + '</div>';
  }
  var out = '<div class="cs-circle-list">';
  for (var i = 0; i < checkIns.length; i++) {
    var c = checkIns[i];
    var when = '';
    try { when = formatTimeAgo(c.checked_in_at || c.created_at); } catch(_e){}
    var pieces = [];
    if (c.mood)          pieces.push('Mood: ' + escHtml(c.mood));
    if (c.energy_level)  pieces.push('Energy: ' + escHtml(c.energy_level));
    if (c.sleep_quality) pieces.push('Sleep: ' + escHtml(c.sleep_quality));
    if (typeof c.pain_level === 'number' && c.pain_level > 0) pieces.push('Pain: ' + c.pain_level + '/10');
    if (c.appetite)      pieces.push('Appetite: ' + escHtml(c.appetite));
    var src = c.source ? String(c.source) : 'check-in';
    out += '<div class="cs-circle-row">';
    out += '<div class="cs-circle-row-head">';
    out += '<i data-lucide="heart" style="width:14px;height:14px;"></i>';
    out += '<span class="cs-circle-row-when">' + escHtml(when || src) + '</span>';
    out += '</div>';
    if (pieces.length) {
      out += '<div class="cs-circle-row-pieces">' + pieces.join(' \u00b7 ') + '</div>';
    }
    if (c.notes) {
      out += '<div class="cs-circle-row-notes">\u201c' + escHtml(String(c.notes).slice(0, 240)) + '\u201d</div>';
    }
    out += '</div>';
  }
  out += '</div>';
  return out;
}

// Build the wearable-card grid (heart rate / steps / sleep / spo2 / hrv) from
// the Terra/Whoop/Garmin data path. Lifted out of the legacy _paintSignals body
// so the new shell can reuse it under the Wearables section.
function _buildWearableGridHtml(activeConns, terraData) {
  if (!terraData || !terraData.vitals || !activeConns || activeConns.length === 0) return '';
  var rw;
  try {
    rw = buildRealSignalsData(terraData.vitals, terraData.events, activeConns);
  } catch (e) {
    console.error('[Signals] buildRealSignalsData failed', e);
    return '';
  }
  if (!rw) return '';
  var ch = '<div class="wearable-grid">';
  if (rw.heartRate) {
    ch += '<div class="wearable-card">';
    ch += '<div class="signals-label">' + t('signals.heartRate') + '</div>';
    ch += '<div class="signals-metric">' + rw.heartRate.current + ' <span style="font-size:var(--type-body);font-weight:400;color:var(--text-secondary);">bpm</span></div>';
    if (rw.heartRate.trend && rw.heartRate.trend.length >= 2) {
      ch += '<div class="wearable-sparkline">' + buildSparkline(rw.heartRate.trend, 120, 28, 'var(--red)') + '</div>';
    }
    ch += '<div class="signals-metric-sm">' + rw.heartRate.min + '\u2013' + rw.heartRate.max + ' range</div>';
    if (rw.heartRate.resting) ch += '<div class="signals-metric-sm">Resting: ' + rw.heartRate.resting + ' bpm</div>';
    ch += renderWearablePills('heart_rate', rw.personName);
    ch += '</div>';
  }
  if (rw.steps) {
    var rStepsPct = Math.round(rw.steps.today / rw.steps.goal * 100);
    ch += '<div class="wearable-card">';
    ch += '<div class="signals-label">' + t('signals.steps') + '</div>';
    ch += '<div class="signals-metric">' + rw.steps.today.toLocaleString() + '</div>';
    ch += '<div class="progress-ring-wrap">';
    ch += buildProgressRing(rStepsPct, 40, 'var(--moss)');
    ch += '<div class="progress-ring-label">' + rStepsPct + '% of goal</div>';
    ch += '</div>';
    if (rw.calories) ch += '<div class="signals-metric-sm">' + rw.calories.toLocaleString() + ' active cal</div>';
    if (rw.distance) ch += '<div class="signals-metric-sm">' + rw.distance + ' mi</div>';
    ch += renderWearablePills('steps', rw.personName);
    ch += '</div>';
  }
  if (rw.sleep) {
    var rSleepH = Math.floor(rw.sleep.total / 60);
    var rSleepM = rw.sleep.total % 60;
    ch += '<div class="wearable-card">';
    ch += '<div class="signals-label">' + t('signals.sleep') + '</div>';
    ch += '<div class="signals-metric">' + rSleepH + 'h ' + rSleepM + 'm</div>';
    ch += buildSleepBar(rw.sleep);
    if (rw.sleep.bedTime || rw.sleep.wakeTime) {
      ch += '<div class="signals-metric-sm">' + escHtml(rw.sleep.bedTime) + (rw.sleep.wakeTime ? ' \u2013 ' + escHtml(rw.sleep.wakeTime) : '') + '</div>';
    }
    ch += renderWearablePills('sleep', rw.personName);
    ch += '</div>';
  }
  if (rw.spo2) {
    ch += '<div class="wearable-card">';
    ch += '<div class="signals-label">' + t('signals.bloodOxygen') + '</div>';
    ch += '<div class="signals-metric">' + rw.spo2.current + '<span style="font-size:var(--type-body);font-weight:400;">%</span></div>';
    ch += '<div style="display:flex;align-items:center;gap:4px;margin-top:4px;"><span style="width:8px;height:8px;border-radius:50%;background:var(--moss);display:inline-block;"></span>';
    ch += '<span class="signals-metric-sm">' + rw.spo2.min + '\u2013' + rw.spo2.max + '% range</span></div>';
    ch += '</div>';
  }
  if (rw.hrv) {
    ch += '<div class="wearable-card">';
    ch += '<div class="signals-label">HRV</div>';
    ch += '<div class="signals-metric">' + rw.hrv.current + ' <span style="font-size:var(--type-body);font-weight:400;color:var(--text-secondary);">' + escHtml(rw.hrv.unit) + '</span></div>';
    ch += '<div class="signals-metric-sm">Heart rate variability</div>';
    ch += '</div>';
  }
  ch += '</div>';
  return ch;
}

// When Apple Health is the only source (no third-party wearable), show one
// "iPhone via Apple Health" device row so the user has the same mental model.
function _buildAppleHealthDeviceCardHtml(rhythmAH) {
  if (!rhythmAH) return '';
  var sync = '';
  if (rhythmAH.lastSyncAt) {
    try { sync = 'Last data ' + formatTimeAgo(rhythmAH.lastSyncAt); } catch(_e){ sync = ''; }
  }
  var metricCount = 0;
  if (rhythmAH.heartRate) metricCount++;
  if (rhythmAH.restingHr && !rhythmAH.restingHr.soft) metricCount++;
  if (rhythmAH.steps) metricCount++;
  if (rhythmAH.hrv) metricCount++;
  var subline = (metricCount === 1 ? '1 metric flowing' : metricCount + ' metrics flowing');
  var html = '<div class="terra-devices-section">';
  html += '<div class="terra-devices-title">Connected Devices</div>';
  html += '<div class="terra-device-card">';
  html += '<div class="terra-device-icon"><i data-lucide="smartphone"></i></div>';
  html += '<div class="terra-device-info">';
  html += '<div class="terra-device-name"><span class="terra-status-dot terra-status-dot--active"></span> iPhone \u00b7 Apple Health</div>';
  html += '<div class="terra-device-meta">' + escHtml(subline) + (sync ? ' \u00b7 ' + escHtml(sync) : '') + '</div>';
  html += '</div>';
  html += '</div>';
  html += '<button class="terra-add-btn" onclick="openTerraConnect()"><i data-lucide="plus" style="width:14px;height:14px;"></i> Connect a wearable too</button>';
  html += '<div class="terra-poweredby">Wearables powered by <a href="https://tryterra.co" target="_blank" rel="noopener noreferrer">Terra</a></div>';
  html += '</div>';
  return html;
}

// Plain-English modal for adding a watch. Uses the same vp-overlay/vp-sheet
// pattern as the watch-proposal flow, POSTs to create-care-signal-watch.
async function openAddWatchModal() {
  if (!currentPersonId) {
    if (typeof showToast === 'function') showToast('Pick a loved one first.');
    return;
  }
  // Remove any existing instance
  var prev = document.getElementById('cs-add-watch-overlay');
  if (prev && prev.parentNode) prev.parentNode.removeChild(prev);

  var name = getPersonFirstName() || 'your loved one';
  var safeName = escHtml(name);

  var overlay = document.createElement('div');
  overlay.id = 'cs-add-watch-overlay';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.style.cssText = 'position:fixed;inset:0;z-index:10000;display:flex;align-items:flex-end;justify-content:center;background:rgba(20,24,22,0.42);backdrop-filter:blur(2px);-webkit-backdrop-filter:blur(2px);animation:nr-fade 0.18s ease-out;';

  var sheet = document.createElement('div');
  sheet.style.cssText = 'background:#FAF7F0;border-radius:20px 20px 0 0;width:100%;max-width:560px;max-height:88vh;overflow-y:auto;padding:22px 22px 18px;box-shadow:0 -8px 28px rgba(0,0,0,0.18);animation:nr-slide 0.22s ease-out;';

  // Pick a watch type via radio cards. Each card has the params it needs.
  // Only types Wellet can actually fulfill today are exposed.
  var typeOptions = [
    { id: 'resting_hr_sustained_above', title: 'Resting heart rate stays high',
      sub: 'Notice if it stays above a number for several days',
      paramsHtml: '<div class="cs-aw-params"><label>bpm</label><input type="number" min="40" max="160" value="90" data-p="threshold_bpm"><label>for days</label><input type="number" min="1" max="14" value="3" data-p="window_days"></div>' },
    { id: 'resting_hr_above_baseline', title: 'Resting heart rate runs above usual',
      sub: 'Notice when it\u2019s a few bpm above their baseline',
      paramsHtml: '<div class="cs-aw-params"><label>bpm above usual</label><input type="number" min="3" max="30" value="10" data-p="delta_bpm"></div>' },
    { id: 'daily_steps_below', title: 'Steps drop below a number',
      sub: 'Notice quiet days that stack up',
      paramsHtml: '<div class="cs-aw-params"><label>steps</label><input type="number" min="100" max="15000" value="1000" step="100" data-p="threshold_steps"><label>for days</label><input type="number" min="1" max="14" value="3" data-p="window_days"></div>' },
    { id: 'wearable_silence', title: 'Their watch stops syncing',
      sub: 'Notice if no data comes in for a while',
      paramsHtml: '<div class="cs-aw-params"><label>days quiet</label><input type="number" min="1" max="14" value="3" data-p="silence_days"></div>' },
    { id: 'sleep_duration_below', title: 'Sleep runs short',
      sub: 'Notice if nights get too short, repeatedly',
      paramsHtml: '<div class="cs-aw-params"><label>hours</label><input type="number" min="3" max="9" step="0.5" value="5" data-p="threshold_hours"><label>for nights</label><input type="number" min="1" max="14" value="3" data-p="window_nights"></div>' },
    { id: 'new_record_arrived', title: 'New records land in the chart',
      sub: 'Lab, visit, imaging, discharge, medication',
      paramsHtml: '<div class="cs-aw-params" style="font-size:12px;color:var(--text-muted,#6B6356);">Wellet will notice all five kinds.</div>' },
    { id: 'pcp_visit_gap', title: 'It\u2019s been a while since a PCP visit',
      sub: 'Notice if no primary-care visit in N months',
      paramsHtml: '<div class="cs-aw-params"><label>months</label><input type="number" min="3" max="24" value="12" data-p="months"></div>' },
    { id: 'refill_gap', title: 'A refill is overdue',
      sub: 'Notice if a medication hasn\u2019t been refilled in time',
      paramsHtml: '<div class="cs-aw-params"><label>medication name (optional)</label><input type="text" maxlength="60" placeholder="e.g. Lisinopril" data-p="medication_name"></div>' }
  ];

  var cardsHtml = '';
  for (var i = 0; i < typeOptions.length; i++) {
    var o = typeOptions[i];
    var checked = (i === 0) ? ' checked' : '';
    cardsHtml += ''
      + '<label class="cs-aw-card" data-wt="' + o.id + '">'
      +   '<input type="radio" name="cs-aw-type" value="' + o.id + '"' + checked + ' style="margin-top:3px;flex-shrink:0;">'
      +   '<div style="flex:1;min-width:0;">'
      +     '<div class="cs-aw-card-title">' + escHtml(o.title) + '</div>'
      +     '<div class="cs-aw-card-sub">' + escHtml(o.sub) + '</div>'
      +     '<div class="cs-aw-params-wrap" data-for="' + o.id + '" style="display:' + (i === 0 ? 'flex' : 'none') + ';">' + o.paramsHtml + '</div>'
      +   '</div>'
      + '</label>';
  }

  sheet.innerHTML = ''
    + '<div style="display:flex;align-items:flex-start;gap:12px;margin-bottom:14px;">'
    +   '<div style="width:38px;height:38px;border-radius:12px;background:#EDF3EE;color:#2F4A3A;display:flex;align-items:center;justify-content:center;flex-shrink:0;">'
    +     '<i data-lucide="bell" style="width:18px;height:18px;"></i>'
    +   '</div>'
    +   '<div style="flex:1;min-width:0;">'
    +     '<div style="font-family:\'Fraunces\', Georgia, serif;font-size:20px;font-weight:500;color:#1F2A22;line-height:1.25;margin-bottom:4px;">Tell Wellet what to notice</div>'
    +     '<div style="font-size:13px;color:#6B6356;line-height:1.5;">Pick something below. Wellet will notice it for ' + safeName + ' and send a gentle nudge if it happens.</div>'
    +   '</div>'
    + '</div>'
    + '<div class="cs-aw-cards">' + cardsHtml + '</div>'
    + '<div style="display:flex;gap:10px;margin-top:14px;">'
    +   '<button type="button" id="cs-aw-cancel" style="flex:1;padding:12px 14px;border-radius:11px;border:1px solid #C9D5CD;background:transparent;color:#2F4A3A;font-size:14px;font-weight:500;cursor:pointer;">Cancel</button>'
    +   '<button type="button" id="cs-aw-save" style="flex:1;padding:12px 14px;border-radius:11px;border:1px solid #2F4A3A;background:#2F4A3A;color:#fff;font-size:14px;font-weight:500;cursor:pointer;">Start watching</button>'
    + '</div>'
    + '<div style="font-size:11px;color:#8A8170;text-align:center;margin-top:12px;">You can pause or stop any watch anytime in Settings.</div>';

  overlay.appendChild(sheet);
  if (!document.getElementById('nr-watch-style')) {
    var st = document.createElement('style');
    st.id = 'nr-watch-style';
    st.textContent = '@keyframes nr-fade{from{opacity:0}to{opacity:1}}@keyframes nr-slide{from{transform:translateY(100%)}to{transform:translateY(0)}}';
    document.head.appendChild(st);
  }
  document.body.appendChild(overlay);
  try { initIcons(); } catch (_e) {}

  // Toggle params visibility on radio change
  var radios = sheet.querySelectorAll('input[name="cs-aw-type"]');
  radios.forEach(function(r) {
    r.addEventListener('change', function() {
      sheet.querySelectorAll('.cs-aw-params-wrap').forEach(function(p) {
        p.style.display = (p.getAttribute('data-for') === r.value) ? 'flex' : 'none';
      });
    });
  });

  function close() {
    if (overlay && overlay.parentNode) overlay.parentNode.removeChild(overlay);
  }
  document.getElementById('cs-aw-cancel').addEventListener('click', close);
  overlay.addEventListener('click', function(ev) { if (ev.target === overlay) close(); });

  document.getElementById('cs-aw-save').addEventListener('click', async function(ev) {
    var btn = ev.currentTarget;
    var sel = sheet.querySelector('input[name="cs-aw-type"]:checked');
    if (!sel) return;
    var watchType = sel.value;
    var paramsWrap = sheet.querySelector('.cs-aw-params-wrap[data-for="' + watchType + '"]');
    var parameters = {};
    if (paramsWrap) {
      var inputs = paramsWrap.querySelectorAll('input[data-p]');
      inputs.forEach(function(inp) {
        var key = inp.getAttribute('data-p');
        var val = inp.value;
        if (inp.type === 'number') {
          var n = parseFloat(val);
          if (!isNaN(n)) parameters[key] = n;
        } else if (val && val.trim()) {
          parameters[key] = val.trim();
        }
      });
    }
    // new_record_arrived gets a default kinds array
    if (watchType === 'new_record_arrived') {
      parameters = { kinds: ['lab', 'visit', 'imaging', 'discharge', 'medication'] };
    }
    btn.disabled = true; btn.textContent = 'Saving\u2026';
    try {
      var token = null;
      try {
        var s = await db.auth.getSession();
        token = (s && s.data && s.data.session && s.data.session.access_token) || null;
      } catch (_e) {}
      if (!token) {
        if (typeof showToast === 'function') showToast('Please sign in again to save this.');
        close();
        return;
      }
      var res = await fetch(
        'https://nrpdhxygzyfmyljzfexv.supabase.co/functions/v1/create-care-signal-watch',
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token,
            'apikey': SUPABASE_ANON_KEY
          },
          body: JSON.stringify({
            person_id: currentPersonId,
            watch_type: watchType,
            parameters: parameters
          })
        }
      );
      if (res.ok) {
        if (typeof showToast === 'function') showToast('All set \u2014 I\u2019m watching for this now.');
        close();
        // Refresh the CareSignals view so the new watch appears in the list
        try { setTimeout(renderSignalsView, 150); } catch (_e) {}
      } else {
        var errText = '';
        try { errText = await res.text(); } catch (_e) {}
        console.error('openAddWatchModal create failed', res.status, errText);
        if (typeof showToast === 'function') showToast('Couldn\u2019t save that. Please try again.');
        btn.disabled = false; btn.textContent = 'Start watching';
      }
    } catch (e) {
      console.error('openAddWatchModal exception', e);
      if (typeof showToast === 'function') showToast('Something went wrong. Please try again.');
      btn.disabled = false; btn.textContent = 'Start watching';
    }
  });
}

// ── CareSignals v2: 5-section editorial shell ─────────────────────────────
// Sections (top to bottom):
//   1) Right Now      — synthesized line from recent check-ins / wearable data
//   2) Watches        — active care_signal_watches rows + "Tell Wellet" CTA
//   3) This Week’s Rhythm — sparkline trio (sleep, steps, mood). Skips if empty.
//   4) Care Circle    — last 5 check_ins (from family/friends or self)
//   5) Wearables      — device cards (was the whole view; now at the bottom)
//
// This view no longer requires a wearable to feel inhabited. Watches and
// check-ins carry the surface on their own.
async function _paintSignals(el, sigFirstName, activeConns, terraData) {
  var personId = currentPersonId || null;
  activeConns = activeConns || [];
  var hasDevices = activeConns.length > 0;
  var hasTerraData = hasDevices && terraData && (terraData.vitals.length > 0 || terraData.events.length > 0);

  // Load watches + check-ins + Apple Health rhythm + EHR trends in parallel.
  // Failures are non-fatal — we just render an empty/quiet section.
  var watches = [];
  var checkIns = [];
  var rhythmAH = null; // { heartRate, restingHr, steps, hrv, lastSyncAt }
  var ehrTrends = null; // { bp, weight, labs, meds }
  if (personId && db) {
    try {
      var loads = await Promise.all([
        db.from('care_signal_watches')
          .select('id, person_id, watch_type, parameters, active, paused_at, description, last_fired_at, fire_count, created_at')
          .eq('person_id', personId)
          .order('created_at', { ascending: false })
          .then(function(r){ return (r && r.data) || []; })
          .catch(function(e){ console.error('[Signals] watches load error', e); return []; }),
        db.from('check_ins')
          .select('id, person_id, user_id, mood, pain_level, sleep_quality, notes, energy_level, appetite, source, created_at, checked_in_at')
          .eq('person_id', personId)
          .order('checked_in_at', { ascending: false, nullsFirst: false })
          .order('created_at', { ascending: false })
          .limit(5)
          .then(function(r){ return (r && r.data) || []; })
          .catch(function(e){ console.error('[Signals] check_ins load error', e); return []; }),
        _loadAppleHealthRhythm(personId)
          .catch(function(e){ console.error('[Signals] AH rhythm load error', e); return null; }),
        _loadEhrTrends(personId)
          .catch(function(e){ console.error('[Signals] EHR trends load error', e); return null; })
      ]);
      watches   = loads[0] || [];
      checkIns  = loads[1] || [];
      rhythmAH  = loads[2] || null;
      ehrTrends = loads[3] || null;
    } catch (e) {
      console.error('[Signals] parallel loads failed', e);
    }
  }
  var hasAHData = !!(rhythmAH && (rhythmAH.heartRate || rhythmAH.steps || rhythmAH.hrv || rhythmAH.restingHr));
  var hasData = hasTerraData || hasAHData;

  // ── Editorial masthead (always shown) ───────────────────────────────────
  var activeWatches = watches.filter(function(w){ return w.active !== false; });
  var fmtAgo;
  try { fmtAgo = (typeof formatTimeAgo === 'function') ? formatTimeAgo : null; } catch(e) { fmtAgo = null; }
  var lastSyncStr = '';
  for (var hi = 0; hi < activeConns.length; hi++) {
    var hc = activeConns[hi];
    if (hc.last_data_at && fmtAgo) {
      try { lastSyncStr = fmtAgo(hc.last_data_at); } catch(_e){}
      break;
    }
  }
  var eyebrowBits = [];
  if (activeWatches.length > 0) {
    eyebrowBits.push(activeWatches.length === 1 ? '1 thing to notice' : activeWatches.length + ' things to notice');
  }
  if (lastSyncStr) eyebrowBits.push('Synced ' + lastSyncStr);
  var eyebrow = eyebrowBits.length ? eyebrowBits.join(' \u00b7 ') : 'CareSignals';
  var lede = 'What Wellet is noticing for ' + escHtml(sigFirstName) + ' \u2014 quiet patterns and check-ins from the people closest to them.';

  var ch = '<div class="signals-view">';
  ch += '<header class="view-header">';
  ch += '<p class="view-header__eyebrow">' + escHtml(eyebrow) + '</p>';
  ch += '<h1 class="view-header__title">CareSignals</h1>';
  ch += '<p class="view-header__lede">' + lede + '</p>';
  ch += '</header>';

  // ── 1. Right Now ───────────────────────────────────────────────────────
  var rightNowLine = _buildRightNowLine(sigFirstName, checkIns, activeConns, terraData, rhythmAH);
  if (rightNowLine) {
    ch += '<section class="cs-section cs-section--rightnow">';
    ch += '<div class="cs-section-eyebrow">Right now</div>';
    ch += '<p class="cs-rightnow-line">' + rightNowLine + '</p>';
    ch += '</section>';
  }

  // ── 2. What to notice ─────────────────────────────────────────────────
  ch += '<section class="cs-section cs-section--watches">';
  ch += '<div class="cs-section-head">';
  ch += '<div class="cs-section-eyebrow">What to notice</div>';
  ch += '<button type="button" class="cs-section-action" onclick="openAddWatchModal()">';
  ch += '<i data-lucide="plus" style="width:13px;height:13px;"></i><span>Tell Wellet what to notice</span>';
  ch += '</button>';
  ch += '</div>';
  ch += _renderWatchesSectionHtml(watches, sigFirstName);
  ch += '</section>';

  // ── 3. From your chart (EHR trends) ────────────────────────────────────
  // Shown BEFORE the wearable rhythm because for users without a watch,
  // this is the entire reason CareSignals isn't empty.
  var ehrHtml = _buildEhrTrendsHtml(ehrTrends, sigFirstName);
  if (ehrHtml) {
    ch += '<section class="cs-section cs-section--ehr-trends">';
    ch += '<div class="cs-section-eyebrow">From ' + escHtml(sigFirstName) + '\u2019s chart</div>';
    ch += ehrHtml;
    ch += '</section>';
  }

  // ── 4. This Week\u2019s Rhythm ──────────────────────────────────────────
  var rhythmHtml = _buildRhythmHtml(terraData, rhythmAH, checkIns);
  if (rhythmHtml) {
    ch += '<section class="cs-section cs-section--rhythm">';
    ch += '<div class="cs-section-eyebrow">This week\u2019s rhythm</div>';
    ch += rhythmHtml;
    ch += '</section>';
  }

  // ── 4. Care Circle ─────────────────────────────────────────────────────
  ch += '<section class="cs-section cs-section--circle">';
  ch += '<div class="cs-section-eyebrow">Care circle check-ins</div>';
  ch += _renderCircleSectionHtml(checkIns, sigFirstName);
  ch += '</section>';

  // ── 5. Wearables (demoted) ─────────────────────────────────────────────
  ch += '<section class="cs-section cs-section--devices">';
  ch += '<div class="cs-section-eyebrow">Wearables &amp; devices</div>';
  if (hasDevices) {
    ch += _buildDeviceCardsHtml(activeConns);
    if (hasTerraData) {
      // Re-use the existing wearable grid so heart rate / steps / sleep
      // cards keep their pills + sparklines. We just wrap it.
      ch += _buildWearableGridHtml(activeConns, terraData);
    } else {
      var waitingDevice = activeConns[0].provider ? activeConns[0].provider.charAt(0).toUpperCase() + activeConns[0].provider.slice(1).toLowerCase() : 'device';
      ch += '<div class="signals-waiting">';
      ch += '<i data-lucide="loader" style="width:18px;height:18px;animation:spin 1s linear infinite;"></i>';
      ch += '<div class="signals-waiting-text">Waiting for first sync from ' + escHtml(waitingDevice) + '\u2026</div>';
      ch += '<div class="signals-waiting-sub">Data will appear here once your device syncs.</div>';
      ch += '</div>';
    }
  } else if (hasAHData) {
    // Apple Health is the "device" — the iPhone itself. Show a single
    // device-style row instead of the third-party wearables grid.
    ch += _buildAppleHealthDeviceCardHtml(rhythmAH);
  } else {
    ch += '<div class="cs-devices-empty">';
    ch += '<div class="cs-devices-empty-title">No wearable connected</div>';
    ch += '<div class="cs-devices-empty-sub">Wellet works without a wearable. Add one when you\u2019re ready and we\u2019ll fold sleep, steps, and heart rate into the picture above.</div>';
    ch += '<button class="terra-add-btn" onclick="openTerraConnect()"><i data-lucide="plus" style="width:14px;height:14px;"></i> Connect a device</button>';
    ch += '<div class="terra-poweredby">Wearables powered by <a href="https://tryterra.co" target="_blank" rel="noopener noreferrer">Terra</a></div>';
    ch += '</div>';
  }
  ch += '</section>';

  ch += '</div>';
  el.innerHTML = ch;
  initIcons();
  return;

  // ── Legacy empty/no-data short circuit (unused; v2 always renders shell) ──
  if (false && (!activeConns || activeConns.length === 0)) {
    var emptyHtml = '<div class="signals-view">';
    emptyHtml += '<p class="section-label">' + escHtml(sigFirstName) + '\u2019s Signals</p>';
    emptyHtml += '<div class="terra-empty">';
    emptyHtml += '<div class="terra-empty-icon"><i data-lucide="watch"></i></div>';
    emptyHtml += '<div class="terra-empty-title">No devices connected yet</div>';
    emptyHtml += '<div class="terra-empty-sub">Connect a wearable to see daily signals \u2014 steps, sleep, heart rate, and more.</div>';
    emptyHtml += '<button class="terra-add-btn" onclick="openTerraConnect()"><i data-lucide="plus" style="width:14px;height:14px;"></i> Connect a device</button>';
    emptyHtml += '<div class="terra-poweredby">Wearables powered by <a href="https://tryterra.co" target="_blank" rel="noopener noreferrer">Terra</a></div>';
    emptyHtml += '</div></div>';
    el.innerHTML = emptyHtml;
    initIcons();
    return;
  }

  // Build device cards (always shown at top)
  var chDevices = _buildDeviceCardsHtml(activeConns);

  var hasData = terraData && (terraData.vitals.length > 0 || terraData.events.length > 0);

  // ── Editorial view header (Fraunces masthead anchor) ──
  // Eyebrow: most-recent device + how long ago it last sent data.
  var _hdrConn = activeConns[0];
  var _hdrProvider = _hdrConn && _hdrConn.provider
    ? _hdrConn.provider.charAt(0).toUpperCase() + _hdrConn.provider.slice(1).toLowerCase()
    : 'Device';
  var _hdrAgo = '';
  for (var _hi = 0; _hi < activeConns.length; _hi++) {
    var _hc = activeConns[_hi];
    if (_hc.last_data_at) {
      try { _hdrAgo = formatTimeAgo(_hc.last_data_at); } catch(e) {}
      _hdrProvider = _hc.provider ? _hc.provider.charAt(0).toUpperCase() + _hc.provider.slice(1).toLowerCase() : _hdrProvider;
      break;
    }
  }
  var _hdrEyebrow = _hdrAgo ? (_hdrProvider + ' \u00b7 Synced ' + _hdrAgo) : (_hdrProvider + ' \u00b7 Connected');
  var _hdrLede = 'Daily rhythms from ' + escHtml(sigFirstName) + '\u2019s wearables, sensors, and medications \u2014 patterns you might miss.';

      var ch = '<div class="signals-view">';
      ch += '<header class="view-header">';
      ch += '<p class="view-header__eyebrow">' + escHtml(_hdrEyebrow) + '</p>';
      ch += '<h1 class="view-header__title">CareSignals</h1>';
      ch += '<p class="view-header__lede">' + _hdrLede + '</p>';
      ch += '</header>';
      ch += chDevices;

      if (!hasData) {
        // Connected but no data yet
        var waitingDevice = activeConns[0].provider ? activeConns[0].provider.charAt(0).toUpperCase() + activeConns[0].provider.slice(1).toLowerCase() : 'device';
        ch += '<div class="signals-waiting">';
        ch += '<i data-lucide="loader" style="width:18px;height:18px;animation:spin 1s linear infinite;"></i>';
        ch += '<div class="signals-waiting-text">Waiting for first sync from ' + escHtml(waitingDevice) + '\u2026</div>';
        ch += '<div class="signals-waiting-sub">Data will appear here once your device syncs.</div>';
        ch += '</div>';
      } else {
        // Build real wearable dashboard
        var rw = buildRealSignalsData(terraData.vitals, terraData.events, activeConns);
        var rNow = new Date();
        var rMonths = ['January','February','March','April','May','June','July','August','September','October','November','December'];
        var rDays = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
        var rDateStr = rDays[rNow.getDay()] + ', ' + rMonths[rNow.getMonth()] + ' ' + rNow.getDate();

        // ── Medications Section (real data from liveMeds) ──
        var rActiveMeds = liveMeds.filter(function(m) { return m.active; });
        if (rActiveMeds.length > 0) {
          ch += '<div class="signals-section">';
          ch += '<div class="signals-section-title">Today\u2019s Medications</div>';
          ch += '<div class="signals-section-sub">' + escHtml(rDateStr) + '</div>';
          ch += '<div class="signals-card">';
          for (var rmi = 0; rmi < rActiveMeds.length; rmi++) {
            var rMed = rActiveMeds[rmi];
            var rRem = _medReminders[rMed.id];
            var rTimes = (rRem && rRem.active && rRem.times && rRem.times.length > 0) ? rRem.times : [];
            ch += '<div class="med-item">';
            ch += '<div class="med-icon-wrap"><i data-lucide="pill"></i></div>';
            ch += '<div class="med-info">';
            ch += '<div class="med-name">' + escHtml(rMed.name || '') + '</div>';
            var rDoseFreq = [rMed.dose, rMed.frequency].filter(Boolean).join(' \u00b7 ');
            if (rDoseFreq) ch += '<div class="med-dose">' + escHtml(rDoseFreq) + '</div>';
            if (rTimes.length > 0) {
              ch += '<div class="med-times">';
              for (var rti = 0; rti < rTimes.length; rti++) {
                var rStatus = getMedStatus(rTimes[rti], rNow, -1);
                var rBadgeClass = 'med-badge med-badge--' + rStatus;
                var rStatusIcon = '';
                var rStatusLabel = '';
                if (rStatus === 'taken') { rStatusIcon = '\u2705'; rStatusLabel = 'Taken'; }
                else if (rStatus === 'missed') { rStatusIcon = '\u26a0\ufe0f'; rStatusLabel = 'Missed'; }
                else if (rStatus === 'due') { rStatusIcon = '\ud83d\udd14'; rStatusLabel = 'Due now'; }
                else { rStatusIcon = '\u23f0'; rStatusLabel = 'Upcoming'; }
                ch += '<span class="' + rBadgeClass + '">' + rStatusIcon + ' ' + formatTime12(rTimes[rti]) + ' \u00b7 ' + rStatusLabel + '</span>';
              }
              ch += '</div>';
            }
            ch += '</div></div>';
          }
          ch += '</div></div>';
        }

        // ── Wearable Data Section ──
        ch += '<div class="signals-section">';
        ch += '<div class="signals-section-title">' + escHtml(rw.device) + ' \u00b7 ' + escHtml(rw.personName);
        if (rw.lastSync) ch += '<span class="wearable-sync">' + escHtml(rw.lastSync) + '</span>';
        ch += '</div>';
        ch += '<div class="signals-section-sub">Live wearable data</div>';
        ch += '<div class="wearable-grid">';

        // Heart rate card
        if (rw.heartRate) {
          ch += '<div class="wearable-card">';
          ch += '<div class="signals-label">' + t('signals.heartRate') + '</div>';
          ch += '<div class="signals-metric">' + rw.heartRate.current + ' <span style="font-size:var(--type-body);font-weight:400;color:var(--text-secondary);">bpm</span></div>';
          if (rw.heartRate.trend && rw.heartRate.trend.length >= 2) {
            ch += '<div class="wearable-sparkline">' + buildSparkline(rw.heartRate.trend, 120, 28, 'var(--red)') + '</div>';
          }
          ch += '<div class="signals-metric-sm">' + rw.heartRate.min + '\u2013' + rw.heartRate.max + ' range</div>';
          if (rw.heartRate.resting) ch += '<div class="signals-metric-sm">Resting: ' + rw.heartRate.resting + ' bpm</div>';
          ch += renderWearablePills('heart_rate', rw.personName);
          ch += '</div>';
        }

        // Steps card
        if (rw.steps) {
          var rStepsPct = Math.round(rw.steps.today / rw.steps.goal * 100);
          ch += '<div class="wearable-card">';
          ch += '<div class="signals-label">' + t('signals.steps') + '</div>';
          ch += '<div class="signals-metric">' + rw.steps.today.toLocaleString() + '</div>';
          ch += '<div class="progress-ring-wrap">';
          ch += buildProgressRing(rStepsPct, 40, 'var(--moss)');
          ch += '<div class="progress-ring-label">' + rStepsPct + '% of goal</div>';
          ch += '</div>';
          if (rw.calories) ch += '<div class="signals-metric-sm">' + rw.calories.toLocaleString() + ' active cal</div>';
          if (rw.distance) ch += '<div class="signals-metric-sm">' + rw.distance + ' mi</div>';
          ch += renderWearablePills('steps', rw.personName);
          ch += '</div>';
        }

        // Sleep card
        if (rw.sleep) {
          var rSleepH = Math.floor(rw.sleep.total / 60);
          var rSleepM = rw.sleep.total % 60;
          ch += '<div class="wearable-card">';
          ch += '<div class="signals-label">' + t('signals.sleep') + '</div>';
          ch += '<div class="signals-metric">' + rSleepH + 'h ' + rSleepM + 'm</div>';
          ch += buildSleepBar(rw.sleep);
          if (rw.sleep.bedTime || rw.sleep.wakeTime) {
            ch += '<div class="signals-metric-sm">' + escHtml(rw.sleep.bedTime) + (rw.sleep.wakeTime ? ' \u2013 ' + escHtml(rw.sleep.wakeTime) : '') + '</div>';
          }
          ch += renderWearablePills('sleep', rw.personName);
          ch += '</div>';
        }

        // SpO2 card
        if (rw.spo2) {
          ch += '<div class="wearable-card">';
          ch += '<div class="signals-label">' + t('signals.bloodOxygen') + '</div>';
          ch += '<div class="signals-metric">' + rw.spo2.current + '<span style="font-size:var(--type-body);font-weight:400;">%</span></div>';
          ch += '<div style="display:flex;align-items:center;gap:4px;margin-top:4px;"><span style="width:8px;height:8px;border-radius:50%;background:var(--moss);display:inline-block;"></span>';
          ch += '<span class="signals-metric-sm">' + rw.spo2.min + '\u2013' + rw.spo2.max + '% range</span></div>';
          ch += '</div>';
        }

        // HRV card
        if (rw.hrv) {
          ch += '<div class="wearable-card">';
          ch += '<div class="signals-label">HRV</div>';
          ch += '<div class="signals-metric">' + rw.hrv.current + ' <span style="font-size:var(--type-body);font-weight:400;color:var(--text-secondary);">' + escHtml(rw.hrv.unit) + '</span></div>';
          ch += '<div class="signals-metric-sm">Heart rate variability</div>';
          ch += '</div>';
        }

    ch += '</div>'; // close wearable-grid
    ch += '</div>'; // close signals-section
  }

  ch += '</div>'; // close signals-view
  el.innerHTML = ch;
  initIcons();
}

// ── CARE SIGNALS v1: per-card pills ──────────────────────────────────────────
// Renders the [Share] [\ud83d\udd14 Notify me] pills inside a wearable card.
// metric: 'heart_rate' | 'steps' | 'sleep'  (SpO2 + HRV intentionally omitted)
// personName: first name of the loved one (for chat-mode label only)
function renderWearablePills(metric, personName) {
  var safeMetric = String(metric || '').replace(/[^a-z_]/g, '');
  var safeName = (personName || '').replace(/[^A-Za-z0-9 \-\u00C0-\u024F]/g, '');
  var encName = escHtml(safeName);
  return ''
    + '<div class="wearable-pill-row">'
    +   '<button class="wearable-pill wearable-pill-share" type="button" '
    +           'onclick="shareWearableMetric(\'' + safeMetric + '\',\'' + encName + '\')" '
    +           'aria-label="Share this with your care circle">'
    +     '<i data-lucide="share-2" class="wearable-pill-icon"></i>'
    +     '<span>Share</span>'
    +   '</button>'
    +   '<button class="wearable-pill wearable-pill-notify" type="button" '
    +           'onclick="openAskWithWatchContext(\'' + safeMetric + '\',\'' + encName + '\')" '
    +           'aria-label="Have Wellet notice changes in this">'
    +     '<i data-lucide="bell" class="wearable-pill-icon"></i>'
    +     '<span>Notify me</span>'
    +   '</button>'
    + '</div>';
}

// Share a wearable metric snapshot via the existing Care Circle share sheet.
// We register a lightweight item shape into _shareRegistry and open the sheet.
function shareWearableMetric(metric, personName) {
  try {
    var labels = { heart_rate: 'Heart rate', steps: 'Daily steps', sleep: 'Sleep' };
    var title = (labels[metric] || 'Wearable update') + (personName ? ' \u00B7 ' + personName : '');
    var key = registerShareItem({
      kind: 'pattern',
      subKind: 'wearable_snapshot',
      metric: metric,
      title: title,
      date: new Date().toISOString(),
      notes: 'Snapshot of today\u2019s ' + (labels[metric] || metric).toLowerCase() + '.'
    });
    if (typeof openShareSheet === 'function') openShareSheet(key);
  } catch (e) { console.error('shareWearableMetric', e); }
}

// "Notify me" pill: prime Ask Wellet with a watch-mode context and switch tabs.
// The chip + suggestion chips will reflect watch intent; sendAskMessage()
// will POST { mode:'watch', text, person_id, context } to ask-wellet v24.
function openAskWithWatchContext(metric, personName) {
  var labels = { heart_rate: 'heart rate', steps: 'daily steps', sleep: 'sleep' };
  window._pendingAskContext = {
    intent: 'watch',
    metric: metric,
    personName: personName || '',
    label: labels[metric] || metric
  };
  try { switchNavTo('ask'); } catch (e) {}
  setTimeout(function() {
    try { _renderAskContextChip(); } catch (e) {}
    // Swap the starter suggestion chips for watch-mode chips
    try {
      var chips = document.getElementById('suggestion-chips');
      if (chips && typeof buildWatchSuggestionChips === 'function') {
        chips.innerHTML = buildWatchSuggestionChips(personName || '');
        chips.style.display = '';
        if (typeof initIcons === 'function') initIcons();
      }
    } catch (e) {}
    var input = document.getElementById('ask-input');
    if (input) input.focus();
  }, 60);
}

// Demo-mode renderer — aligned with live _paintSignals() structure.
// Uses DEMO_TIMELINE_EXTRAS watches + check-ins + DEMO_EHR_DATA for EHR trends.
// Preserves the wearable data section (demo has Apple Watch data) but removes
// the legacy medication checklist, adherence chart, and home sensors sections.
function _renderSignalsDemo(el, data, demoFirstName) {
  var demoName = demoFirstName || 'Dad';

  // Pull demo watches + check-ins from the timeline extras seed data.
  var demoExtras = (typeof DEMO_TIMELINE_EXTRAS !== 'undefined') ? DEMO_TIMELINE_EXTRAS : {};
  var watches = demoExtras.careSignalWatches || [];
  var checkIns = demoExtras.checkIns || [];

  // Demo EHR trends — build a lightweight representation from DEMO_EHR_DATA
  // so the "From your chart" section renders something honest.
  var demoEhr = (typeof DEMO_EHR_DATA !== 'undefined') ? DEMO_EHR_DATA : null;
  var demoEhrTrends = null;
  if (demoEhr) {
    // Build BP + weight trends from the new vital-signs observation seeds so the
    // CareSignals "From your chart" section renders the same BP + weight cards
    // that ship in the live product.
    var _vitals = (demoEhr.observations || []).filter(function(o){ return o.category === 'vital-signs'; });
    var _sysObs = _vitals.filter(function(o){ return o.code === '8480-6'; }).sort(function(a,b){ return a.effective_date.localeCompare(b.effective_date); });
    var _diaObs = _vitals.filter(function(o){ return o.code === '8462-4'; }).sort(function(a,b){ return a.effective_date.localeCompare(b.effective_date); });
    var _wtObs  = _vitals.filter(function(o){ return o.code === '29463-7'; }).sort(function(a,b){ return a.effective_date.localeCompare(b.effective_date); });
    var _bp = null;
    if (_sysObs.length > 0 && _diaObs.length > 0) {
      var _latestSys = _sysObs[_sysObs.length-1];
      var _latestDia = _diaObs[_diaObs.length-1];
      _bp = {
        latest: _latestSys.value + '/' + _latestDia.value,
        latestDate: _latestSys.effective_date,
        systolic: _sysObs.map(function(o){ return parseInt(o.value, 10); }),
        diastolic: _diaObs.map(function(o){ return parseInt(o.value, 10); }),
        summary: 'Morning readings run ~15 mmHg higher than afternoon'
      };
    }
    var _wt = null;
    if (_wtObs.length > 0) {
      var _latestWt = _wtObs[_wtObs.length-1];
      _wt = {
        latest: _latestWt.value + ' lb',
        latestDate: _latestWt.effective_date,
        values: _wtObs.map(function(o){ return parseFloat(o.value); }),
        summary: 'Down 5 lb over 8 months'
      };
    }
    demoEhrTrends = {
      meds: demoEhr.medications || [],
      conditions: demoEhr.conditions || [],
      bp: _bp,
      weight: _wt
    };
  }

  var ch = '<div class="signals-view">';

  // \u2500\u2500 Editorial masthead \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  var activeWatches = watches.filter(function(w){ return w.active !== false; });
  var eyebrowBits = [];
  if (activeWatches.length > 0) {
    eyebrowBits.push(activeWatches.length === 1 ? '1 thing to notice' : activeWatches.length + ' things to notice');
  }
  eyebrowBits.push('Apple Watch \u00b7 Synced 8 min ago');
  var eyebrow = eyebrowBits.join(' \u00b7 ');
  var lede = 'What Wellet is noticing for ' + escHtml(demoName) + ' \u2014 quiet patterns and check-ins from the people closest to them.';

  ch += '<header class="view-header">';
  ch += '<p class="view-header__eyebrow">' + escHtml(eyebrow) + '</p>';
  ch += '<h1 class="view-header__title">CareSignals</h1>';
  ch += '<p class="view-header__lede">' + lede + '</p>';
  ch += '</header>';

  // \u2500\u2500 1. What to notice (watches) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  ch += '<section class="cs-section cs-section--watches">';
  ch += '<div class="cs-section-head">';
  ch += '<div class="cs-section-eyebrow">What to notice</div>';
  ch += '<button type="button" class="cs-section-action" onclick="openAddWatchModal()">';
  ch += '<i data-lucide="plus" style="width:13px;height:13px;"></i><span>Tell Wellet what to notice</span>';
  ch += '</button>';
  ch += '</div>';
  ch += (typeof _renderWatchesSectionHtml === 'function')
    ? _renderWatchesSectionHtml(watches, demoName)
    : '';
  ch += '</section>';

  // \u2500\u2500 2. From your chart (EHR trends) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  // For demo we build a lightweight static "From your chart" section using
  // DEMO_EHR_DATA instead of calling the async _loadEhrTrends() edge function.
  if (demoEhrTrends && (demoEhrTrends.meds.length > 0 || demoEhrTrends.conditions.length > 0 || demoEhrTrends.bp || demoEhrTrends.weight)) {
    ch += '<section class="cs-section cs-section--ehr-trends">';
    ch += '<div class="cs-section-eyebrow">From ' + escHtml(demoName) + '\u2019s chart</div>';
    // Shipped BP + weight cards — delegate to the live renderer so demo matches production.
    if ((demoEhrTrends.bp || demoEhrTrends.weight) && typeof _buildEhrTrendsHtml === 'function') {
      // Pass a copy without meds/conditions so the live renderer only emits the
      // BP + weight cards (we already render meds + conditions below in the
      // simpler demo mini-lists, which match the rest of the demo's aesthetic).
      ch += _buildEhrTrendsHtml({ bp: demoEhrTrends.bp, weight: demoEhrTrends.weight, labs: [], meds: [] }, demoName);
    }
    // Active medications mini-list
    if (demoEhrTrends.meds.length > 0) {
      ch += '<div class="cs-ehr-card">';
      ch += '<div class="cs-ehr-card-title"><i data-lucide="pill" style="width:14px;height:14px;color:var(--amber);"></i> Active medications from EHR</div>';
      ch += '<div class="cs-ehr-card-body">';
      demoEhrTrends.meds.slice(0, 4).forEach(function(m) {
        ch += '<div class="cs-ehr-med-row">'
          + '<span class="cs-ehr-med-name">' + escHtml(m.name || '') + '</span>'
          + (m.dosage ? '<span class="cs-ehr-med-dose">' + escHtml(m.dosage) + '</span>' : '')
          + '</div>';
      });
      ch += '</div></div>';
    }
    // Active conditions mini-list
    if (demoEhrTrends.conditions.length > 0) {
      ch += '<div class="cs-ehr-card" style="margin-top:10px;">';
      ch += '<div class="cs-ehr-card-title"><i data-lucide="heart-pulse" style="width:14px;height:14px;color:var(--moss);"></i> Active conditions from EHR</div>';
      ch += '<div class="cs-ehr-card-body">';
      demoEhrTrends.conditions.slice(0, 4).forEach(function(c) {
        ch += '<div class="cs-ehr-med-row">'
          + '<span class="cs-ehr-med-name">' + escHtml(c.name || '') + '</span>'
          + (c.status ? '<span class="cs-ehr-med-dose">' + escHtml(c.status) + '</span>' : '')
          + '</div>';
      });
      ch += '</div></div>';
    }
    ch += '</section>';
  }

  // \u2500\u2500 3. This week\u2019s rhythm (wearable) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  // Use the legacy wearable grid section which has the demo Apple Watch data.
  var w = data && data.wearable ? data.wearable : null;
  if (w) {
    ch += '<section class="cs-section cs-section--rhythm">';
    ch += '<div class="cs-section-eyebrow">This week\u2019s rhythm</div>';
    ch += '<div class="wearable-grid">';
    // Heart rate card
    if (w.heartRate) {
      ch += '<div class="wearable-card">';
      ch += '<div class="signals-label">' + (typeof t === 'function' ? t('signals.heartRate') : 'Heart rate') + '</div>';
      ch += '<div class="signals-metric">' + escHtml(String(w.heartRate.current)) + ' <span style="font-size:var(--type-body);font-weight:400;color:var(--text-secondary);">bpm</span></div>';
      if (w.heartRate.trend && typeof buildSparkline === 'function') {
        ch += '<div class="wearable-sparkline">' + buildSparkline(w.heartRate.trend, 120, 28, 'var(--signal-warm)') + '</div>';
      }
      ch += '<div class="signals-metric-sm">' + w.heartRate.min + '\u2013' + w.heartRate.max + ' today</div>';
      ch += '</div>';
    }
    // Steps card
    if (w.steps) {
      var stepsPct = Math.round(w.steps.today / w.steps.goal * 100);
      ch += '<div class="wearable-card">';
      ch += '<div class="signals-label">' + (typeof t === 'function' ? t('signals.steps') : 'Steps') + '</div>';
      ch += '<div class="signals-metric">' + w.steps.today.toLocaleString() + '</div>';
      if (typeof buildProgressRing === 'function') {
        ch += '<div class="progress-ring-wrap">';
        ch += buildProgressRing(stepsPct, 40, 'var(--moss)');
        ch += '<div class="progress-ring-label">' + stepsPct + '% of goal</div>';
        ch += '</div>';
      }
      ch += '</div>';
    }
    // Sleep card
    if (w.sleep) {
      var sleepH = Math.floor(w.sleep.total / 60);
      var sleepM = w.sleep.total % 60;
      ch += '<div class="wearable-card">';
      ch += '<div class="signals-label">' + (typeof t === 'function' ? t('signals.sleep') : 'Sleep') + '</div>';
      ch += '<div class="signals-metric">' + sleepH + 'h ' + sleepM + 'm</div>';
      if (typeof buildSleepBar === 'function') ch += buildSleepBar(w.sleep);
      ch += '</div>';
    }
    ch += '</div></section>';
  }

  // \u2500\u2500 4. Care circle check-ins \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  ch += '<section class="cs-section cs-section--circle">';
  ch += '<div class="cs-section-eyebrow">Care circle check-ins</div>';
  ch += (typeof _renderCircleSectionHtml === 'function')
    ? _renderCircleSectionHtml(checkIns, demoName)
    : '';
  ch += '</section>';

  // \u2500\u2500 5. Wearables & devices \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  // Show a static demo device card (Apple Watch) to illustrate the connection UI.
  ch += '<section class="cs-section cs-section--devices">';
  ch += '<div class="cs-section-eyebrow">Wearables &amp; devices</div>';
  ch += '<div class="cs-device-card">';
  ch += '<div class="cs-device-card-top">';
  ch += '<i data-lucide="watch" style="width:20px;height:20px;color:var(--moss);"></i>';
  ch += '<div class="cs-device-card-meta">';
  ch += '<div class="cs-device-card-name">Apple Watch</div>';
  ch += '<div class="cs-device-card-sub">via Health Sharing \u00b7 Synced 8 min ago</div>';
  ch += '</div>';
  ch += '<span class="cs-device-card-status">Connected</span>';
  ch += '</div></div>';
  ch += '</section>';

  ch += '</div>'; // .signals-view

  el.innerHTML = ch;
  if (typeof initIcons === 'function') initIcons();
}

// Load cached EHR data from localStorage
function loadEhrCache(personId) {
  if (!personId) return null;
  try {
    var key = 'wellet_ehr_' + personId;
    var cached = localStorage.getItem(key);
    if (cached) {
      var parsed = JSON.parse(cached);
      ehrCache[personId] = parsed;
      // Fire practitioner enrichment off the cached care_team so the app
      // can light up Call/Email/Map links without waiting for a fresh sync.
      try {
        if (typeof enrichPractitionersForPerson === 'function' &&
            parsed && Array.isArray(parsed.care_team) && parsed.care_team.length) {
          enrichPractitionersForPerson(personId, parsed.care_team, parsed.provider || {});
        }
      } catch(_e) {}
      return parsed;
    }
  } catch(e) { console.warn('EHR cache read error:', e); }
  return null;
}

// Save EHR data to localStorage
function saveEhrCache(personId, data) {
  if (!personId || !data) return;
  try {
    var key = 'wellet_ehr_' + personId;
    ehrCache[personId] = data;
    localStorage.setItem(key, JSON.stringify(data));
  } catch(e) { console.warn('EHR cache write error:', e); }
}

// Clear EHR cache for a person
function clearEhrCache(personId) {
  if (!personId) return;
  try {
    delete ehrCache[personId];
    localStorage.removeItem('wellet_ehr_' + personId);
    // Also clear v2 cache (keyed per-connection) so a wipe is consistent
    // across both shapes regardless of which path the caller is on.
    delete ehrCacheV2[personId];
    localStorage.removeItem('wellet_ehr_v2_' + personId);
  } catch(e) {}
}

// ── EHR CACHE V2 (per-connection, gated by localStorage.welletPhase2) ─────────
// v1 stores ONE flat ehrData per person. v2 stores N connections per person and
// merges them on read. Both shapes coexist; v1 is untouched so the flag can
// flip ON or OFF freely without losing data. saveEhrCache() writes BOTH shapes
// when the response includes _phase2 + connections[] (always true on v55+).
//
// Storage key:  wellet_ehr_v2_<personId>
// Storage shape:
//   { version: 2,
//     connections: { <connection_id>: { hospital_name, fhir_base_url,
//       patient_id, provider, status, conditions, medications, allergies,
//       observations, immunizations, diagnostic_reports, visits, care_team,
//       patient, synced_at, last_data_at, result_counts, _diagnostic } } }
var ehrCacheV2 = {}; // in-memory mirror, lazy-loaded from localStorage

function _v2Key(personId) { return 'wellet_ehr_v2_' + personId; }

function loadEhrCacheV2(personId) {
  if (!personId) return null;
  if (ehrCacheV2[personId]) return ehrCacheV2[personId];
  try {
    var raw = localStorage.getItem(_v2Key(personId));
    if (!raw) return null;
    var parsed = JSON.parse(raw);
    if (!parsed || parsed.version !== 2 || !parsed.connections) return null;
    ehrCacheV2[personId] = parsed;
    return parsed;
  } catch(e) { console.warn('EHR v2 cache read error:', e); return null; }
}

// Save the v2 shape for a person. Drops connections that are no longer
// present in the latest fetch-ehr-data response (server-side disconnect).
function saveEhrCacheV2(personId, data) {
  if (!personId || !data || !data._phase2 || !Array.isArray(data.connections)) return;
  try {
    var byId = {};
    for (var i = 0; i < data.connections.length; i++) {
      var c = data.connections[i];
      if (!c || !c.connection_id) continue;
      byId[c.connection_id] = c;
    }
    var v2 = { version: 2, connections: byId, _phase2: true };
    ehrCacheV2[personId] = v2;
    localStorage.setItem(_v2Key(personId), JSON.stringify(v2));
  } catch(e) { console.warn('EHR v2 cache write error:', e); }
}

// Merge all connections for a person into the same flat shape v1 produced,
// so every existing caller (renderRecordsView, openRecordsDetail, timeline,
// AskWellet, etc.) keeps working unchanged. Each row is stamped with
// _connection_id and _hospital_name so later UI (hospital pills, per-row
// provenance) can read it without another lookup.
function getMergedEhr(personId) {
  var v2 = loadEhrCacheV2(personId);
  if (!v2 || !v2.connections) return null;
  var ids = Object.keys(v2.connections);
  if (ids.length === 0) return null;

  // Sort by sort_order ascending if present, otherwise by synced_at descending
  // (most-recently-synced first). v55 doesn't expose sort_order in the
  // response yet — fall back to synced_at until it does.
  ids.sort(function(a, b) {
    var ca = v2.connections[a] || {};
    var cb = v2.connections[b] || {};
    if (ca.sort_order != null && cb.sort_order != null) return ca.sort_order - cb.sort_order;
    var ta = ca.synced_at ? new Date(ca.synced_at).getTime() : 0;
    var tb = cb.synced_at ? new Date(cb.synced_at).getTime() : 0;
    return tb - ta;
  });

  var ARRAY_KEYS = ['conditions','medications','allergies','observations',
    'immunizations','diagnostic_reports','visits','care_team'];
  var merged = {
    conditions: [], medications: [], allergies: [], observations: [],
    immunizations: [], diagnostic_reports: [], visits: [], care_team: [],
    _connections: [],
  };

  var providerNames = [];
  var maxSyncedMs = 0;
  var maxSyncedIso = null;
  var firstPatient = null;
  var firstExpectedPatientId = null;

  for (var k = 0; k < ids.length; k++) {
    var conn = v2.connections[ids[k]];
    if (!conn) continue;

    if (conn.hospital_name) providerNames.push(conn.hospital_name);
    if (conn.synced_at) {
      var t = new Date(conn.synced_at).getTime();
      if (t > maxSyncedMs) { maxSyncedMs = t; maxSyncedIso = conn.synced_at; }
    }
    if (!firstPatient && conn.patient) firstPatient = conn.patient;
    if (!firstExpectedPatientId && conn.patient_id) firstExpectedPatientId = conn.patient_id;

    // Per-connection summary (used by hospital pills + reconnect banners)
    merged._connections.push({
      connection_id: conn.connection_id,
      hospital_name: conn.hospital_name,
      fhir_base_url: conn.fhir_base_url,
      patient_id: conn.patient_id,
      provider: conn.provider,
      status: conn.status,
      synced_at: conn.synced_at,
      result_counts: conn.result_counts,
    });

    for (var ak = 0; ak < ARRAY_KEYS.length; ak++) {
      var key = ARRAY_KEYS[ak];
      var rows = Array.isArray(conn[key]) ? conn[key] : [];
      for (var ri = 0; ri < rows.length; ri++) {
        var row = rows[ri];
        if (!row) continue;
        // Stamp source-of-truth without mutating the original cached row.
        var stamped = {};
        for (var p in row) { if (Object.prototype.hasOwnProperty.call(row, p)) stamped[p] = row[p]; }
        if (!stamped._connection_id) stamped._connection_id = conn.connection_id;
        if (!stamped._hospital_name) stamped._hospital_name = conn.hospital_name;
        merged[key].push(stamped);
      }
    }
  }

  merged.provider = providerNames.length > 1 ? providerNames.join(', ') : (providerNames[0] || 'EHR');
  merged.synced_at = maxSyncedIso;
  if (firstPatient) merged.patient = firstPatient;
  if (firstExpectedPatientId) merged.expected_patient_id = firstExpectedPatientId;
  merged._phase2 = true;

  return merged;
}

function isPhase2Enabled() {
  try { return localStorage.getItem('welletPhase2') === '1'; } catch(e) { return false; }
}

// Update the Settings → Developer preview row to reflect current flag state.
function updatePhase2ToggleUI() {
  var btn = document.getElementById('phase2-toggle-btn');
  var desc = document.getElementById('phase2-toggle-desc');
  if (!btn || !desc) return;
  var on = isPhase2Enabled();
  // Detect whether the active loved one already has 2+ connected hospitals.
  // When they do, Phase 2 auto-enables (see saveEhrCache), so the toggle is
  // really a status indicator at that point — surface that in the copy.
  var nConn = 0;
  try {
    var v2 = currentPersonId ? loadEhrCacheV2(currentPersonId) : null;
    if (v2 && v2.connections) nConn = Object.keys(v2.connections).length;
  } catch(e) {}
  if (on) {
    btn.textContent = 'Turn off';
    btn.style.background = 'var(--moss)';
    btn.style.color = '#fff';
    btn.style.borderColor = 'var(--moss)';
    if (nConn >= 2) {
      desc.textContent = 'On (auto) — ' + nConn + ' hospitals connected. Records merges them all.';
    } else {
      desc.textContent = 'On — Records reads the merged multi-hospital cache.';
    }
  } else {
    btn.textContent = 'Turn on';
    btn.style.background = '#eef2f0';
    btn.style.color = 'var(--text-primary)';
    btn.style.borderColor = 'var(--border)';
    desc.textContent = 'Off — single-hospital cache. Auto-enables when a 2nd hospital connects.';
  }
}

// Tap handler for the toggle button.
function togglePhase2Flag() {
  try {
    if (isPhase2Enabled()) {
      localStorage.removeItem('welletPhase2');
      try { showToast('Multi-hospital preview off'); } catch(e){}
    } else {
      localStorage.setItem('welletPhase2', '1');
      try { showToast('Multi-hospital preview on'); } catch(e){}
    }
  } catch(e) { console.warn('phase2 toggle:', e); }
  updatePhase2ToggleUI();
  // Re-render the views that read getEhrData() so the change takes effect
  // immediately without a hard reload.
  try { if (typeof renderRecordsView === 'function') renderRecordsView(); } catch(e){}
  try { if (typeof renderTimeline === 'function') renderTimeline(); } catch(e){}
}

// ── TRIALS TILE TOGGLE ───────────────────────────────────────────────────────────────────
function updateTrialsToggleUI() {
  var btn  = document.getElementById('trials-toggle-btn');
  if (!btn) return;
  var on = isTrialsTileEnabled();
  if (on) {
    btn.textContent  = 'On';
    btn.style.background   = 'var(--moss)';
    btn.style.color        = '#fff';
    btn.style.borderColor  = 'var(--moss)';
  } else {
    btn.textContent  = 'Off';
    btn.style.background   = '#eef2f0';
    btn.style.color        = 'var(--text-primary)';
    btn.style.borderColor  = 'var(--border)';
  }
}

function toggleTrialsTileFlag() {
  try {
    if (isTrialsTileEnabled()) {
      localStorage.setItem(TRIALS_PREF_KEY, '0');
      try { showToast('Trials tile off'); } catch(e) {}
    } else {
      localStorage.setItem(TRIALS_PREF_KEY, '1');
      try { showToast('Trials tile on'); } catch(e) {}
    }
  } catch(e) { console.warn('trials toggle:', e); }
  updateTrialsToggleUI();
}

// Check if cached EHR data is stale (older than 15 minutes).
// 2026-05-04: tightened from 30→15 min so reopening the app reliably picks
// up new chart activity from a loved one's hospital. Multiple Duke sync rows
// per day is normal (every app open) — the cost is small, and the win is
// that the masthead "Updated …" chip never lies for more than a quarter hour
// after a re-open. autoRefreshEhrIfNeeded() consults this on person load.
function isEhrCacheStale(personId) {
  var cached = ehrCache[personId];
  if (!cached || !cached.synced_at) return true;
  var age = Date.now() - new Date(cached.synced_at).getTime();
  return age > 15 * 60 * 1000;
}

// Adapt a row from public.medications (DB shape) into the shape the EHR
// medications render path expects (ehrData.medications[]). DB is the source
// of truth — the v2 localStorage cache is only an instant-paint optimization.
// When the v2 cache is stale, empty, or scoped to a superseded connection,
// liveMeds (already filtered to active connections by loadPersonData) becomes
// the fallback so Records can never show "0" when DB has rows.
function _ehrMedsFromLiveMeds(meds) {
  if (!Array.isArray(meds)) return [];
  return meds
    .filter(function(m){ return m && m.source === 'ehr' && m.active !== false; })
    .map(function(m) {
      return {
        id: m.id || '',
        name: m.name || '',
        // ehr cache rows use `dosage`; live rows use `dose`. Render path reads either.
        dosage: m.dose || '',
        dose: m.dose || '',
        frequency: m.frequency || '',
        prescriber: m.prescriber || '',
        start_date: m.start_date || '',
        end_date: m.end_date || '',
        status: m.active === false ? 'stopped' : 'active',
        source: 'ehr',
        _connection_id: m.connection_id || null,
      };
    });
}

// Legacy v1 reader — same body as before, kept so the flag can dispatch.
function _legacyGetEhrData(personId) {
  if (isDemoMode) {
    var pills = document.querySelectorAll('#view-records .person-pill, .person-pill.active');
    var isDad = !personId || personId === 'dad';
    if (isDad) return DEMO_EHR_DATA;
    return null;
  }
  return ehrCache[personId] || loadEhrCache(personId);
}

// Get EHR data for current person (demo or real). When the Phase 2 flag is
// set, route through getMergedEhr() so all existing callers transparently
// see merged-across-connections data; fall back to v1 if v2 cache is empty
// (e.g., user just flipped the flag and hasn't synced yet).
function getEhrData(personId) {
  if (isPhase2Enabled() && !isDemoMode) {
    var merged = getMergedEhr(personId);
    if (merged) return merged;
  }
  return _legacyGetEhrData(personId);
}

// ── Hospital picker state ──
var _epicEndpoints = null;
var _epicEndpointsCachedAt = 0;
var _hospitalPickerDebounce = null;

// Allow-list of FHIR base URLs for orgs where Wellet's confidential client is
// activated. Picker only shows these so users don't hit Epic's OAuth2 Error
// at unactivated orgs. URLs are normalized (lowercased, trailing slash stripped)
// before comparison since Epic's endpoint list is inconsistent.
// URLs below are taken verbatim from Epic's published R4 bundle
// (https://open.epic.com/Endpoints/R4). _normFhirUrl() strips trailing
// slashes and lowercases before comparison so minor formatting drift in
// either source can't break the gate.
var ACTIVATED_FHIR_URLS = [
  // NC Tier 1 (Mom's likely care network)
  'https://epsoap.conehealth.com/FHIRProxy/api/FHIR/R4/',                            // Cone Health
  'https://health-apis.duke.edu/FHIR/api/FHIR/R4/',                                  // Duke Health
  'https://epicrp.firsthealth.org/FHIR-PRD/api/FHIR/R4/',                            // FirstHealth of the Carolinas
  'https://epicproxy.et0798.epichosted.com/APIProxyPRD/api/FHIR/R4/',                // Novant
  'https://epicfe.unch.unc.edu/FHIR/api/FHIR/R4/',                                   // UNC Health Care
  'https://epic-soap.wakemed.org/FHIR/api/FHIR/R4/',                                 // WakeMed
  'https://epicproxy.et0905.epichosted.com/FHIRProxy/api/FHIR/R4/',                  // Atrium Health
  'https://spp.caromonthealth.org/FhirProxy/api/FHIR/R4/',                           // CaroMont Health
  'https://prd-proxy.vidanthealth.com/FHIR/api/FHIR/R4/',                            // ECU Health (Vidant)
  // CarolinaEast: not in Epic's R4 bundle as of 2026-04-27. Captured via
  // "Add my health system" form until Epic publishes their R4 endpoint.
  // National anchors
  'https://api.ccf.org/mu/api/FHIR/R4/',                                             // Cleveland Clinic
  'https://ws-interconnect-fhir.partners.org/Interconnect-FHIR-MU-PRD/api/FHIR/R4/', // Mass General Brigham
  // Mayo Clinic: not in Epic's R4 bundle as of 2026-04-27. Captured via form.
  'https://unified-api.ucsf.edu/clinical/apex/api/FHIR/R4/',                         // UCSF Health
  'https://fhir.kp.org/service/ptnt_care/EpicEdiFhirRoutingSvc/v2014/esb-envlbl/212/api/FHIR/R4/', // Kaiser Permanente - Southern California
  // NY metro Tier 1 (added 2026-05-20 in response to tester signal — Kelly Washburn).
  // All 6 endpoints verified via .well-known/smart-configuration: 200 OK, S256 PKCE,
  // Confidential client supported. wellet_confidential (fhir_base_pattern '%') handles
  // OAuth for all of them. No appointment scope — visits/meds/labs/conditions/allergies
  // /care-team/immunizations/observations/diagnostic-reports only.
  'https://epicproxy-pub.et1089.epichosted.com/FHIRProxy/api/FHIR/R4/',              // NewYork-Presbyterian + Weill Cornell Medicine (shared endpoint)
  'https://epicfhir.nyumc.org/FHIRPRD/api/FHIR/R4/',                                 // NYU Langone Health
  'https://epicsoapproxyprd.mountsinai.org/FHIR-PRD/api/FHIR/R4/',                   // Mount Sinai (NYC) — also covers Health Center / Hudson Yards / Concierge Care
  'https://soapepic.montefiore.org/FhirProxyPrd/api/FHIR/R4/',                       // Montefiore Health System
  'https://epicproxy.et1353.epichosted.com/APIPROXYPRD/api/FHIR/R4/',                // Memorial Sloan Kettering Cancer Center
  'https://epicproxy.et0927.epichosted.com/FHIRProxy/api/FHIR/R4/'                   // Hospital for Special Surgery
];

function _normFhirUrl(u) {
  if (!u) return '';
  return String(u).toLowerCase().replace(/\/+$/, '');
}

var _ACTIVATED_FHIR_SET = (function() {
  var s = {};
  for (var i = 0; i < ACTIVATED_FHIR_URLS.length; i++) {
    s[_normFhirUrl(ACTIVATED_FHIR_URLS[i])] = true;
  }
  return s;
})();

function isActivatedHospital(fhirBaseUrl) {
  return !!_ACTIVATED_FHIR_SET[_normFhirUrl(fhirBaseUrl)];
}

// Load Epic endpoint list from open.epic.com (cached 24h in localStorage).
// Empty arrays are NEVER cached or served from cache — a zero-length result
// is always treated as a miss so a transient init-time race can't poison the
// session for 24 hours.
function loadEpicEndpoints(cb) {
  // Bump v whenever the loader logic, ACTIVATED_FHIR_URLS, or the cache
  // shape changes so existing users with stale data refresh.
  var CACHE_KEY = 'wellet_epic_endpoints_v6';
  var CACHE_TS_KEY = 'wellet_epic_endpoints_v6_ts';
  var CACHE_TTL = 24 * 60 * 60 * 1000;

  // Also wipe legacy cache keys on first run so users on v2/v3/v4 don't keep
  // dragging around an old (possibly-empty or DSTU2) array under a stale key.
  try {
    localStorage.removeItem('wellet_epic_endpoints_v2');
    localStorage.removeItem('wellet_epic_endpoints_v2_ts');
    localStorage.removeItem('wellet_epic_endpoints_v3');
    localStorage.removeItem('wellet_epic_endpoints_v3_ts');
    localStorage.removeItem('wellet_epic_endpoints_v4');
    localStorage.removeItem('wellet_epic_endpoints_v4_ts');
    localStorage.removeItem('wellet_epic_endpoints_v5');
    localStorage.removeItem('wellet_epic_endpoints_v5_ts');
  } catch(e) {}

  // Check in-memory cache first — but only if it's non-empty. An empty array
  // is treated as a miss so a transient init-time race (e.g. callback fired
  // before isActivatedHospital was defined) can recover on the next call
  // instead of poisoning the session.
  if (_epicEndpoints && _epicEndpoints.length > 0 && (Date.now() - _epicEndpointsCachedAt < CACHE_TTL)) {
    cb(_epicEndpoints);
    return;
  }

  // Check localStorage cache — same rule: non-empty only.
  try {
    var ts = parseInt(localStorage.getItem(CACHE_TS_KEY) || '0', 10);
    if (Date.now() - ts < CACHE_TTL) {
      var cached = localStorage.getItem(CACHE_KEY);
      if (cached) {
        var parsed = JSON.parse(cached);
        if (Array.isArray(parsed) && parsed.length > 0) {
          _epicEndpoints = parsed;
          _epicEndpointsCachedAt = ts;
          cb(_epicEndpoints);
          return;
        }
      }
    }
  } catch(e) {}

  // Fetch from Epic. The cache-buster query param + no-store on the response
  // belt-and-suspenders defeat any HTTP cache (browser disk, intermediary CDN)
  // that might still be holding the old DSTU2 response from a prior version
  // of this edge function. Seen in prod 2026-04-27: a user's tab kept
  // receiving DSTU2 URLs from disk cache for 24h after we shipped R4.
  var bust = 'v5_' + Date.now();
  fetch('https://nrpdhxygzyfmyljzfexv.supabase.co/functions/v1/epic-endpoints?cb=' + bust, { cache: 'no-store' })
    .then(function(res) { return res.json(); })
    .then(function(data) {
      var endpoints = (data.Entries || data).map(function(e) {
        return {
          name: e.OrganizationName || e.Name || '',
          fhirBaseUrl: e.FHIRPatientFacingURI || e.BaseURL || e.FHIRBaseUrl || '',
          city: e.City || '',
          state: e.State || ''
        };
      }).filter(function(e) {
        // Drop entries missing required fields, then gate by activation allow-list
        // so users only see hospitals where our confidential client is enabled.
        return e.name && e.fhirBaseUrl && isActivatedHospital(e.fhirBaseUrl);
      });

      _epicEndpoints = endpoints;
      _epicEndpointsCachedAt = Date.now();

      // Only persist non-empty results so an upstream blip doesn't poison
      // the cache for 24h. The next call after a transient empty result
      // will retry the fetch.
      if (endpoints.length > 0) {
        try {
          localStorage.setItem(CACHE_KEY, JSON.stringify(endpoints));
          localStorage.setItem(CACHE_TS_KEY, String(Date.now()));
        } catch(e) {}
      }

      cb(endpoints);
    }).catch(function(err) {
      console.error('Failed to load Epic endpoints:', err);
      cb([]);
    });
}

// 2026-05-21: Hospital pre-check helpers — calls ehr-vendor-check edge fn when
// the user types a query that doesn't match any Epic endpoint in our bundle, and
// renders a 4-bucket result card inline. Identified-via-Perplexity attribution
// surfaces only when the source is Sonar.
var _vendorCheckCache = {};      // key=normalized query -> {result, ts}
var _vendorCheckInflight = {};   // key=normalized query -> Promise
var _vendorCheckDebounce = null;

function _normVendorQuery(q) {
  return String(q || '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function precheckHospitalVendor(query, city, state, fhirBaseUrl) {
  var key = _normVendorQuery(query) + '|' + _normVendorQuery(city || '') + '|' + _normVendorQuery(state || '') + '|' + _normVendorQuery(fhirBaseUrl || '');
  if (_vendorCheckCache[key] && (Date.now() - _vendorCheckCache[key].ts) < 5 * 60 * 1000) {
    return Promise.resolve(_vendorCheckCache[key].result);
  }
  if (_vendorCheckInflight[key]) return _vendorCheckInflight[key];

  var p = db.auth.getSession().then(function(s) {
    var headers = {
      'Content-Type': 'application/json',
      'apikey': SUPABASE_ANON_KEY
    };
    var session = s && s.data && s.data.session;
    if (session && session.access_token) {
      headers['Authorization'] = 'Bearer ' + session.access_token;
    }
    return fetch(SUPABASE_URL + '/functions/v1/ehr-vendor-check', {
      method: 'POST',
      headers: headers,
      body: JSON.stringify({
        hospital_name: query || null,
        city: city || null,
        state: state || null,
        fhir_base_url: fhirBaseUrl || null
      })
    });
  }).then(function(res) {
    if (!res.ok) throw new Error('vendor-check http ' + res.status);
    return res.json();
  }).then(function(result) {
    _vendorCheckCache[key] = { result: result, ts: Date.now() };
    delete _vendorCheckInflight[key];
    return result;
  }).catch(function(err) {
    console.warn('[ehr-vendor-check] failed', err);
    delete _vendorCheckInflight[key];
    return null;
  });
  _vendorCheckInflight[key] = p;
  return p;
}

// Render a 4-bucket result card. Returns HTML string.
function _vendorCheckCardHtml(result, query) {
  if (!result || !result.vendor_guess) return '';
  var v = result.vendor_guess;
  var conf = result.vendor_confidence || 'low';
  var src = result.vendor_source || '';
  var viaPplx = !!result.via_perplexity;
  var matched = result.matched_hospital || query || 'this hospital';

  var title = '';
  var body = '';
  var ctaHtml = '';
  var tone = 'info'; // info | good | warn | block

  if (v === 'epic_activated') {
    tone = 'good';
    title = 'Good news — ' + escHtml(matched) + ' is wired up.';
    body = 'Pick it from the list above to connect now.';
  } else if (v === 'epic_not_activated') {
    tone = 'warn';
    title = escHtml(matched) + ' is on Epic, but not activated yet.';
    body = 'We\u2019ll need to turn it on for your hospital. Send us a request and we\u2019ll prioritize it.';
    ctaHtml = '<button type="button" class="vendor-check-cta" onclick="openConnectRequestModal({hospital_name:' + JSON.stringify(matched) + ',issue_type:\'unsupported_version\',source:\'precheck_picker\',vendor_guess:\'epic_not_activated\',vendor_confidence:' + JSON.stringify(conf) + ',vendor_source:' + JSON.stringify(src) + ',vendor_lookup_payload:' + JSON.stringify(JSON.stringify(result)) + '})">Request access</button>';
  } else if (v === 'kaiser_blocked' || v === 'va_blocked') {
    tone = 'block';
    title = escHtml(matched) + ' doesn\u2019t share records this way yet.';
    body = (v === 'kaiser_blocked'
      ? 'Kaiser Permanente keeps records inside their own portal and hasn\u2019t opened FHIR access to outside apps. You can still upload PDFs from kp.org for now.'
      : 'VA records aren\u2019t available through this connection yet. You can still upload VA Blue Button PDFs.');
  } else if (v === 'cerner' || v === 'meditech' || v === 'athena' || v === 'nextgen' || v === 'allscripts' || v === 'eclinicalworks') {
    tone = 'warn';
    var vendorLabel = ({cerner:'Oracle Cerner', meditech:'Meditech', athena:'athenahealth', nextgen:'NextGen', allscripts:'Veradigm/Allscripts', eclinicalworks:'eClinicalWorks'})[v] || v;
    title = escHtml(matched) + ' uses ' + vendorLabel + ', not Epic.';
    body = 'We\u2019re adding non-Epic vendors next. Send us a request and we\u2019ll let you know as soon as it\u2019s ready.';
    ctaHtml = '<button type="button" class="vendor-check-cta" onclick="openConnectRequestModal({hospital_name:' + JSON.stringify(matched) + ',issue_type:\'unsupported_version\',source:\'precheck_picker\',vendor_guess:' + JSON.stringify(v) + ',vendor_confidence:' + JSON.stringify(conf) + ',vendor_source:' + JSON.stringify(src) + ',vendor_lookup_payload:' + JSON.stringify(JSON.stringify(result)) + '})">Tell us your hospital</button>';
  } else if (v === 'other' || v === 'unknown') {
    tone = 'info';
    title = 'We couldn\u2019t place ' + escHtml(matched) + ' yet.';
    body = 'Send us a few details and we\u2019ll find the right path for you.';
    ctaHtml = '<button type="button" class="vendor-check-cta" onclick="openConnectRequestModal({hospital_name:' + JSON.stringify(query || matched) + ',issue_type:\'not_found\',source:\'precheck_picker\',vendor_guess:' + JSON.stringify(v) + ',vendor_confidence:' + JSON.stringify(conf) + ',vendor_source:' + JSON.stringify(src) + ',vendor_lookup_payload:' + JSON.stringify(JSON.stringify(result)) + '})">Tell us your hospital</button>';
  } else {
    return '';
  }

  var attribution = (src === 'sonar' || viaPplx)
    ? '<div class="vendor-check-attribution"><em>Identified via Perplexity</em></div>'
    : '';

  return '<div class="vendor-check-card vendor-check-card--' + tone + '">'
    + '<div class="vendor-check-title">' + title + '</div>'
    + '<div class="vendor-check-body">' + body + '</div>'
    + (ctaHtml ? '<div class="vendor-check-actions">' + ctaHtml + '</div>' : '')
    + attribution
    + '</div>';
}

function renderHospitalList(filtered) {
  var list = document.getElementById('hospital-picker-list');
  if (!list) return;
  if (!filtered || filtered.length === 0) {
    var inputEl = document.getElementById('hospital-picker-input');
    var query = inputEl ? inputEl.value.trim() : '';
    var baseEmpty = '<li class="hospital-picker-empty">No hospitals found. Try a different search term.</li>';
    // If query too short, just show the empty message.
    if (!query || query.length < 3) {
      list.innerHTML = baseEmpty;
      return;
    }
    // Render placeholder while we check.
    list.innerHTML = baseEmpty
      + '<li class="vendor-check-slot"><div class="vendor-check-card vendor-check-card--loading"><div class="vendor-check-body">Checking what kind of system ' + escHtml(query) + ' uses\u2026</div></div></li>';
    precheckHospitalVendor(query).then(function(result) {
      // Make sure the query is still current
      var cur = document.getElementById('hospital-picker-input');
      var stillSame = cur && cur.value.trim() === query;
      if (!stillSame) return;
      var slot = list.querySelector('.vendor-check-slot');
      if (!slot) return;
      var cardHtml = _vendorCheckCardHtml(result, query);
      slot.innerHTML = cardHtml || '';
    });
    return;
  }
  var shown = filtered.slice(0, 50);
  var html = '';
  for (var i = 0; i < shown.length; i++) {
    var h = shown[i];
    var loc = [h.city, h.state].filter(Boolean).join(', ');
    // 2026-05-21: stash the hospital's identity directly on the <li> via data-*
    // attrs instead of a numeric index into list._filtered. The old idx scheme
    // was vulnerable to a race where a second renderHospitalList() (from a
    // debounced input event, a delayed loadEpicEndpoints callback, or the
    // vendor-check-slot async path) could mutate _filtered between the
    // onclick's render time and the tap dispatch, surfacing the WRONG hospital
    // (e.g. tapping Cleveland Clinic and triggering Kaiser Permanente). With
    // data attrs the tap resolves against the element that was actually
    // tapped, immune to any subsequent list mutation.
    html += '<li class="hospital-picker-item"'
      + ' data-fhir-base-url="' + escHtml(h.fhirBaseUrl) + '"'
      + ' data-hospital-name="' + escHtml(h.name) + '"'
      + ' onclick="selectHospitalFromEl(this)">'
      + '<div class="hospital-picker-name">' + escHtml(h.name) + '</div>'
      + (loc ? '<div class="hospital-picker-loc">' + escHtml(loc) + '</div>' : '')
      + '</li>';
  }
  list.innerHTML = html;
  // Kept for backwards compatibility with any in-flight onclick handlers from
  // a previous render. New taps go through selectHospitalFromEl(this).
  list._filtered = shown;
}

// Resolve the tapped hospital from the <li> that was actually clicked, not
// from an index into a shared mutable array. This is the picker's primary
// selection path as of 2026-05-21.
function selectHospitalFromEl(el) {
  if (!el) return;
  var fhirBaseUrl = el.getAttribute('data-fhir-base-url') || '';
  var name = el.getAttribute('data-hospital-name') || '';
  if (!fhirBaseUrl || !name) return;
  closeSheet('hospital-picker-overlay');
  if (_obFromEhr && !currentPersonId) {
    _obEhrPending = { fhirBaseUrl: fhirBaseUrl, name: name };
    try { localStorage.setItem('wellet_ob_ehr_hospital', JSON.stringify(_obEhrPending)); } catch(e) {}
    obShowNameScreen(null);
    return;
  }
  beginEhrOAuth(fhirBaseUrl, name, false);
}

// Legacy entry point. Older renders (or anything cached) may still call this
// by numeric index; route through the new resolver when possible, otherwise
// fall back to the original idx-into-_filtered path.
function selectHospital(idx) {
  var list = document.getElementById('hospital-picker-list');
  if (!list) return;
  var items = list.querySelectorAll('.hospital-picker-item');
  if (items && items[idx] && items[idx].getAttribute('data-fhir-base-url')) {
    selectHospitalFromEl(items[idx]);
    return;
  }
  if (!list._filtered || !list._filtered[idx]) return;
  var h = list._filtered[idx];
  closeSheet('hospital-picker-overlay');
  if (_obFromEhr && !currentPersonId) {
    _obEhrPending = { fhirBaseUrl: h.fhirBaseUrl, name: h.name };
    try { localStorage.setItem('wellet_ob_ehr_hospital', JSON.stringify(_obEhrPending)); } catch(e) {}
    obShowNameScreen(null);
    return;
  }
  beginEhrOAuth(h.fhirBaseUrl, h.name, false);
}

function filterHospitals(query) {
  if (!_epicEndpoints) return [];
  if (!query) return _epicEndpoints.slice(0, 50);
  var q = query.toLowerCase();
  return _epicEndpoints.filter(function(e) {
    return e.name.toLowerCase().indexOf(q) !== -1
      || (e.city && e.city.toLowerCase().indexOf(q) !== -1)
      || (e.state && e.state.toLowerCase().indexOf(q) !== -1);
  });
}

// Open the hospital picker overlay
function startEhrConnect() {
  if (isDemoMode) {
    showToast('In the real app, this connects to your provider\u2019s records');
    return;
  }
  if (!currentUser) {
    showToast('Please sign in first');
    return;
  }
  if (!currentPersonId) {
    showToast('Please select a person first');
    return;
  }

  // 2026-05-21: user tapped Connect Health Records — reset any prior
  // in-flight attempt before opening the picker. Two effects:
  //   - in-memory _ehrConnecting lock released so the next pick isn't dropped
  //   - any 'pending' ehr_connections row for this person flipped to
  //     'abandoned' so UI/ops queries don't see ghost connections.
  try { _resetEhrConnectingStateForFreshAttempt(); } catch(e) {}

  openSheetAccessible('hospital-picker-overlay');
  initIcons();

  var input = document.getElementById('hospital-picker-input');
  if (input) {
    input.value = '';
    input.removeEventListener('input', _hospitalPickerInputHandler);
    input.addEventListener('input', _hospitalPickerInputHandler);
  }

  // Load endpoints and render initial list
  var list = document.getElementById('hospital-picker-list');
  if (list) list.innerHTML = '<li class="hospital-picker-loading">Loading hospitals\u2026</li>';

  loadEpicEndpoints(function(endpoints) {
    renderHospitalList(endpoints.slice(0, 50));
  });
}

function _hospitalPickerInputHandler() {
  clearTimeout(_hospitalPickerDebounce);
  _hospitalPickerDebounce = setTimeout(function() {
    var input = document.getElementById('hospital-picker-input');
    var query = input ? input.value.trim() : '';
    var filtered = filterHospitals(query);
    // Bumped to 600ms only when the filter is empty (i.e. pre-check will fire);
    // otherwise keep the snappy 200ms feel from filterHospitals.
    renderHospitalList(filtered);
  }, 200);
}

// ── CONNECT-REQUEST FLOW ────────────────────────────────────────────────────
var _crContext = {};

function openConnectRequestModal(opts) {
  opts = opts || {};
  _crContext = opts;

  // Reset to form view
  var formView = document.getElementById('cr-form-view');
  var successView = document.getElementById('cr-success-view');
  if (formView) formView.style.display = '';
  if (successView) successView.style.display = 'none';

  // Pre-fill form fields
  var hospitalEl = document.getElementById('cr-hospital');
  var cityEl = document.getElementById('cr-city');
  var stateEl = document.getElementById('cr-state');
  var issueEl = document.getElementById('cr-issue');
  var notesEl = document.getElementById('cr-notes');
  var emailEl = document.getElementById('cr-email');
  var subEl = document.getElementById('cr-sub');

  if (hospitalEl) hospitalEl.value = opts.hospital_name || '';
  if (cityEl) cityEl.value = opts.city || '';
  if (stateEl) stateEl.value = opts.state || '';
  if (issueEl) issueEl.value = opts.issue_type || 'not_found';
  if (notesEl) notesEl.value = opts.notes || '';

  // 2026-05-21: if caller pre-filled vendor info (e.g. from picker pre-check), show it.
  // Also wire blur-pre-check on the hospital field.
  _crPrefillVendor(opts);
  if (hospitalEl) {
    hospitalEl.removeEventListener('blur', _crHospitalBlurHandler);
    hospitalEl.addEventListener('blur', _crHospitalBlurHandler);
  }
  if (emailEl) {
    var defaultEmail = '';
    try { if (currentUser && currentUser.email) defaultEmail = currentUser.email; } catch(e) {}
    emailEl.value = opts.contact_email || defaultEmail;
  }

  // Contextual subheading
  if (subEl) {
    if (opts.issue_type === 'unsupported_version') {
      subEl.textContent = 'It looks like your hospital isn’t on a supported version yet. Share a few details and we’ll let you know as soon as support is ready.';
    } else if (opts.issue_type === 'oauth_error') {
      subEl.textContent = 'Sorry about that — we hit a snag connecting. Send us the details and we’ll take a look.';
    } else {
      subEl.textContent = 'We’re adding hospitals every week. Share a few details and we’ll follow up when yours is ready.';
    }
  }

  // Reset submit button state
  var btn = document.getElementById('cr-submit-btn');
  if (btn) {
    btn.disabled = false;
    btn.textContent = 'Send';
  }

  var overlay = document.getElementById('cr-overlay');
  if (overlay) {
    overlay.classList.add('show');
  }
  initIcons();
}

function closeConnectRequestModal() {
  var overlay = document.getElementById('cr-overlay');
  if (overlay) overlay.classList.remove('show');
  _crContext = {};
  var slot = document.getElementById('cr-vendor-check-slot');
  if (slot) slot.innerHTML = '';
}

// 2026-05-21: Pre-fill vendor banner inside the connect-request modal when the
// picker pre-check already produced a result, or when the user pastes a hospital
// name into the form and blurs the field.
function _crPrefillVendor(opts) {
  var slot = document.getElementById('cr-vendor-check-slot');
  if (!slot) return;
  if (opts && opts.vendor_guess) {
    var synthetic = {
      vendor_guess: opts.vendor_guess,
      vendor_confidence: opts.vendor_confidence,
      vendor_source: opts.vendor_source,
      matched_hospital: opts.hospital_name,
      via_perplexity: !!(opts.vendor_lookup_payload && (function() {
        try { var p = (typeof opts.vendor_lookup_payload === 'string') ? JSON.parse(opts.vendor_lookup_payload) : opts.vendor_lookup_payload; return p && p.via_perplexity; } catch(e) { return false; }
      })())
    };
    slot.innerHTML = _vendorCheckCardHtml(synthetic, opts.hospital_name || '');
  } else {
    slot.innerHTML = '';
  }
}

var _crHospitalBlurDebounce = null;
function _crHospitalBlurHandler() {
  var hospitalEl = document.getElementById('cr-hospital');
  var cityEl = document.getElementById('cr-city');
  var stateEl = document.getElementById('cr-state');
  var slot = document.getElementById('cr-vendor-check-slot');
  if (!hospitalEl || !slot) return;
  var query = hospitalEl.value.trim();
  if (query.length < 3) { slot.innerHTML = ''; return; }
  // If picker already pre-filled and the hospital name hasn't changed, keep it.
  if (_crContext && _crContext.vendor_guess && _crContext.hospital_name === query) return;
  slot.innerHTML = '<div class="vendor-check-card vendor-check-card--loading"><div class="vendor-check-body">Checking what kind of system this hospital uses\u2026</div></div>';
  clearTimeout(_crHospitalBlurDebounce);
  _crHospitalBlurDebounce = setTimeout(function() {
    var city = cityEl ? cityEl.value.trim() : '';
    var state = stateEl ? stateEl.value.trim() : '';
    precheckHospitalVendor(query, city, state).then(function(result) {
      var cur = document.getElementById('cr-hospital');
      if (!cur || cur.value.trim() !== query) return;
      // Store vendor result in _crContext so submit picks it up.
      if (result) {
        _crContext.vendor_guess = result.vendor_guess || null;
        _crContext.vendor_confidence = result.vendor_confidence || null;
        _crContext.vendor_source = result.vendor_source || null;
        _crContext.vendor_blocked = (result.vendor_blocked === true) ? true : null;
        _crContext.vendor_lookup_payload = result;
      }
      slot.innerHTML = result ? _vendorCheckCardHtml(result, query) : '';
    });
  }, 300);
}

function submitConnectRequest() {
  var btn = document.getElementById('cr-submit-btn');
  var hospitalEl = document.getElementById('cr-hospital');
  var cityEl = document.getElementById('cr-city');
  var stateEl = document.getElementById('cr-state');
  var issueEl = document.getElementById('cr-issue');
  var notesEl = document.getElementById('cr-notes');
  var emailEl = document.getElementById('cr-email');

  var hospitalName = hospitalEl ? hospitalEl.value.trim() : '';
  var city = cityEl ? cityEl.value.trim() : '';
  var state = stateEl ? stateEl.value.trim() : '';
  var issueType = issueEl ? issueEl.value : 'other';
  var notes = notesEl ? notesEl.value.trim() : '';
  var contactEmail = emailEl ? emailEl.value.trim() : '';

  if (!hospitalName) {
    showToast('Please enter your hospital or health system');
    if (hospitalEl) hospitalEl.focus();
    return;
  }

  if (!contactEmail) {
    showToast('Please add your email so we can tell you when it’s ready');
    if (emailEl) emailEl.focus();
    return;
  }

  // Basic email shape check — server will do the authoritative validation
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(contactEmail)) {
    showToast('That email doesn’t look quite right — please double-check');
    if (emailEl) emailEl.focus();
    return;
  }

  var payload = {
    hospital_name: hospitalName,
    city: city || null,
    state: state || null,
    issue_type: issueType,
    notes: notes || null,
    contact_email: contactEmail,
    fhir_base_url: _crContext.fhir_base_url || null,
    error_code: _crContext.error_code || null,
    error_message: _crContext.error_message || null,
    person_id: _crContext.person_id || (typeof currentPersonId !== 'undefined' ? currentPersonId : null),
    source: _crContext.source || null,
    // 2026-05-21: surface the pre-check result so triage can prioritize.
    vendor_guess: _crContext.vendor_guess || null,
    vendor_confidence: _crContext.vendor_confidence || null,
    vendor_source: _crContext.vendor_source || null,
    vendor_blocked: _crContext.vendor_blocked || null,
    vendor_lookup_payload: _crContext.vendor_lookup_payload || null
  };

  if (btn) {
    btn.disabled = true;
    btn.textContent = 'Sending…';
  }

  db.auth.getSession().then(function(s) {
    var headers = {
      'Content-Type': 'application/json',
      'apikey': SUPABASE_ANON_KEY
    };
    var session = s && s.data && s.data.session;
    if (session && session.access_token) {
      headers['Authorization'] = 'Bearer ' + session.access_token;
    }
    return fetch(SUPABASE_URL + '/functions/v1/submit-connect-request', {
      method: 'POST',
      headers: headers,
      body: JSON.stringify(payload)
    });
  }).then(function(res) {
    return res.json().then(function(data) {
      return { status: res.status, data: data };
    }).catch(function() {
      return { status: res.status, data: null };
    });
  }).then(function(result) {
    if (result.status >= 200 && result.status < 300) {
      var formView = document.getElementById('cr-form-view');
      var successView = document.getElementById('cr-success-view');
      if (formView) formView.style.display = 'none';
      if (successView) successView.style.display = '';
      initIcons();
    } else {
      var errMsg = (result.data && result.data.error) ? result.data.error : 'Could not send right now. Please try again.';
      showToast(errMsg);
      if (btn) {
        btn.disabled = false;
        btn.textContent = 'Send';
      }
    }
  }).catch(function(err) {
    console.error('[connect-request] submit error', err);
    showToast('Could not send right now. Please try again.');
    if (btn) {
      btn.disabled = false;
      btn.textContent = 'Send';
    }
  });
}

// Begin the actual OAuth redirect for a selected hospital (or sandbox)
function beginEhrOAuth(fhirBaseUrl, hospitalName, isSandbox) {
  // 2026-05-21: if the picker is visible the user is clearly initiating a
  // new attempt — any prior _ehrConnecting=true is stale (e.g. previous
  // attempt where they hit back from MyChart without completing OAuth).
  // Reset before the guard so the tap isn't silently dropped.
  var pickerEl = document.getElementById('hospital-picker-overlay');
  var pickerOpen = !!(pickerEl && pickerEl.classList.contains('open'));
  if (pickerOpen && _ehrConnecting) {
    console.warn('[ehr] picker open with stale _ehrConnecting=true \u2014 resetting');
    try { _resetEhrConnectingStateForFreshAttempt(); } catch(e) {}
  }
  if (_ehrConnecting) return;
  var personId = currentPersonId;
  if (!personId && _obFromEhr) {
    // Onboarding: no person yet — store choice; chat flow will create person first
    closeSheet('hospital-picker-overlay');
    _obEhrPending = { fhirBaseUrl: fhirBaseUrl, name: hospitalName || (isSandbox ? 'Epic Sandbox' : null), sandbox: !!isSandbox };
    try { localStorage.setItem('wellet_ob_ehr_hospital', JSON.stringify(_obEhrPending)); } catch(e) {}
    // In chat-first flow, inform user we need to finish names first
    if (obChat && obChat.phase === 'connect') {
      obAddBubble('wellet', 'I\u2019ll connect to the portal once we\u2019re set up. Let me finish getting things ready.');
    }
    return;
  }
  if (!personId) {
    showToast('Please select a person first');
    return;
  }

  _ehrConnecting = true;
  _ehrPendingPersonId = personId;

  // 2026-05-21: watchdog. If we never redirect to Epic and never hit a
  // success/error branch within 90s (e.g. the user closed the OAuth tab
  // mid-flight and came back without a back-navigation event), auto-clear
  // the lock so the next hospital pick isn't silently swallowed.
  if (_ehrConnectingTimeoutId) clearTimeout(_ehrConnectingTimeoutId);
  _ehrConnectingTimeoutId = setTimeout(function() {
    if (_ehrConnecting) {
      console.warn('[ehr] connecting lock watchdog fired \u2014 clearing stuck lock');
      _clearEhrConnectingLock();
      try { showToast('Connection attempt timed out \u2014 try again'); } catch(e) {}
    }
  }, 90000);

  try { localStorage.setItem('wellet_ehr_pending_person', personId); } catch(e) {}

  var label = isSandbox ? 'Epic Sandbox' : (hospitalName || 'your hospital');
  showToast('Connecting to ' + label + '\u2026');

  // Force a token refresh to avoid stale JWT race condition
  db.auth.refreshSession().then(function(refreshRes) {
    var session = refreshRes.data.session;
    if (!session) {
      // Fallback to getSession if refresh fails
      return db.auth.getSession().then(function(s) { return s.data.session; });
    }
    return session;
  }).then(function(session) {
    if (!session) {
      showToast('Session expired. Please sign in again.');
      _clearEhrConnectingLock();
      return;
    }
    var payload = { action: 'start', person_id: personId };
    if (isSandbox) {
      payload.sandbox = true;
    } else if (fhirBaseUrl) {
      payload.fhirBaseUrl = fhirBaseUrl;
      if (hospitalName) payload.hospitalName = hospitalName;
    }
    var tok = session.access_token || '';
    try { console.log('[ehr] sending token fingerprint', tok.slice(0,8) + '...' + tok.slice(-4), 'len=' + tok.length, 'user=' + (session.user && session.user.id)); } catch(e) {}
    return fetch(SUPABASE_URL + '/functions/v1/epic-auth', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + tok,
        'Content-Type': 'application/json',
        'apikey': SUPABASE_ANON_KEY
      },
      body: JSON.stringify(payload)
    });
  }).then(function(res) {
    if (!res) return;
    try { console.log('[ehr] epic-auth response status', res.status); } catch(e) {}
    return res.json();
  }).then(function(data) {
    _clearEhrConnectingLock();
    if (!data) return;
    try { console.log('[ehr] epic-auth body', data); } catch(e) {}
    if (data.error) {
      if (data.error === 'unsupported_fhir_version') {
        showToast('This hospital isn’t supported yet — let us know and we’ll get to work on it.');
        setTimeout(function() {
          openConnectRequestModal({
            source: 'unsupported_version',
            issue_type: 'unsupported_version',
            hospital_name: hospitalName || '',
            fhir_base_url: fhirBaseUrl || null,
            error_code: data.error,
            error_message: data.message || data.diag || null,
            person_id: personId
          });
        }, 400);
        return;
      }
      // 2026-05-01: removed dead handler for `multi_hospital_not_yet_supported`.
      // The 2026-04-26 server-side gate was lifted on 2026-04-27 once the
      // N-connections refactor landed; the server no longer returns this
      // error code. A loved one can now connect any number of hospitals
      // (Duke, UNC, WakeMed, etc.) and the v2 merged cache surfaces them all.
      var msg = 'Error: ' + data.error;
      if (data.diag) msg += ' (' + data.diag + ')';
      showToast(msg);
      // Offer the "Let us know" path for any other start-phase error
      setTimeout(function() {
        openConnectRequestModal({
          source: 'start_error',
          issue_type: 'oauth_error',
          hospital_name: hospitalName || '',
          fhir_base_url: fhirBaseUrl || null,
          error_code: data.error,
          error_message: data.message || data.diag || null,
          person_id: personId
        });
      }, 400);
      return;
    }
    if (data.authorize_url) {
      // Validate redirect URL — must be HTTPS (production hospitals have diverse hostnames)
      try {
        var authUrl = new URL(data.authorize_url);
        if (authUrl.protocol === 'https:') {
          // 2026-05-21: the 2nd-hospital-bounce-back bug. On the 2nd attempt
          // (after backing out of the 1st hospital's MyChart) Safari was
          // sitting on a history entry pushed by openSheetAccessible. Setting
          // window.location.href in that state silently failed for some users
          // — the page stayed put, the toast faded, and the user landed back
          // on the 3-button Connect screen with no OAuth. Belt-and-suspenders
          // fix:
          //   1. Collapse the sheet history entry first so we redirect from
          //      the underlying tab state, not from a stacked sheet state.
          //   2. Use location.assign() (the canonical "navigate" API).
          //   3. Schedule a verification check 600ms later — if we're still
          //      on the same page, retry the navigation as window.location
          //      .replace(). If THAT also fails, show a tappable fallback so
          //      the user can manually trigger the redirect.
          try {
            if (history.state && history.state.type === 'sheet' && history.state.id === 'hospital-picker-overlay') {
              history.replaceState({ type: 'tab', view: _currentNavView || 'connect' }, '');
            }
          } catch(_e) {}
          var targetUrl = data.authorize_url;
          try { console.log('[ehr] navigating to authorize_url', targetUrl); } catch(_e) {}
          try { window.location.assign(targetUrl); } catch(_e) {
            try { window.location.href = targetUrl; } catch(__e) {}
          }
          // Verification + retry — if the page didn't navigate within 600ms,
          // the assign call was silently dropped (history conflict, bfcache,
          // pending unload race). Try replace() which is more aggressive,
          // then fall back to a tappable toast.
          setTimeout(function() {
            try {
              if (document.visibilityState === 'visible' && location.host !== authUrl.host) {
                console.warn('[ehr] redirect did not fire — retrying with location.replace()');
                try { window.location.replace(targetUrl); } catch(_e) {
                  try { window.location.href = targetUrl; } catch(__e) {}
                }
                setTimeout(function() {
                  if (document.visibilityState === 'visible' && location.host !== authUrl.host) {
                    console.error('[ehr] redirect still failed — surfacing tappable fallback');
                    try { _showEhrContinueFallback(targetUrl, hospitalName); } catch(_e) {
                      try { window.open(targetUrl, '_self'); } catch(__e) {}
                    }
                  }
                }, 600);
              }
            } catch(_e) {}
          }, 600);
        } else {
          showToast('Invalid authorize URL');
        }
      } catch(e) {
        showToast('Invalid authorize URL');
      }
    } else {
      // 2026-05-21: 200 OK but no authorize_url AND no error. Should be
      // unreachable, but never leave the user staring at a faded toast.
      try { console.warn('[ehr] epic-auth returned 200 with no authorize_url and no error', data); } catch(_e) {}
      showToast('Could not start the connection — try again');
    }
  }).catch(function(err) {
    _clearEhrConnectingLock();
    console.error('EHR connect error:', err);
    showToast('Failed to start EHR connection');
  });
}

// 2026-05-21: tappable fallback overlay shown when the automatic redirect to
// the hospital's authorize_url silently fails (e.g. iOS Safari history-stack
// race after a back-out from a prior MyChart attempt). Tapping "Continue"
// performs a user-gesture navigation which always succeeds.
function _showEhrContinueFallback(targetUrl, hospitalName) {
  // Avoid stacking multiple overlays if the user retries.
  var existing = document.getElementById('ehr-continue-fallback');
  if (existing) existing.remove();
  var overlay = document.createElement('div');
  overlay.id = 'ehr-continue-fallback';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(44,42,38,0.55);z-index:400;display:flex;align-items:center;justify-content:center;padding:24px;';
  var card = document.createElement('div');
  card.style.cssText = 'background:white;border-radius:20px;padding:24px;max-width:340px;width:100%;text-align:center;font-family:DM Sans,sans-serif;';
  var label = hospitalName ? ('your ' + hospitalName + ' sign-in') : 'your hospital sign-in';
  card.innerHTML = '<div style="font-family:var(--serif);font-size:var(--type-h2);margin-bottom:8px;">One more tap</div>'
    + '<div style="font-size:var(--type-body);color:var(--text-secondary);line-height:1.5;margin-bottom:18px;">Safari needs a tap to continue to ' + escHtml(label) + '.</div>';
  var btn = document.createElement('button');
  btn.textContent = 'Continue';
  btn.style.cssText = 'background:var(--moss);color:white;border:none;border-radius:12px;padding:12px 28px;font-size:var(--type-body);font-weight:500;font-family:DM Sans,sans-serif;cursor:pointer;width:100%;';
  btn.onclick = function() {
    overlay.remove();
    try { window.location.assign(targetUrl); } catch(_e) {
      try { window.open(targetUrl, '_self'); } catch(__e) {
        try { window.location.href = targetUrl; } catch(___e) {}
      }
    }
  };
  card.appendChild(btn);
  overlay.appendChild(card);
  document.body.appendChild(overlay);
}

// Handle the Epic OAuth callback (called on page load if code is present)
function handleEhrCallback() {
  var params = new URLSearchParams(window.location.search);
  var code = params.get('code');
  if (!code) { console.log('EHR callback: no code param'); return; }
  // Validate OAuth code format (allow base64 and common auth code chars)
  if (!/^[a-zA-Z0-9\-_.+=\/]{1,2048}$/.test(code)) { console.warn('EHR callback: code failed validation', code.substring(0, 40)); return; }
  var state = params.get('state') || '';

  // Get the pending person_id
  var personId;
  try { personId = localStorage.getItem('wellet_ehr_pending_person'); } catch(e) {}
  if (!personId) {
    console.warn('EHR callback: no pending person_id');
    return;
  }

  // Clean up URL — navigate back to root
  try {
    window.history.replaceState({}, '', window.location.origin + '/');
  } catch(e) {}

  // Wait for auth to be ready, then exchange the code
  var checkAuth = setInterval(function() {
    if (!currentUser) return;
    clearInterval(checkAuth);

    showToast('Completing Epic connection\u2026');

    db.auth.getSession().then(function(sessionRes) {
      var session = sessionRes.data.session;
      if (!session) return;
      return fetch(SUPABASE_URL + '/functions/v1/epic-auth', {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + session.access_token,
          'Content-Type': 'application/json',
          'apikey': SUPABASE_ANON_KEY
        },
        body: JSON.stringify({ action: 'callback', code: code, state: state, person_id: personId })
      });
    }).then(function(res) {
      if (!res) return;
      return res.json();
    }).then(function(data) {
      if (!data) return;
      if (data.error) {
        // Surface server error messages (e.g., unsupported_fhir_version, server_misconfigured)
        var msg = data.message || data.error || 'Unknown error';
        showToast('EHR connection failed: ' + msg);
        try { localStorage.removeItem('wellet_ehr_pending_person'); } catch(e) {}
        // Offer the "Let us know" path
        var cbIssue = (data.error === 'unsupported_fhir_version') ? 'unsupported_version' : 'oauth_error';
        var cbHospital = data.hospital_name || '';
        var cbFhir = data.fhir_base_url || null;
        setTimeout(function() {
          openConnectRequestModal({
            source: 'oauth_callback',
            issue_type: cbIssue,
            hospital_name: cbHospital,
            fhir_base_url: cbFhir,
            error_code: data.error,
            error_message: msg,
            person_id: personId
          });
        }, 400);
        return;
      }
      try { localStorage.removeItem('wellet_ehr_pending_person'); } catch(e) {}
      // Make sure the connected person is the one shown on return — otherwise we
      // default to currentPeople[0] (typically Mom/Cheryl) and it looks like the
      // import landed on the wrong person.
      setCurrentPersonId(personId);
      if (typeof loadPersonData === 'function') {
        try { loadPersonData(personId); } catch(e) { console.warn('loadPersonData after EHR callback failed:', e); }
      }
      if (typeof applyPersonBg === 'function') { try { applyPersonBg(personId); } catch(e) {} }
      // Sync the visible person pill so the UI also updates
      try {
        var pills = document.querySelectorAll('.person-pill[data-person-id]');
        pills.forEach(function(p){
          var match = p.getAttribute('data-person-id') === personId;
          p.classList.toggle('active', match);
          p.setAttribute('aria-selected', match ? 'true' : 'false');
        });
      } catch(e) {}
      // If the user is in the multi-source connect flow (Step 5a), route
      // them BACK to the connect screen with the EHR card marked done so
      // they can pick the next source (Apple Health / Devices) or hit
      // "Open my Wellet". This takes priority over the legacy onboarding
      // chat path below.
      if (typeof _isConnectScreenActive === 'function' && _isConnectScreenActive()) {
        showToast('Health records connected!');
        var hospitalCs = data.hospital_name || data.provider || 'your hospital';
        // Kick off the data pull in the background so it's loading while
        // the user picks their next source.
        try { fetchEhrData(personId, true); } catch(_e) {}
        // Re-open the connect screen and refresh status so EHR shows ✓.
        try { showConnectScreen(); } catch(_e) {}
        // Loved-one invite: mark consumed for the caregiver notification.
        try { consumeDsInviteSelf(); } catch (_dsErr) { console.warn('[dsinvite] consume_self failed:', _dsErr); }
        // Clear the legacy onboarding-chat flag if it was also set so it
        // doesn't fire later.
        try { localStorage.removeItem('wellet_ob_ehr_return'); } catch(_e) {}
        return;
      }
      // Check if returning from onboarding EHR connect
      var fromOnboarding = false;
      try { fromOnboarding = localStorage.getItem('wellet_ob_ehr_return') === 'true'; localStorage.removeItem('wellet_ob_ehr_return'); } catch(e) {}
      if (fromOnboarding) {
        showToast('Health records connected!');
        var hospital = data.hospital_name || data.provider || 'your hospital';
        // Loved-one invite consume — fire here too in case the loved one
        // ended up in the onboarding flow rather than the connect screen.
        try { consumeDsInviteSelf(); } catch (_dsErr) { console.warn('[dsinvite] consume_self failed:', _dsErr); }
        // Mark onboarding state so the chat knows EHR is connected (used by
        // obShowConnectChips to hide the already-completed option if the user
        // comes back to it later).
        if (obChat) { obOnEhrConnected(hospital); }
        // Close onboarding chat and drop into the authenticated app, then jump
        // to Records so the user watches their data land.
        showOwnWellet();
        fetchEhrData(personId, true);
        setTimeout(function() { try { switchNavTo('records'); } catch(e) {} }, 300);
        // After a short delay, ask if they'd like a heads-up when new records arrive.
        setTimeout(function() {
          try { promptNewRecordsWatchOptIn(personId, hospital); } catch (_e) {}
        }, 1800);
        return;
      }
      showToast('Health records connected! Fetching data\u2026');
      // Take the user straight to Records so they can watch the data land
      try { switchNavTo('records'); } catch(e) { console.warn('switchNavTo(records) after EHR connect failed:', e); }
      fetchEhrData(personId, true);
      // Loved-one invite: mark consumed so the caregiver gets the connected
      // notification. Fire-and-forget — the loved one is already connected
      // either way.
      try { consumeDsInviteSelf(); } catch (_dsErr) { console.warn('[dsinvite] consume_self failed:', _dsErr); }
      // After a short delay, ask if they'd like a heads-up when new records arrive.
      var _hospitalName = data.hospital_name || data.provider || 'your hospital';
      setTimeout(function() {
        try { promptNewRecordsWatchOptIn(personId, _hospitalName); } catch (_e) {}
      }, 1800);
    }).catch(function(err) {
      console.error('EHR callback error:', err);
      showToast('EHR connection failed');
    });
  }, 500);

  // Timeout after 15 seconds
  setTimeout(function() { clearInterval(checkAuth); }, 15000);
}

// Handle the /epic-callback route specifically
function handleEpicCallback() {
  var path = window.location.pathname;
  if (path === '/epic-callback') {
    handleEhrCallback();
  }
}

// Fetch EHR data from the edge function
function fetchEhrData(personId, navigateToRecords, _retryAttempt) {
  // Surface silent bails — these have historically caused "Refresh doesn't do anything" reports.
  if (isDemoMode) { console.warn('[EHR] fetchEhrData bail: demo mode'); return; }
  if (!currentUser) { console.warn('[EHR] fetchEhrData bail: no currentUser'); try { showToast('Not signed in \u2014 please reload'); } catch(e){} return; }
  if (!personId) { console.warn('[EHR] fetchEhrData bail: no personId'); try { showToast('No person selected'); } catch(e){} return; }
  console.log('[EHR] fetchEhrData START person=' + personId);
  var retryAttempt = _retryAttempt || 0;

  // Sentinel returned by any earlier silent-bail path so the next .then in
  // this chain knows the bail was already handled (toast + status restore
  // already happened) and should NOT show its own "Couldn't reach health
  // records" toast.
  var BAILED = '__bailed__';

  db.auth.getSession().then(function(sessionRes) {
    var session = sessionRes.data.session;
    if (!session) {
      console.warn('[EHR] fetchEhrData bail: no session');
      try { showToast('Session expired \u2014 please reload to sign in'); } catch(e){}
      try { restoreRecordsEhrStatus(); } catch(e){}
      return BAILED;
    }
    return fetch(SUPABASE_URL + '/functions/v1/fetch-ehr-data', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + session.access_token,
        'Content-Type': 'application/json',
        'apikey': SUPABASE_ANON_KEY
      },
      body: JSON.stringify({ person_id: personId })
    });
  }).then(function(res) {
    if (res === BAILED) return BAILED;
    if (!res) return null;
    // 401 + error envelope = every connection failed token refresh.
    // Surface this as a reconnect prompt instead of a generic "couldn't
    // reach health records" toast — the network is fine, the token isn't.
    if (res.status === 401) {
      console.warn('[EHR] fetch-ehr-data 401 \u2014 token refresh failed for all connections');
      try { showToast('Please reconnect your health records to refresh access'); } catch(e){}
      try { restoreRecordsEhrStatus(); } catch(e){}
      try { evaluateReconnectBanner(); } catch(e) {}
      return BAILED;
    }
    // A 404 can happen legitimately (no connection) OR transiently right after a
    // successful OAuth callback (Postgres read-after-write lag on a pooled replica).
    // We never wipe the cache on 404 anymore — that caused the UI to show
    // "Connect Health Records" even when the connection row existed in the DB.
    // Instead: verify with a direct query; retry once after a short delay if a
    // row exists; surface a gentle toast only if the row is truly missing.
    if (res.status === 404) {
      console.warn('[EHR] fetch-ehr-data returned 404 for', personId, 'attempt', retryAttempt);
      // Look directly at ehr_connections to know whether a connection row exists.
      db.from('ehr_connections')
        .select('id, access_token, connected_at')
        .eq('person_id', personId)
        .maybeSingle()
        .then(function(connRes) {
          var hasConn = connRes && connRes.data && connRes.data.access_token;
          if (hasConn && retryAttempt < 2) {
            // Row exists — this was a transient read-after-write race. Retry after a delay.
            var delay = 1500 + retryAttempt * 1500;
            console.log('[EHR] connection row exists; retrying fetch in', delay, 'ms');
            setTimeout(function(){ fetchEhrData(personId, navigateToRecords, retryAttempt + 1); }, delay);
            return;
          }
          if (hasConn) {
            // Row exists but fetch still 404s after retries. Leave cache alone,
            // surface a reconnect suggestion.
            showToast('Records are taking a moment — try again in a few seconds');
            return;
          }
          // No connection row really exists. Only now is it safe to clear cache.
          console.warn('[EHR] no connection row found; clearing cache for', personId);
          clearEhrCache(personId);
          liveMeds = liveMeds.filter(function(m) { return m.source !== 'ehr'; });
          liveAllergies = liveAllergies.filter(function(a) { return a.source !== 'ehr'; });
          liveLabs = liveLabs.filter(function(l) { return l.source !== 'ehr'; });
          if (personId === currentPersonId) { try { renderRecordsView(); } catch(e){} try { renderTimeline(); } catch(e){} }
          try { updateSettingsEhr(); } catch(e){}
          try { updateProfileEhr(personId); } catch(e){}
          try { initIcons(); } catch(e){}
        });
      return BAILED;
    }
    return res.json();
  }).then(function(data) {
    if (data === BAILED) return;
    if (!data || data.error) {
      // PHI log removed
      console.warn('[EHR] fetchEhrData bail: no data or data.error');
      try { showToast("Couldn\u2019t reach health records \u2014 try again"); } catch(e){}
      try { restoreRecordsEhrStatus(); } catch(e){}
      return;
    }
    // Identity safety check: the FHIR Patient returned must match the patient_id
    // stored with this connection. This catches cases where an Epic proxy session
    // or stale browser session caused the OAuth flow to mint a token against the
    // wrong patient (which would silently overwrite the wrong person's cache).
    if (data.expected_patient_id && data.patient && data.patient.id
        && data.patient.id !== data.expected_patient_id) {
      console.warn('EHR identity mismatch', {
        personId: personId,
        expected: data.expected_patient_id,
        returned: data.patient.id,
      });
      showToast('Identity mismatch — please reconnect this person’s record');
      // Do NOT cache — this would overwrite the wrong person
      try { restoreRecordsEhrStatus(); } catch(e){}
      return;
    }
    saveEhrCache(personId, data);
    // Phase 2 dual-write: when the response carries connections[] (v55+),
    // also persist the per-connection v2 shape. v1 stays the source of truth
    // until Phase 2 is on; v2 is read-only until then.
    try { saveEhrCacheV2(personId, data); } catch(e) { console.warn('v2 cache save:', e); }
    // Auto-enable Phase 2 the moment a loved one has 2+ connected hospitals.
    // Single-hospital people stay on the v1 cache (unchanged behavior); the
    // moment a second hospital finishes OAuth, Records/Timeline/Ask Wellet
    // start reading from the merged getMergedEhr view so both hospitals'
    // data shows up. No user action required — the developer-preview toggle
    // becomes a status row at that point. Idempotent: safe to call every sync.
    try {
      if (data && Array.isArray(data.connections) && data.connections.length >= 2) {
        if (!isPhase2Enabled()) {
          localStorage.setItem('welletPhase2', '1');
          if (typeof updatePhase2ToggleUI === 'function') updatePhase2ToggleUI();
        }
      }
    } catch(e) { console.warn('phase2 auto-enable:', e); }
    // Fresh sync just landed — update the masthead label so it says e.g.
    // "Updated just now" (truthfully this time) instead of staying stale.
    try { if (personId === currentPersonId) updateHeaderSyncMeta(); } catch(e) {}
    showToast('Health records updated');
    // Re-render views with EHR data
    if (personId === currentPersonId) {
      renderRecordsView();
      renderTimeline();
      try { evaluateReconnectBanner(); } catch(e) {}
    }
    // Background-fill missing practitioner contact info from public sources
    // (dukehealth.org, NPPES). Render gets re-triggered as each result lands.
    try {
      var ct = (data && data.care_team) || [];
      var prov = (data && (data.provider || {})) || {};
      enrichPractitionersForPerson(personId, ct, prov);
    } catch(e) {}
    // Navigate to Records view after initial EHR connection.
    // C9: On the FIRST successful sync for this person, show a one-time
    // warm welcome screen with what just landed + a chart-aware sentence.
    // The overlay's CTA navigates to Records itself; subsequent syncs skip it.
    //
    // Step 5a exception: if the user is in the multi-source connect flow,
    // ALWAYS show the success popup (with two CTAs: "keep going" / "stop here").
    // The first-sync-seen flag is per-person, but in connect flow each
    // additional source connect deserves its own confirmation \u2014 e.g. user
    // connects EHR (popup), keeps going to connect Apple Health, would still
    // expect a popup confirming what landed.
    if (navigateToRecords) {
      var _inConnectFlowNow = (typeof _isConnectScreenActive === 'function' && _isConnectScreenActive());
      if (_inConnectFlowNow || !hasSeenFirstSync(personId)) {
        try { openFirstSyncWelcome(personId, data); }
        catch (e) { console.warn('first-sync welcome:', e); if (!_inConnectFlowNow) switchNavTo('records'); }
      } else {
        switchNavTo('records');
      }
    }
  }).catch(function(err) {
    console.error('EHR fetch error:', err);
    try { showToast("Couldn\u2019t reach health records \u2014 try again"); } catch(e){}
    try { restoreRecordsEhrStatus(); } catch(e){}
  });
}

// Refresh EHR data (manual button click)
function refreshEhrData() {
  console.log('[EHR] refreshEhrData tapped; isDemoMode=' + isDemoMode + ' currentPersonId=' + currentPersonId + ' currentUser=' + (currentUser ? currentUser.id : 'null'));
  if (isDemoMode) {
    showToast('Demo data refreshed');
    return;
  }
  var personId = currentPersonId;
  if (!personId) { showToast('No person selected \u2014 tap a person pill first'); return; }
  if (!currentUser) { showToast('Not signed in \u2014 please reload'); return; }
  showToast('Refreshing health records\u2026');
  fetchEhrData(personId);
}

// Disconnect EHR
function disconnectEhr() {
  console.log('[EHR] disconnectEhr called, isDemoMode:', isDemoMode, 'currentPersonId:', currentPersonId);
  if (isDemoMode) { showToast('Demo mode — disconnect not available'); return; }
  var personId = currentPersonId;
  if (!personId) { showToast('No person selected'); return; }
  if (!confirm('Disconnect health records? Cached data on this device will be removed.')) return;

  showToast('Disconnecting...');
  clearEhrCache(personId);

  db.auth.getSession().then(function(sessionRes) {
    var session = sessionRes.data.session;
    if (!session) { showToast('Not signed in'); return; }
    return fetch(SUPABASE_URL + '/functions/v1/epic-auth', {
      method: 'POST',
      headers: {
        'Authorization': 'Bearer ' + session.access_token,
        'Content-Type': 'application/json',
        'apikey': SUPABASE_ANON_KEY
      },
      body: JSON.stringify({ action: 'disconnect', person_id: personId })
    });
  }).then(function(resp) {
    console.log('[EHR] disconnect response:', resp && resp.status);
    showToast('Health records disconnected');
    // Clear any remaining in-memory data
    liveMeds = liveMeds.filter(function(m) { return m.source !== 'ehr'; });
    liveAllergies = liveAllergies.filter(function(a) { return a.source !== 'ehr'; });
    liveLabs = liveLabs.filter(function(l) { return l.source !== 'ehr'; });
    renderRecordsView();
    renderTimeline();
    updateSettingsEhr();
    updateProfileEhr(personId);
    initIcons();
  }).catch(function(err) {
    console.error('EHR disconnect error:', err);
    showToast('Disconnect failed — check console');
  });
}

