var currentLang = localStorage.getItem('wellet_lang') || 'en';

function t(key) {
  var dict = TRANSLATIONS[currentLang] || TRANSLATIONS.en;
  return dict[key] || TRANSLATIONS.en[key] || key;
}

// Apply translations to all data-i18n elements in the DOM
function applyI18n() {
  var els = document.querySelectorAll('[data-i18n]');
  for (var i = 0; i < els.length; i++) {
    var key = els[i].getAttribute('data-i18n');
    if (key) els[i].textContent = t(key);
  }
  // Settings title has its own id
  var settingsTitle = document.getElementById('settings-title-el');
  if (settingsTitle) settingsTitle.textContent = t('settings.title');
  // Notif panel title
  var notifTitle = document.getElementById('notif-panel-title');
  if (notifTitle) notifTitle.textContent = t('notif.title');
  // Mark all read button
  var markAllBtn = document.getElementById('notif-mark-all-btn');
  if (markAllBtn) markAllBtn.textContent = t('notif.markAllRead');
}

function setLanguage(lang) {
  currentLang = lang;
  localStorage.setItem('wellet_lang', lang);
  document.documentElement.lang = lang;
  applyI18n();
  refreshCurrentView();
  // Update language picker buttons active state
  var btns = document.querySelectorAll('.lang-pill-btn');
  for (var i = 0; i < btns.length; i++) {
    if (btns[i].dataset.lang === lang) {
      btns[i].classList.add('active');
    } else {
      btns[i].classList.remove('active');
    }
  }
}

function refreshCurrentView() {
  // Update bottom nav labels
  var navBtns = document.querySelectorAll('.nav-item');
  for (var ni = 0; ni < navBtns.length; ni++) {
    var navKey = navBtns[ni].getAttribute('data-nav-key');
    if (navKey) {
      var textNode = navBtns[ni].lastChild;
      if (textNode && textNode.nodeType === 3) textNode.textContent = t(navKey);
    }
  }

  // Update tab labels
  var tabBtns = document.querySelectorAll('.tab[id^="tab-btn-"]');
  var tabKeys = ['tab.update', 'tab.timeline'];
  for (var ti = 0; ti < tabBtns.length; ti++) {
    if (tabKeys[ti]) tabBtns[ti].textContent = t(tabKeys[ti]);
  }

  // Update notification panel title
  var notifTitle = document.getElementById('notif-panel-title');
  if (notifTitle) notifTitle.textContent = t('notif.title');

  // Re-render active view
  var activeView = document.querySelector('.app-view.active');
  if (activeView) {
    var viewId = activeView.id;
    if (viewId === 'view-home') renderUpdateMe();
    else if (viewId === 'view-people') renderPeopleView();
    else if (viewId === 'view-records') renderRecordsView();
    else if (viewId === 'view-signals') renderSignalsView();
    else if (viewId === 'view-resources') renderResourcesView();
    else if (viewId === 'view-ask') renderAskView();
  }
}



// ── VISIT PREP FLOW ─────────────────────────────────────────────────────────
var _vpVisitType = '';         // selected visit type label
var _vpContext = '';           // optional context text
var _vpQuestions = [];         // array of question strings (or grouped objects)
var _vpCheckedState = {};      // { questionIndex: bool }
var _vpCurrentStep = 1;
var _vpIsSaved = false;

// Remove the saved visit-prep for the current loved one. Called from the ×
// dismiss button on the "Resume Visit Prep" card on the Home tab. Confirms
// first because regenerating questions costs an LLM round-trip and the user
// would lose any check-state on the saved list. Storage is client-side
// only (localStorage key `wellet_visit_prep_<personId>`), so this is a
// fully local delete — no Supabase row to clean.
function deleteVisitPrep() {
  if (!currentPersonId) return;
  var key = 'wellet_visit_prep_' + currentPersonId;
  var saved = null;
  try { saved = JSON.parse(localStorage.getItem(key) || 'null'); } catch (e) { saved = null; }
  var label = (saved && saved.visitType) ? saved.visitType : 'this saved prep';
  if (!window.confirm('Remove ' + label + '? You can start a new visit prep anytime.')) return;
  try { localStorage.removeItem(key); } catch (e) {}
  if (typeof renderUpdateMe === 'function') renderUpdateMe();
}
window.deleteVisitPrep = deleteVisitPrep;

function openVisitPrep(resume) {
  var overlay = document.getElementById('visit-prep-overlay');
  if (!overlay) return;

  // Reset state for new prep
  _vpIsSaved = false;
  _vpVisitType = '';
  _vpContext = '';
  _vpCurrentStep = 1;

  var savedBadge = document.getElementById('vp-saved-badge');
  if (savedBadge) savedBadge.style.display = 'none';
  var saveBtn = document.getElementById('vp-save-btn');
  if (saveBtn) { saveBtn.innerHTML = '<i data-lucide="bookmark" style="width:16px;height:16px;"></i> Save for Later'; }

  if (resume && currentPersonId) {
    // Load saved prep and go to results step
    var saved = JSON.parse(localStorage.getItem('wellet_visit_prep_' + currentPersonId) || 'null');
    if (saved && saved.questions && saved.questions.length > 0) {
      _vpVisitType = saved.visitType || '';
      _vpContext = saved.context || '';
      _vpQuestions = saved.questions;
      _vpCheckedState = saved.checkedState || {};
      _vpIsSaved = true;
      vpGoStep(4);
      vpRenderQuestions();
      // Show saved badge
      if (savedBadge) savedBadge.style.display = 'block';
      if (saveBtn) { saveBtn.innerHTML = '<i data-lucide="bookmark-check" style="width:16px;height:16px;"></i> Saved'; }
      overlay.classList.add('show');
      initIcons();
      return;
    }
  }

  // Fresh start: reset step 1 selections
  _vpQuestions = [];
  _vpCheckedState = {};
  var contextInput = document.getElementById('vp-context-input');
  if (contextInput) contextInput.value = '';
  // Clear any selected visit type cards
  var cards = overlay.querySelectorAll('.visit-type-card');
  for (var i = 0; i < cards.length; i++) { cards[i].classList.remove('selected'); }
  vpGoStep(1);
  overlay.classList.add('show');
  initIcons();
}

function closeVisitPrep() {
  var overlay = document.getElementById('visit-prep-overlay');
  if (overlay) overlay.classList.remove('show');
}

function vpGoStep(stepNum) {
  _vpCurrentStep = stepNum;
  var steps = document.querySelectorAll('.vp-step');
  for (var i = 0; i < steps.length; i++) { steps[i].classList.remove('active'); }
  var target = document.getElementById('vp-step-' + stepNum);
  if (target) target.classList.add('active');
  // Scroll sheet to top
  var sheet = document.querySelector('.vp-sheet');
  if (sheet) sheet.scrollTop = 0;
  initIcons();
}

function vpSelectType(visitType, cardEl) {
  _vpVisitType = visitType;
  // Update sub text in step 2
  var sub = document.getElementById('vp-step2-sub');
  if (sub) sub.textContent = visitType + ' — add anything specific you want to ask about (optional)';
  // Move to step 2
  vpGoStep(2);
}

async function vpGenerateQuestions() {
  _vpContext = (document.getElementById('vp-context-input') || {}).value || '';
  // Show loading step
  var firstName = getPersonFirstName();
  var loadingText = document.getElementById('vp-loading-text');
  if (loadingText) loadingText.textContent = 'Wellet is reviewing ' + firstName + '\u2019s records and preparing questions\u2026';
  vpGoStep(3);

  try {
    var questions = [];
    if (isDemoMode) {
      // Demo: wait briefly then return demo questions
      await new Promise(function(resolve) { setTimeout(resolve, 1800); });
      questions = [
        'Blood pressure has been running higher — should we adjust the current medication dosage?',
        'Are there any new treatment options to consider given the current regimen?',
        'What dietary changes or additional monitoring should we do to slow disease progression?',
        'How are current medications interacting with each other, and what side effects should we watch for?',
        'Are there any upcoming screenings or preventive care visits we should schedule?'
      ];
    } else {
      var session = await db.auth.getSession();
      var token = session.data.session ? session.data.session.access_token : '';
      if (!token) throw new Error('Not authenticated');
      var res = await fetch(SUPABASE_URL + '/functions/v1/generate-visit-questions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + token,
          'apikey': SUPABASE_ANON_KEY
        },
        body: JSON.stringify({
          person_id: currentPersonId,
          visit_type: _vpVisitType,
          context: _vpContext
        })
      });
      if (res.ok) {
        var data = await res.json();
        if (data.questions && data.questions.length > 0) {
          questions = data.questions;
        }
      }
      if (questions.length === 0) {
        questions = [
          'What is your assessment of the current health status based on recent records?',
          'Are there any medication adjustments you would recommend?',
          'What follow-up tests or screenings should we schedule?',
          'Are there any lifestyle changes that could improve outcomes?',
          'When should our next appointment be?'
        ];
      }
    }

    _vpQuestions = questions;
    _vpCheckedState = {};
    // Restore saved checkbox state if available
    if (currentPersonId) {
      var saved = JSON.parse(localStorage.getItem('wellet_visit_prep_' + currentPersonId) || 'null');
      if (saved && saved.checkedState) { _vpCheckedState = saved.checkedState; }
    }

    vpRenderQuestions();
    var resultsSub = document.getElementById('vp-results-sub');
    if (resultsSub && _vpVisitType) resultsSub.textContent = _vpVisitType + ' — check off each question as you go';
    vpGoStep(4);
    initIcons();
  } catch (err) {
    console.error('Visit prep error:', err);
    showToast('Something went wrong. Please try again.');
    vpGoStep(2);
  }
}

function vpRenderQuestions() {
  var container = document.getElementById('vp-questions-list');
  if (!container) return;
  var html = '';

  if (_vpQuestions.length === 0) {
    html = '<div style="padding:20px 0;text-align:center;color:var(--text-muted);font-size:var(--type-meta);">No questions generated. Try adding more context.</div>';
    container.innerHTML = html;
    return;
  }

  // Check if questions are grouped objects {category, questions:[]} or flat strings
  var isGrouped = _vpQuestions.length > 0 && typeof _vpQuestions[0] === 'object' && _vpQuestions[0].category;

  if (isGrouped) {
    var qIdx = 0;
    for (var g = 0; g < _vpQuestions.length; g++) {
      var group = _vpQuestions[g];
      html += '<div class="vp-question-group-label">' + escHtml(group.category || '') + '</div>';
      var groupQs = group.questions || [];
      for (var qi = 0; qi < groupQs.length; qi++) {
        var q = groupQs[qi];
        var checked = _vpCheckedState[qIdx] ? ' checked' : '';
        var textClass = _vpCheckedState[qIdx] ? ' class="vp-question-text checked"' : ' class="vp-question-text"';
        html += '<div class="vp-question-item">'
          + '<input type="checkbox" class="vp-question-cb" data-qidx="' + qIdx + '"' + checked + ' onchange="vpToggleCheck(this)">'
          + '<span' + textClass + ' onclick="vpToggleCheckByIdx(' + qIdx + ')">' + escHtml(q) + '</span>'
          + '</div>';
        qIdx++;
      }
    }
  } else {
    for (var i = 0; i < _vpQuestions.length; i++) {
      var qText = typeof _vpQuestions[i] === 'string' ? _vpQuestions[i] : (_vpQuestions[i].text || '');
      var isChecked = _vpCheckedState[i] ? true : false;
      var cbChecked = isChecked ? ' checked' : '';
      var spanClass = isChecked ? ' class="vp-question-text checked"' : ' class="vp-question-text"';
      html += '<div class="vp-question-item">'
        + '<input type="checkbox" class="vp-question-cb" data-qidx="' + i + '"' + cbChecked + ' onchange="vpToggleCheck(this)">'
        + '<span' + spanClass + ' onclick="vpToggleCheckByIdx(' + i + ')">' + escHtml(qText) + '</span>'
        + '</div>';
    }
  }

  container.innerHTML = html;
}

function vpToggleCheck(cbEl) {
  var idx = parseInt(cbEl.getAttribute('data-qidx'), 10);
  _vpCheckedState[idx] = cbEl.checked;
  // Update the text appearance
  var textEl = cbEl.parentElement.querySelector('.vp-question-text');
  if (textEl) {
    if (cbEl.checked) { textEl.classList.add('checked'); } else { textEl.classList.remove('checked'); }
  }
  // Auto-save checked state if already saved
  if (_vpIsSaved && currentPersonId) {
    var saved = JSON.parse(localStorage.getItem('wellet_visit_prep_' + currentPersonId) || 'null');
    if (saved) { saved.checkedState = _vpCheckedState; localStorage.setItem('wellet_visit_prep_' + currentPersonId, JSON.stringify(saved)); }
  }
}

function vpToggleCheckByIdx(idx) {
  var cb = document.querySelector('.vp-question-cb[data-qidx="' + idx + '"]');
  if (cb) { cb.checked = !cb.checked; vpToggleCheck(cb); }
}

function vpGetFlatQuestions() {
  // Returns flat array of question strings regardless of grouping
  var flat = [];
  if (_vpQuestions.length === 0) return flat;
  var isGrouped = typeof _vpQuestions[0] === 'object' && _vpQuestions[0].category;
  if (isGrouped) {
    for (var g = 0; g < _vpQuestions.length; g++) {
      var qs = _vpQuestions[g].questions || [];
      for (var qi = 0; qi < qs.length; qi++) { flat.push(qs[qi]); }
    }
  } else {
    for (var i = 0; i < _vpQuestions.length; i++) {
      flat.push(typeof _vpQuestions[i] === 'string' ? _vpQuestions[i] : (_vpQuestions[i].text || ''));
    }
  }
  return flat;
}

async function vpDownloadPDF() {
  try {
    var firstName = getPersonFirstName();
    var person = isDemoMode ? null : currentPeople.find(function(p){ return p.id === currentPersonId; });
    var fullName = isDemoMode ? 'Patient' : (person ? person.name : 'Patient');

    // Gather medications
    var medications = [];
    if (isDemoMode) {
      medications = [{ name: 'See medical records', dose: '', frequency: '' }];
    } else {
      medications = liveMeds.filter(function(m){ return m.active; }).map(function(m) {
        return { name: m.name, dose: m.dose || '', frequency: m.frequency || '' };
      });
    }

    // Gather recent events (last 90 days)
    var ninetyDaysAgo = new Date();
    ninetyDaysAgo.setDate(ninetyDaysAgo.getDate() - 90);
    var recentEvents = [];
    if (!isDemoMode) {
      recentEvents = liveEvents.filter(function(e) {
        return new Date(e.event_date) >= ninetyDaysAgo;
      }).map(function(e) {
        return {
          date: new Date(e.event_date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }),
          title: e.title || '',
          notes: e.notes || e.description || ''
        };
      });
    }

    // Patterns
    var patterns = [];
    var alertBanner = document.querySelector('.alert-banner');
    if (alertBanner && !isDemoMode) {
      var alertTitle = alertBanner.querySelector('.alert-title');
      var alertBody = alertBanner.querySelector('.alert-body');
      if (alertTitle && alertTitle.textContent) {
        var patternText = alertTitle.textContent;
        if (alertBody && alertBody.textContent) patternText += ' — ' + alertBody.textContent;
        patterns.push(patternText);
      }
    }

    // Emergency contact
    var emergencyContact = '';
    if (!isDemoMode && person) {
      if (person.emergency_contact_name) {
        emergencyContact = person.emergency_contact_name;
        if (person.emergency_contact_phone) emergencyContact += ' · ' + person.emergency_contact_phone;
      } else if (liveCareCircle.length > 0) {
        var primary = liveCareCircle.find(function(c){ return c.role === 'Primary'; }) || liveCareCircle[0];
        emergencyContact = primary.member_name;
        if (primary.phone) emergencyContact += ' · ' + primary.phone;
        if (primary.role) emergencyContact += ' · ' + primary.role;
      }
    }

    var flatQuestions = vpGetFlatQuestions();
    var doc = buildVisitSummaryPDF(fullName, firstName, medications, recentEvents, patterns, emergencyContact, flatQuestions);
    var today = new Date();
    var yyyy = today.getFullYear();
    var mm = String(today.getMonth() + 1).padStart(2, '0');
    var dd = String(today.getDate()).padStart(2, '0');
    var filename = fullName.replace(/\s+/g, '-') + '-Visit-Summary-' + yyyy + '-' + mm + '-' + dd + '.pdf';
    doc.save(filename);
    showToast('Visit Summary downloaded');
  } catch (err) {
    console.error('Visit prep PDF error:', err);
    showToast('Could not generate PDF — please try again');
  }
}

function vpShareWithCareCircle() {
  // Build a share message from the questions
  var flatQuestions = vpGetFlatQuestions();
  var firstName = getPersonFirstName();
  var shareText = 'Preparing for ' + (firstName ? firstName + '\u2019s' : 'upcoming') + ' ' + (_vpVisitType || 'doctor visit') + '. Questions to discuss:\n\n';
  for (var i = 0; i < flatQuestions.length && i < 5; i++) {
    shareText += (i + 1) + '. ' + flatQuestions[i] + '\n';
  }
  // Close visit prep and open share overlay
  closeVisitPrep();
  // Set share preview text if element exists
  var previewEl = document.getElementById('share-preview-text');
  if (previewEl) previewEl.textContent = shareText;
  // Open share overlay
  openShareFamily();
}

function vpSaveForLater() {
  if (!currentPersonId) { showToast('No person selected'); return; }
  var flatQuestions = vpGetFlatQuestions();
  if (flatQuestions.length === 0) { showToast('No questions to save'); return; }

  var saveData = {
    visitType: _vpVisitType,
    context: _vpContext,
    questions: _vpQuestions,
    checkedState: _vpCheckedState,
    savedAt: new Date().toISOString()
  };
  localStorage.setItem('wellet_visit_prep_' + currentPersonId, JSON.stringify(saveData));
  _vpIsSaved = true;

  // Update UI
  var savedBadge = document.getElementById('vp-saved-badge');
  if (savedBadge) savedBadge.style.display = 'block';
  var saveBtn = document.getElementById('vp-save-btn');
  if (saveBtn) {
    saveBtn.innerHTML = '<i data-lucide="bookmark-check" style="width:16px;height:16px;"></i> Saved';
    initIcons();
  }
  showToast('Visit prep saved — find it on Summary');
  // Refresh Summary card in the background
  renderUpdateMe();
}

// ── FIRST-RUN ONBOARDING TOOLTIPS (P2D) ───────────────────────────────────────
var _onboardTooltips = [
  { target: '#tab-btn-update', text: 'Summary is your home base — plain-English updates on what’s changed.' },
  { target: '#nav-ask', text: 'Ask Wellet anything about the health history you’ve captured.' },
  { target: '.nav-item[data-nav-key="nav.signals"]', text: 'CareSignals watches wearables, labs, and patterns for you.' }
];
var _onboardStep = 0;
var _onboardEl = null;

function _showOnboardTooltip(idx) {
  _removeOnboardTooltip();
  if (idx >= _onboardTooltips.length) {
    try { localStorage.setItem('wellet_onboarded', 'true'); } catch(e) {}
    return;
  }
  var cfg = _onboardTooltips[idx];
  var anchor = document.querySelector(cfg.target);
  if (!anchor) { _showOnboardTooltip(idx + 1); return; }
  var rect = anchor.getBoundingClientRect();
  var tip = document.createElement('div');
  tip.className = 'onboard-tooltip';
  tip.textContent = cfg.text;
  tip.style.left = (rect.left + rect.width / 2) + 'px';
  tip.style.top = (rect.top - 54) + 'px';
  document.body.appendChild(tip);
  _onboardEl = tip;
}

function _removeOnboardTooltip() {
  if (_onboardEl) { _onboardEl.remove(); _onboardEl = null; }
}

function _advanceOnboard() {
  _onboardStep++;
  if (_onboardStep < _onboardTooltips.length) {
    _showOnboardTooltip(_onboardStep);
  } else {
    _removeOnboardTooltip();
    try { localStorage.setItem('wellet_onboarded', 'true'); } catch(e) {}
    document.removeEventListener('click', _advanceOnboard);
  }
}

function maybeShowOnboardTooltips() {
  try {
    if (localStorage.getItem('wellet_onboarded') === 'true') return;
  } catch(e) { return; }
  if (isDemoMode) return;
  if (document.getElementById('auth-screen') && document.getElementById('auth-screen').style.display !== 'none') return;
  _onboardStep = 0;
  setTimeout(function() {
    _showOnboardTooltip(0);
    document.addEventListener('click', _advanceOnboard);
  }, 1200);
}

// ── BROWSER BACK BUTTON SUPPORT (pushState / popstate) ────────────────────────
var _navHistoryActive = true;
var _currentNavView = 'home';

// Set initial state so first back press has somewhere to go
history.replaceState({ type: 'tab', view: 'home' }, '');

window.addEventListener('popstate', function(e) {
  var state = e.state;
  if (!state) {
    switchNavTo('home', true);
    return;
  }
  if (state.type === 'sheet') {
    var sheetEl = document.getElementById(state.id);
    if (sheetEl && sheetEl.classList.contains('show')) {
      closeSheetAccessible(state.id);
    }
  } else if (state.type === 'modal') {
    closeModal();
  } else if (state.type === 'tab') {
    switchNavTo(state.view, true);
  } else if (state.type === 'onboarding') {
    var appEl = document.getElementById('app');
    if (appEl && appEl.style.display !== 'none') {
      document.getElementById('onboarding').style.display = 'none';
    }
  }
});

// ── PULL-TO-REFRESH ON HOME TAB ────────────────────────────────────────────
var _ptrStartY = 0;
var _ptrActive = false;
var _ptrRefreshing = false;
var _ptrThreshold = 60;

document.addEventListener('touchstart', function(e) {
  if (_ptrRefreshing) return;
  var homeView = document.getElementById('view-home');
  if (!homeView || !homeView.classList.contains('active')) return;
  if (window.scrollY > 0) return;
  _ptrStartY = e.touches[0].clientY;
  _ptrActive = true;
}, { passive: true });

document.addEventListener('touchmove', function(e) {
  if (!_ptrActive || _ptrRefreshing) return;
  if (window.scrollY > 0) { _ptrActive = false; return; }
  var delta = e.touches[0].clientY - _ptrStartY;
  if (delta < 0) return;
  var indicator = document.getElementById('pull-refresh-indicator');
  if (!indicator) return;
  if (delta > 10) {
    indicator.classList.add('visible');
    var text = indicator.querySelector('.pull-refresh-text');
    if (delta >= _ptrThreshold) {
      if (text) text.textContent = 'Release to refresh';
    } else {
      if (text) text.textContent = 'Pull to refresh';
    }
  }
}, { passive: true });

document.addEventListener('touchend', function() {
  if (!_ptrActive || _ptrRefreshing) return;
  _ptrActive = false;
  var indicator = document.getElementById('pull-refresh-indicator');
  if (!indicator) return;
  if (!indicator.classList.contains('visible')) return;
  var text = indicator.querySelector('.pull-refresh-text');
  if (text && text.textContent === 'Release to refresh') {
    _ptrRefreshing = true;
    indicator.classList.add('refreshing');
    if (text) text.textContent = 'Refreshing\u2026';
    var doRefresh = function() {
      if (currentPersonId && !isDemoMode) {
        loadPersonData(currentPersonId).then(function() {
          renderUpdateMe();
          renderTimeline();
          renderPatterns();
          initIcons();
          _ptrFinish(true);
        }).catch(function() { _ptrFinish(false); });
      } else if (isDemoMode) {
        renderUpdateMe();
        renderTimeline();
        renderPatterns();
        initIcons();
        setTimeout(function() { _ptrFinish(true); }, 600);
      } else {
        _ptrFinish(false);
      }
    };
    doRefresh();
  } else {
    indicator.classList.remove('visible');
  }
}, { passive: true });

// success=true  → sync completed; pull pill says "Updated just now" briefly,
//                 then the masthead label is reconciled to the real synced_at.
// success=false → sync failed or skipped; pull pill says "Couldn't refresh"
//                 briefly, masthead is reconciled to the real (possibly
//                 older) synced_at — never lies about when the last sync was.
function _ptrFinish(success) {
  _ptrRefreshing = false;
  var indicator = document.getElementById('pull-refresh-indicator');
  if (!indicator) return;
  var text = indicator.querySelector('.pull-refresh-text');
  indicator.classList.remove('refreshing');
  if (text) text.textContent = success === false ? "Couldn't refresh" : 'Updated just now';
  // Honest masthead update: reflect actual last successful sync.
  try { updateHeaderSyncMeta(); } catch(e) {}
  setTimeout(function() { indicator.classList.remove('visible'); }, 1200);
}

// ── OFFLINE BANNER + GRACEFUL DEGRADATION ───────────────────────────────
var _wasOffline = !navigator.onLine;

function updateOfflineBanner() {
  var banner = document.getElementById('offline-banner');
  if (!banner) return;
  if (!navigator.onLine) {
    banner.classList.add('visible');
    _wasOffline = true;
    initIcons();
  } else {
    banner.classList.remove('visible');
    if (_wasOffline) {
      _wasOffline = false;
      // Show "back online" confirmation
      var toast = document.createElement('div');
      toast.className = 'back-online-toast';
      toast.innerHTML = '<i data-lucide="wifi" style="width:14px;height:14px;"></i> Back online';
      document.body.appendChild(toast);
      initIcons();
      setTimeout(function() { toast.remove(); }, 2800);
    }
  }
}

window.addEventListener('online', updateOfflineBanner);
window.addEventListener('offline', updateOfflineBanner);
// Check on load
if (!navigator.onLine) updateOfflineBanner();

// ── SKELETON LOADING STATES ──────────────────────────────────────────────
function showSkeletons() {
  var pane = document.getElementById('tab-update');
  if (!pane) return;
  // Save existing content reference for restore
  pane.setAttribute('data-skeleton-active', 'true');
  var skHtml = '<div class="skeleton-wrap">';
  // Mimic update card
  skHtml += '<div class="skeleton-card" style="height:100px;"></div>';
  // Mimic alert card
  skHtml += '<div class="skeleton-card" style="height:64px;"></div>';
  // Mimic quick actions row
  skHtml += '<div style="display:flex;gap:10px;margin-bottom:14px;">';
  skHtml += '<div class="skeleton" style="height:36px;flex:1;"></div>';
  skHtml += '<div class="skeleton" style="height:36px;flex:1;"></div>';
  skHtml += '<div class="skeleton" style="height:36px;flex:1;"></div>';
  skHtml += '</div>';
  // Mimic timeline cards
  skHtml += '<div class="skeleton-card"></div>';
  skHtml += '<div class="skeleton-card"></div>';
  skHtml += '<div class="skeleton-card"></div>';
  skHtml += '</div>';
  pane.innerHTML = skHtml;
}

function hideSkeletons() {
  var pane = document.getElementById('tab-update');
  if (pane) pane.removeAttribute('data-skeleton-active');
}

// ── ANONYMOUS BEHAVIORAL ANALYTICS ───────────────────────────────────────────
// Zero PHI. No names, no health data, no IPs, no fingerprints.
// Captures: navigation flows, feature usage, timing, satisfaction pulses,
//           language, device type, screen size, timezone region.

var _wa = (function() {
  var sessionId = '';
  var queue = [];
  var flushTimer = null;
  var sessionStart = Date.now();
  var lastNav = '';
  var rageClicks = { count: 0, ts: 0, el: '' };
  var meta = {}; // device/language metadata set once per session

  function init() {
    sessionId = crypto.randomUUID ? crypto.randomUUID() : Math.random().toString(36).slice(2) + Date.now().toString(36);
    lastNav = 'home';
    // Collect deidentified metadata once
    var lang = (navigator.language || 'en').substring(0, 2).toLowerCase();
    var w = window.innerWidth || 0;
    var deviceType = w < 768 ? 'mobile' : w < 1024 ? 'tablet' : 'desktop';
    var screenBucket = w < 768 ? 'small' : w < 1024 ? 'medium' : 'large';
    // Coarse timezone region (continent only)
    var tzRegion = 'Unknown';
    try {
      var tz = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
      if (tz.indexOf('America') === 0) tzRegion = 'Americas';
      else if (tz.indexOf('Europe') === 0) tzRegion = 'Europe';
      else if (tz.indexOf('Asia') === 0) tzRegion = 'Asia';
      else if (tz.indexOf('Africa') === 0) tzRegion = 'Africa';
      else if (tz.indexOf('Australia') === 0 || tz.indexOf('Pacific') === 0) tzRegion = 'Oceania';
    } catch(e) {}
    meta = { browser_lang: lang, device_type: deviceType, screen_bucket: screenBucket, timezone_region: tzRegion };
    // Flush on page unload
    window.addEventListener('beforeunload', flush);
    flushTimer = setInterval(flush, 30000);
    document.addEventListener('click', detectRageClick, true);
    document.addEventListener('visibilitychange', function() {
      if (document.hidden) {
        track('session', 'background', { duration_s: Math.round((Date.now() - sessionStart) / 1000) });
        flush();
      }
    });
    track('session', 'start', {});
  }

  function track(type, name, data) {
    if (isDemoMode) return;
    var evt = {
      session_id: sessionId,
      event_type: type,
      event_name: name,
      event_data: data || {},
      person_count: (typeof currentPeople !== 'undefined' && currentPeople) ? currentPeople.length : 0,
      created_at: new Date().toISOString(),
      browser_lang: meta.browser_lang || null,
      device_type: meta.device_type || null,
      screen_bucket: meta.screen_bucket || null,
      timezone_region: meta.timezone_region || null
    };
    queue.push(evt);
    if (queue.length >= 20) flush();
  }

  function flush() {
    if (queue.length === 0) return;
    var batch = queue.splice(0, queue.length);
    if (typeof db !== 'undefined' && db.auth) {
      db.auth.getSession().then(function(res) {
        var s = res.data.session;
        if (!s) return;
        var uid = s.user.id;
        var rows = batch.map(function(e) { e.user_id = uid; return e; });
        db.from('anon_sessions').insert(rows).then(function() {}).catch(function() {});
      }).catch(function() {});
    }
  }

  function detectRageClick(e) {
    var tag = (e.target.tagName || '').toLowerCase();
    var id = e.target.id || e.target.className || tag;
    var now = Date.now();
    if (id === rageClicks.el && now - rageClicks.ts < 1500) {
      rageClicks.count++;
      if (rageClicks.count >= 3) {
        track('frustration', 'rage_click', { element: String(id).substring(0, 60), view: _currentNavView || 'unknown' });
        rageClicks.count = 0;
      }
    } else {
      rageClicks = { count: 1, ts: now, el: id };
    }
  }

  return { init: init, track: track, flush: flush };
})();

// ── SATISFACTION PULSE ────────────────────────────────────────────────────────
var _pulse = (function() {
  var shown = {};
  var SESSION_LIMIT = 2;
  var shownCount = 0;

  function maybeShow(feature, delay) {
    if (isDemoMode) return;
    if (shownCount >= SESSION_LIMIT) return;
    if (shown[feature]) return;
    shown[feature] = true;
    setTimeout(function() { showPulse(feature); }, delay || 3000);
  }

  function showPulse(feature) {
    shownCount++;
    var el = document.createElement('div');
    el.className = 'wellet-pulse-toast';
    el.innerHTML = '<div class="pulse-q">How helpful was this?</div>' +
      '<div class="pulse-btns">' +
      '<button onclick="_pulse.respond(\'' + feature + '\',1,this)" title="Not helpful" aria-label="Not helpful"><i data-lucide="frown"></i></button>' +
      '<button onclick="_pulse.respond(\'' + feature + '\',2,this)" title="Okay" aria-label="Okay"><i data-lucide="meh"></i></button>' +
      '<button onclick="_pulse.respond(\'' + feature + '\',3,this)" title="Very helpful" aria-label="Very helpful"><i data-lucide="smile"></i></button>' +
      '</div>' +
      '<button class="pulse-dismiss" onclick="this.parentNode.remove()" aria-label="Dismiss"><i data-lucide="x"></i></button>';
    document.body.appendChild(el);
    if (typeof initIcons === 'function') initIcons();
    setTimeout(function() { if (el.parentNode) el.remove(); }, 8000);
  }

  function respond(feature, rating, btn) {
    _wa.track('satisfaction', 'pulse_response', { feature: feature, rating: rating });
    var toast = btn.closest('.wellet-pulse-toast');
    if (toast) {
      toast.innerHTML = '<div class="pulse-q" style="padding:8px 0;">Thanks!</div>';
      setTimeout(function() { toast.remove(); }, 1500);
    }
  }

  return { maybeShow: maybeShow, respond: respond };
})();

// ── WISHES v1 ────────────────────────────────────────────────────────────────
// Voice-notes-only. Per loved one. Silent — no prompts. Stored as documents
// with document_type='wish' so the existing transcribe-audio + RLS pipeline
// just works. List sheet (#wishes-list-overlay) and a dedicated record sheet
// (#wish-record-overlay) live in index.html. Recording reuses the same
// MediaRecorder state machine as voice notes via a mode flag, so we don't
// fork the audio pipeline.

var _wishMode = false;           // true while we're recording into a wish
var _wishPersonId = null;        // the person the wish belongs to
var _wishPersonName = '';        // cached display name for sheet titles

async function openWishesList(personId) {
  if (!personId) return;
  _wishPersonId = personId;
  var person = (currentPeople || []).find(function(p){ return p.id === personId; });
  _wishPersonName = person ? (person.name || 'your loved one') : 'your loved one';
  // Demo fallback: the static demo person cards aren't in currentPeople, so map
  // the well-known ids back to the names the rest of the demo uses.
  if ((!person) && isDemoMode) {
    if (personId === 'dad') _wishPersonName = 'Don Bell';
    else if (personId === 'mom') _wishPersonName = 'Margaret Bell';
  }
  var firstName = _wishPersonName.split(' ')[0];
  // "your loved one" should stay intact, not get split to "your".
  if (_wishPersonName === 'your loved one') firstName = 'your loved one';
  var titleEl = document.getElementById('wishes-list-title');
  var subEl = document.getElementById('wishes-list-sub');
  if (titleEl) titleEl.textContent = firstName + '\u2019s wishes';
  if (subEl) subEl.textContent = 'What ' + firstName + ' wants. In their words, kept safe for the people who need to hear it.';
  var body = document.getElementById('wishes-list-body');
  if (body) body.innerHTML = '<div style="padding:24px 4px;font-size:var(--type-meta);color:var(--text-muted);font-style:italic;">Loading\u2026</div>';
  try { openSheetAccessible('wishes-list-overlay'); } catch (e) { var ov = document.getElementById('wishes-list-overlay'); if (ov) ov.classList.add('show'); }
  initIcons();
  await renderWishesList(personId);
}

function closeWishesList() {
  try { closeSheet('wishes-list-overlay'); } catch (e) {
    var ov = document.getElementById('wishes-list-overlay');
    if (ov) ov.classList.remove('show');
  }
}

async function renderWishesList(personId) {
  var body = document.getElementById('wishes-list-body');
  if (!body) return;

  // Two sources, unioned + sorted by most recent:
  //   1. Voice-recorded wishes: rows in `documents` with document_type='wish'
  //   2. AI-surfaced wishes:    rows in `wishes` table from extract-wishes edge fn
  // Demo mode keeps the original soft demo content so reviewers see something populated.
  var voiceWishes = [];
  var aiWishes = [];

  if (isDemoMode) {
    voiceWishes = _demoWishesFor(personId);
    // Show an AI-surfaced wish for Dad so reviewers see the full Wishes surface.
    if (personId === 'dad' || personId === null || personId === undefined) {
      if (typeof _demoAiWishForDad === 'function') aiWishes = [_demoAiWishForDad()];
    }
  } else {
    try {
      var both = await Promise.all([
        db.from('documents')
          .select('id, file_name, document_type, extracted_events, extraction_status, uploaded_at')
          .eq('person_id', personId)
          .eq('document_type', 'wish')
          .order('uploaded_at', { ascending: false }),
        db.from('wishes')
          .select('id, content, category, source_type, source_id, source_quote, confidence, status, created_at')
          .eq('person_id', personId)
          .neq('status', 'archived')
          .order('created_at', { ascending: false })
          .limit(200)
      ]);
      if (!both[0].error && both[0].data) voiceWishes = both[0].data;
      if (!both[1].error && both[1].data) aiWishes = both[1].data;
    } catch (e) { /* leave empty rather than crash */ }
  }

  if (!voiceWishes.length && !aiWishes.length) {
    body.innerHTML = '<div style="text-align:center;padding:32px 12px;">'
      + '<div style="font-size:var(--type-display);opacity:0.25;margin-bottom:12px;"><i data-lucide="heart" style="width:32px;height:32px;"></i></div>'
      + '<div style="font-family:var(--serif),serif;font-style:italic;color:var(--moss-dark);font-size:var(--type-body);line-height:1.55;max-width:34ch;margin:0 auto 10px;">Nothing recorded yet.</div>'
      + '<div style="font-size:var(--type-meta);color:var(--text-muted);line-height:1.6;max-width:36ch;margin:0 auto;">When ' + escHtml(_wishPersonName === 'your loved one' ? 'they' : _wishPersonName.split(' ')[0]) + ' tells you something they want \u2014 a song at the funeral, no more chemo, who should make decisions \u2014 capture it here, in their words.</div>'
      + '</div>';
    initIcons();
    return;
  }

  // Normalize both sources into one render-ready array with a common timestamp.
  var rows = [];
  voiceWishes.forEach(function(w) {
    var ts = w.uploaded_at ? new Date(w.uploaded_at).getTime() : 0;
    rows.push({ kind: 'voice', ts: ts, data: w });
  });
  aiWishes.forEach(function(w) {
    var ts = w.created_at ? new Date(w.created_at).getTime() : 0;
    rows.push({ kind: 'ai', ts: ts, data: w });
  });
  rows.sort(function(a, b) { return b.ts - a.ts; });

  var html = '';
  rows.forEach(function(row) {
    if (row.kind === 'voice') html += _renderVoiceWishRow(row.data);
    else html += _renderAiWishRow(row.data);
  });
  body.innerHTML = html;
  initIcons();
}

function _renderVoiceWishRow(w) {
  var ts = w.uploaded_at ? new Date(w.uploaded_at) : null;
  var dateStr = ts ? ts.toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' }) : '';
  var transcript = '';
  try {
    var ee = w.extracted_events;
    if (ee && typeof ee === 'object') {
      if (typeof ee.transcript === 'string') transcript = ee.transcript;
      else if (typeof ee.text === 'string') transcript = ee.text;
      else if (typeof ee.summary === 'string') transcript = ee.summary;
    }
  } catch (e) {}
  var status = w.extraction_status || '';
  var statusBadge = '';
  if (status === 'pending' || status === 'processing') {
    statusBadge = '<span style="font-size:var(--type-micro);color:var(--text-muted);font-style:italic;">Transcribing\u2026</span>';
  } else if (status === 'failed') {
    statusBadge = '<span style="font-size:var(--type-micro);color:#C0392B;">Transcription failed</span>';
  }
  var bodyText = transcript
    ? '<p style="font-family:var(--serif),serif;font-style:italic;color:var(--text-primary);font-size:var(--type-body);line-height:1.55;margin:6px 0 0;">\u201C' + escHtml(transcript) + '\u201D</p>'
    : (statusBadge ? '<div style="margin-top:6px;">' + statusBadge + '</div>' : '<div style="margin-top:6px;font-size:var(--type-micro);color:var(--text-muted);font-style:italic;">Voice recording \u00b7 transcript pending</div>');
  return '<div style="padding:14px 4px;border-top:1px solid var(--border, #ECE8DC);">'
    + '<div style="display:flex;align-items:center;gap:8px;">'
    +   '<i data-lucide="heart" style="width:13px;height:13px;color:var(--moss);"></i>'
    +   '<span style="font-size:var(--type-micro);letter-spacing:0.06em;text-transform:uppercase;color:var(--moss-dark);font-weight:500;">Wish</span>'
    +   '<span style="font-size:var(--type-micro);color:var(--text-muted);margin-left:auto;">' + escHtml(dateStr) + '</span>'
    + '</div>'
    + bodyText
    + '</div>';
}

function _renderAiWishRow(w) {
  var ts = w.created_at ? new Date(w.created_at) : null;
  var dateStr = ts ? ts.toLocaleDateString([], { month: 'short', day: 'numeric', year: 'numeric' }) : '';
  var category = (w.category || 'other').replace(/_/g, ' ');
  var conf = (w.confidence || 'low').toLowerCase();
  var status = (w.status || 'suggested').toLowerCase();
  var isSuggested = status === 'suggested';
  var isConfirmed = status === 'confirmed';
  var pillBg = conf === 'high' ? '#DDE7C7' : (conf === 'medium' ? '#F0E5C8' : '#EADFD2');
  var pillFg = conf === 'high' ? '#4E5A3C' : (conf === 'medium' ? '#6B5A2A' : '#6B4A2A');
  var eyebrowLabel = isConfirmed ? 'Confirmed wish' : (status === 'suggested' ? 'Surfaced from records' : 'Wish');

  var actionRow = '';
  if (isSuggested) {
    actionRow = '<div style="display:flex;gap:6px;margin-top:10px;flex-wrap:wrap;">'
      + '<button class="ai-wish-chip ai-wish-confirm" onclick="confirmAiWish(\'' + escHtml(w.id) + '\')" '
      +   'style="font:inherit;font-size:var(--type-micro);padding:5px 12px;border-radius:99px;border:1px solid var(--moss);background:var(--moss);color:#fff;cursor:pointer;">Confirm</button>'
      + '<button class="ai-wish-chip ai-wish-edit" onclick="editAiWish(\'' + escHtml(w.id) + '\')" '
      +   'style="font:inherit;font-size:var(--type-micro);padding:5px 12px;border-radius:99px;border:1px solid var(--border, #ECE8DC);background:transparent;color:var(--moss-dark);cursor:pointer;">Edit</button>'
      + '<button class="ai-wish-chip ai-wish-archive" onclick="archiveAiWish(\'' + escHtml(w.id) + '\')" '
      +   'style="font:inherit;font-size:var(--type-micro);padding:5px 12px;border-radius:99px;border:1px solid var(--border, #ECE8DC);background:transparent;color:var(--text-muted);cursor:pointer;">Archive</button>'
      + '</div>';
  }

  var quoteBlock = w.source_quote
    ? '<div style="font-family:var(--serif),serif;font-style:italic;font-size:var(--type-meta);line-height:1.55;color:var(--moss-dark);background:#F6F3E8;border-left:3px solid var(--moss);padding:8px 12px;border-radius:0 6px 6px 0;margin-top:8px;">\u201C' + escHtml(w.source_quote) + '\u201D</div>'
    : '';

  return '<div data-ai-wish-id="' + escHtml(w.id) + '" style="padding:14px 4px;border-top:1px solid var(--border, #ECE8DC);' + (isSuggested ? '' : 'opacity:0.95;') + '">'
    + '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'
    +   '<i data-lucide="' + (isConfirmed ? 'heart' : 'sparkles') + '" style="width:13px;height:13px;color:var(--moss);"></i>'
    +   '<span style="font-size:var(--type-micro);letter-spacing:0.06em;text-transform:uppercase;color:var(--moss-dark);font-weight:500;">' + escHtml(eyebrowLabel) + '</span>'
    +   '<span style="font-size:var(--type-micro);padding:1px 8px;border-radius:99px;background:#F0EDE0;color:var(--moss-dark);">' + escHtml(category) + '</span>'
    +   '<span style="font-size:var(--type-micro);padding:1px 8px;border-radius:99px;background:' + pillBg + ';color:' + pillFg + ';">' + escHtml(conf) + '</span>'
    +   '<span style="font-size:var(--type-micro);color:var(--text-muted);margin-left:auto;">' + escHtml(dateStr) + '</span>'
    + '</div>'
    + '<p style="font-family:var(--serif),serif;font-style:italic;color:var(--text-primary);font-size:var(--type-body);line-height:1.55;margin:8px 0 0;">' + escHtml(w.content || '') + '</p>'
    + quoteBlock
    + actionRow
    + '</div>';
}

// ── AI WISH ACTIONS ──────────────────────────────────────────────────────────

async function confirmAiWish(wishId) {
  if (!wishId) return;
  try {
    var res = await db.from('wishes')
      .update({ status: 'confirmed', confirmed_at: new Date().toISOString() })
      .eq('id', wishId)
      .select('id')
      .maybeSingle();
    if (res.error) { showToast('Could not confirm'); return; }
    showToast('Confirmed');
    if (_wishPersonId) await renderWishesList(_wishPersonId);
  } catch (e) { showToast('Could not confirm'); }
}

async function archiveAiWish(wishId) {
  if (!wishId) return;
  if (!confirm('Archive this wish? You can still see it in the database, but it will be hidden from this list.')) return;
  try {
    var res = await db.from('wishes')
      .update({ status: 'archived' })
      .eq('id', wishId)
      .select('id')
      .maybeSingle();
    if (res.error) { showToast('Could not archive'); return; }
    showToast('Archived');
    if (_wishPersonId) await renderWishesList(_wishPersonId);
  } catch (e) { showToast('Could not archive'); }
}

async function editAiWish(wishId) {
  if (!wishId) return;
  try {
    var cur = await db.from('wishes')
      .select('content')
      .eq('id', wishId)
      .maybeSingle();
    if (cur.error || !cur.data) { showToast('Could not load'); return; }
    var next = prompt('Edit the wish in their words:', cur.data.content || '');
    if (next === null) return;
    var trimmed = String(next).trim();
    if (!trimmed) { showToast('Wish cannot be empty'); return; }
    if (trimmed === cur.data.content) return;
    var res = await db.from('wishes')
      .update({ content: trimmed.slice(0, 280) })
      .eq('id', wishId)
      .select('id')
      .maybeSingle();
    if (res.error) { showToast('Could not save'); return; }
    showToast('Saved');
    if (_wishPersonId) await renderWishesList(_wishPersonId);
  } catch (e) { showToast('Could not save'); }
}

// Calls the extract-wishes edge function for the currently open loved one,
// throttled to once per 24h per person via localStorage. The button shows
// remaining wait time when throttled.
async function surfaceWishesFromRecords() {
  if (!_wishPersonId) { showToast('Open a profile first'); return; }
  if (isDemoMode) { showToast('Demo mode \u2014 not available'); return; }
  var throttleKey = 'wellet:surface-wishes:' + _wishPersonId;
  var last = 0;
  try { last = parseInt(localStorage.getItem(throttleKey) || '0', 10) || 0; } catch (e) {}
  var hoursSince = (Date.now() - last) / (3600 * 1000);
  if (hoursSince < 24) {
    var hoursLeft = Math.ceil(24 - hoursSince);
    showToast('Already checked today \u2014 try again in ' + hoursLeft + 'h');
    return;
  }

  var btn = document.getElementById('surface-wishes-btn');
  var originalHtml = btn ? btn.innerHTML : '';
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '<i data-lucide="loader-2" style="width:16px;height:16px;"></i> Reading records\u2026';
    initIcons();
  }

  try {
    var session = null;
    try { var s = await db.auth.getSession(); session = s && s.data ? s.data.session : null; } catch (e) {}
    if (!session) { showToast('Sign in first'); return; }

    var resp = await fetch(SUPABASE_URL + '/functions/v1/extract-wishes', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer ' + session.access_token,
        'apikey': SUPABASE_ANON_KEY
      },
      body: JSON.stringify({ person_id: _wishPersonId })
    });
    var json = null;
    try { json = await resp.json(); } catch (e) {}
    if (!resp.ok) {
      showToast('Could not read records');
      return;
    }
    try { localStorage.setItem(throttleKey, String(Date.now())); } catch (e) {}
    var added = (json && typeof json.suggested === 'number') ? json.suggested : 0;
    if (added > 0) {
      showToast('Surfaced ' + added + ' new ' + (added === 1 ? 'wish' : 'wishes'));
    } else {
      showToast('Nothing new surfaced');
    }
    await renderWishesList(_wishPersonId);
  } catch (e) {
    showToast('Could not read records');
  } finally {
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = originalHtml;
      initIcons();
    }
  }
}

function _demoWishesFor(personId) {
  // Two soft wishes per demo person so reviewers see the feature populated.
  // One AI-surfaced wish is included to show the wish-extraction feature.
  var now = Date.now();
  var d = function(daysAgo) { return new Date(now - daysAgo * 24 * 3600 * 1000).toISOString(); };
  if (personId === 'dad' || personId === null || personId === undefined) {
    // voiceWishes returned as document-shaped objects; aiWish matches the `wishes` table shape
    var dadVoice = [
      { id: 'w-dad-1', document_type: 'wish', extraction_status: 'completed', uploaded_at: d(12), extracted_events: { transcript: 'He said again today: no more hospitals if it gets to that. He wants to be home, with the dog, with the windows open.' } },
      { id: 'w-dad-2', document_type: 'wish', extraction_status: 'completed', uploaded_at: d(34), extracted_events: { transcript: 'Wants Joanne to make medical decisions, not the kids. He was very clear about it.' } }
    ];
    // _renderWishesList merges voice + ai rows by kind; return voice wishes only from this
    // function. The AI wish is injected directly inside renderWishesList for demo mode.
    return dadVoice;
  }
  if (personId === 'mom') {
    return [
      { id: 'w-mom-1', document_type: 'wish', extraction_status: 'completed', uploaded_at: d(5), extracted_events: { transcript: 'She wants her gardening books donated to the library when the time comes. Specifically the rose ones.' } }
    ];
  }
  return [];
}

// AI-surfaced demo wish — shown for Dad to demonstrate the AI wish-extraction feature.
// Shape matches the `wishes` table (used by _renderAiWishRow).
function _demoAiWishForDad() {
  var now = Date.now();
  var d = function(daysAgo) { return new Date(now - daysAgo * 24 * 3600 * 1000).toISOString(); };
  return {
    id: 'w-dad-ai-1',
    content: 'No aggressive interventions. He wants comfort care if the CML progresses beyond remission.',
    category: 'end_of_life',
    source_type: 'ai_extracted',
    source_quote: 'I’ve had a good run. If the leukemia comes back hard, I don’t want them doing heroics.',
    confidence: 'high',
    status: 'suggested',
    created_at: d(7)
  };
}

// ── WISH RECORDING ───────────────────────────────────────────────────────────
// Reuses the same MediaRecorder state machine as voice notes (_vrMediaRecorder,
// _vrChunks, _vrIsRecording, _vrSeconds, _vrTimerInterval, _vrCancelled). The
// difference is purely cosmetic UI + a flag that diverts the upload destination.

function startWishRecording() {
  if (!_wishPersonId) { showToast('Open a profile first'); return; }
  _wishMode = true;
  try { openSheetAccessible('wish-record-overlay'); } catch (e) {
    var ov = document.getElementById('wish-record-overlay'); if (ov) ov.classList.add('show');
  }
  initIcons();
  _vrSeconds = 0;
  _vrIsRecording = false;
  _vrCancelled = false;
  _vrChunks = [];
  var timerEl = document.getElementById('wish-record-timer');
  var statusEl = document.getElementById('wish-record-status');
  var stopBtn = document.getElementById('wish-stop-btn');
  var processingEl = document.getElementById('wish-processing');
  var recordBtn = document.getElementById('wish-record-btn');
  if (timerEl) timerEl.textContent = '0:00';
  if (statusEl) statusEl.textContent = 'Tap to start recording';
  if (stopBtn) stopBtn.style.display = 'none';
  if (processingEl) processingEl.style.display = 'none';
  if (recordBtn) { recordBtn.style.background = 'var(--moss)'; recordBtn.disabled = false; }
}

function cancelWishRecording() {
  _vrCancelled = true;
  if (_vrMediaRecorder && _vrMediaRecorder.state !== 'inactive') {
    try { _vrMediaRecorder.stop(); } catch (e) {}
  }
  if (_vrTimerInterval) { clearInterval(_vrTimerInterval); _vrTimerInterval = null; }
  _vrIsRecording = false;
  _vrChunks = [];
  _wishMode = false;
  try { closeSheet('wish-record-overlay'); } catch (e) {
    var ov = document.getElementById('wish-record-overlay'); if (ov) ov.classList.remove('show');
  }
}

function toggleWishRecording() {
  if (_vrIsRecording) {
    finishWishRecording();
  } else {
    _startWishMediaRecording();
  }
}

function _startWishMediaRecording() {
  if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) { showToast('Microphone not available on this device'); return; }
  if (typeof MediaRecorder === 'undefined') { showToast('Voice recording isn\u2019t supported in this browser. Try Safari or Chrome.'); return; }
  navigator.mediaDevices.getUserMedia({ audio: true }).then(function(stream) {
    _vrChunks = [];
    _vrSeconds = 0;
    _vrIsRecording = true;
    var statusEl = document.getElementById('wish-record-status');
    var stopBtn = document.getElementById('wish-stop-btn');
    var timerEl = document.getElementById('wish-record-timer');
    var recordBtn = document.getElementById('wish-record-btn');
    if (statusEl) statusEl.textContent = 'Recording\u2026';
    if (stopBtn) stopBtn.style.display = 'block';
    if (recordBtn) recordBtn.style.background = 'var(--moss-dark)';
    _vrTimerInterval = setInterval(function() {
      _vrSeconds++;
      var m = Math.floor(_vrSeconds / 60);
      var s = _vrSeconds % 60;
      if (timerEl) timerEl.textContent = m + ':' + (s < 10 ? '0' : '') + s;
    }, 1000);
    _vrCancelled = false;
    var chosenMime = _pickRecorderMimeType();
    try {
      _vrMediaRecorder = chosenMime ? new MediaRecorder(stream, { mimeType: chosenMime }) : new MediaRecorder(stream);
    } catch (ctorErr) {
      try { _vrMediaRecorder = new MediaRecorder(stream); }
      catch (fatal) {
        stream.getTracks().forEach(function(t) { t.stop(); });
        if (_vrTimerInterval) { clearInterval(_vrTimerInterval); _vrTimerInterval = null; }
        _vrIsRecording = false;
        showToast('Voice recording isn\u2019t supported in this browser. Try Safari or Chrome.');
        return;
      }
    }
    _vrMediaRecorder.ondataavailable = function(e) {
      if (e.data && e.data.size > 0) _vrChunks.push(e.data);
      try {
        var st = document.getElementById('wish-record-status');
        if (st && _vrIsRecording) {
          var totalBytes = _vrChunks.reduce(function(a,c){ return a + (c.size||0); }, 0);
          st.textContent = 'Recording\u2026 ' + Math.round(totalBytes/1024) + ' KB';
        }
      } catch (er) {}
    };
    _vrMediaRecorder.onstop = function() {
      stream.getTracks().forEach(function(t) { t.stop(); });
      if (_vrCancelled) { _vrChunks = []; return; }
      setTimeout(function() { _uploadWishRecording(); }, 250);
    };
    try { _vrMediaRecorder.start(1000); }
    catch (startErr) {
      try { _vrMediaRecorder.start(); }
      catch (startFatal) {
        stream.getTracks().forEach(function(t) { t.stop(); });
        if (_vrTimerInterval) { clearInterval(_vrTimerInterval); _vrTimerInterval = null; }
        _vrIsRecording = false;
        showToast('Could not start recording. Try closing other apps using the microphone.');
        return;
      }
    }
  }).catch(function(err) {
    var msg = (err && err.message) || String(err);
    if (err && (err.name === 'NotAllowedError' || /permission|denied/i.test(msg))) {
      showToast('Microphone permission is blocked. Open iOS Settings \u2192 Wellet \u2192 Microphone.');
    } else if (err && err.name === 'NotFoundError') {
      showToast('No microphone found on this device.');
    } else {
      showToast('Could not access microphone: ' + msg);
    }
  });
}

function finishWishRecording() {
  if (!_vrIsRecording) return;
  _vrIsRecording = false;
  if (_vrTimerInterval) { clearInterval(_vrTimerInterval); _vrTimerInterval = null; }
  if (_vrMediaRecorder && _vrMediaRecorder.state !== 'inactive') {
    try { if (typeof _vrMediaRecorder.requestData === 'function') _vrMediaRecorder.requestData(); } catch (e) {}
    try { _vrMediaRecorder.stop(); } catch (e) { _uploadWishRecording(); }
  } else {
    _uploadWishRecording();
  }
}

async function _uploadWishRecording() {
  var processingEl = document.getElementById('wish-processing');
  var processingLabel = document.getElementById('wish-processing-label');
  var stopBtn = document.getElementById('wish-stop-btn');
  if (processingEl) processingEl.style.display = 'block';
  if (stopBtn) stopBtn.style.display = 'none';
  var setProgress = function(msg) { if (processingLabel) processingLabel.textContent = msg; };

  try {
    if (!_vrChunks || _vrChunks.length === 0) {
      throw new Error('No audio was captured. Check that microphone access is allowed in Settings \u2192 Wellet \u2192 Microphone, then try again.');
    }
    if (!_wishPersonId) {
      throw new Error('No person selected.');
    }

    var mimeType = (_vrMediaRecorder && _vrMediaRecorder.mimeType) || _vrChunks[0].type || 'audio/webm';
    var baseMime = mimeType.split(';')[0].trim();
    var extMap = { 'audio/webm': 'webm', 'audio/mp4': 'm4a', 'audio/mpeg': 'mp3', 'audio/ogg': 'ogg', 'audio/wav': 'wav' };
    var ext = extMap[baseMime] || 'webm';
    var blob = new Blob(_vrChunks, { type: baseMime });
    if (blob.size < 2048) throw new Error('Recording was too short. Try again and speak for a few seconds.');

    setProgress('Saving wish\u2026');
    var sessionRes = await db.auth.getSession();
    var session = sessionRes && sessionRes.data && sessionRes.data.session;
    if (!session) throw new Error('Your session expired. Please sign in again.');
    var userId = session.user.id;
    var token = session.access_token;

    var ts = Date.now();
    var fileName = 'Wish \u2014 ' + new Date(ts).toLocaleString([], { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }) + '.' + ext;
    // RLS requires first folder = auth.uid()
    var storagePath = userId + '/wishes/' + _wishPersonId + '/' + ts + '.' + ext;

    var uploadRes = await db.storage.from('documents').upload(storagePath, blob, { contentType: baseMime, upsert: false });
    if (uploadRes.error) throw new Error('Upload failed: ' + uploadRes.error.message);

    setProgress('Creating entry\u2026');
    var insertRes = await db.from('documents').insert({
      person_id: _wishPersonId,
      file_name: fileName,
      storage_path: storagePath,
      document_type: 'wish',
      extraction_status: 'pending'
    }).select().single();
    if (insertRes.error || !insertRes.data) {
      try { await db.storage.from('documents').remove([storagePath]); } catch (e) {}
      throw new Error('Could not save wish: ' + (insertRes.error && insertRes.error.message || 'unknown'));
    }
    var docId = insertRes.data.id;

    setProgress('Transcribing\u2026');
    var controller = new AbortController();
    var timeoutId = setTimeout(function() { controller.abort(); }, 60000);
    try {
      await fetch('https://nrpdhxygzyfmyljzfexv.supabase.co/functions/v1/transcribe-audio', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + token, 'apikey': SUPABASE_ANON_KEY },
        body: JSON.stringify({ document_id: docId, storage_path: storagePath }),
        signal: controller.signal
      });
    } catch (netErr) {
      // Saved fine, transcription still running. We'll see it on next list refresh.
    }
    clearTimeout(timeoutId);

    if (processingEl) processingEl.style.display = 'none';
    try { closeSheet('wish-record-overlay'); } catch (e) {
      var ov = document.getElementById('wish-record-overlay'); if (ov) ov.classList.remove('show');
    }
    _wishMode = false;
    showToast('Wish saved');
    // Refresh the wishes list under it.
    if (_wishPersonId) await renderWishesList(_wishPersonId);
  } catch (err) {
    if (processingEl) processingEl.style.display = 'none';
    if (stopBtn) stopBtn.style.display = 'block';
    showToast(err && err.message ? err.message : 'Could not save wish');
    _wishMode = false;
  }
}

